25	/**
26	 * A person on a sheet, with a name (unique on the sheet, ignoring case) and a dated grade (one of the sheet's grades): each grade
27	 * applies from its from-date, the first one given from the beginning of time; and the terms of their own, if any,
28	 * from the beginning of time and from their from-dates.
29	 */
30	@Entity
31	@Table(name = "person")
32	public class Person {
33	
34	    @Id
35	    @GeneratedValue(strategy = GenerationType.IDENTITY)
36	    private Long id;
37	
38	    @Column(name = "sheet_id", nullable = false)
39	    private String sheetId;
40	
41	    @Column(name = "name", nullable = false)
42	    private String name;
43	
44	    @ElementCollection(fetch = FetchType.EAGER)
45	    @CollectionTable(name = "person_grade", joinColumns = @JoinColumn(name = "person_id"))
46	    private List<DatedGrade> grades = new ArrayList<>();
47	
48	    /** The person's place in the sheet's list, smallest first. */
49	    @Column(name = "list_position", nullable = false)
50	    private long position;
51	
52	    /** The person's own terms from the beginning of time; null: none. */
53	    @Column(name = "terms")
54	    private Integer terms;
55	
56	    @ElementCollection(fetch = FetchType.EAGER)
57	    @CollectionTable(name = "person_terms", joinColumns = @JoinColumn(name = "person_id"))
58	    private List<DatedTerms> datedTerms = new ArrayList<>();
59	
60	    /** The person's contact, without surrounding spaces and lower-cased; null: none. */
61	    @Column(name = "contact")
62	    private String contact;
63	
64	    /** The person's tags, sorted and comma separated; null for a person with none. */
65	    @Column(name = "tags")
66	    private String tags;
67	
68	    @Column(name = "retired_from")
69	    private LocalDate retiredFrom;
70	
71	    /** The sheet the person was transferred from; null: not transferred. */
72	    @Column(name = "origin_sheet")
73	    private String originSheet;
74	
75	    /** The sheet's today when the person arrived by transfer; null: not transferred, or before that was kept. */
76	    @Column(name = "arrived_on")
77	    private LocalDate arrivedOn;
78	
79	    /** The user who transferred the person here; null: not transferred, or before that was kept. */
80	    @Column(name = "arrived_by")
81	    private String arrivedBy;
82	
83	    /** The sheet's today when the person was added; null: before that was kept. */
84	    @Column(name = "added_on")
85	    private LocalDate addedOn;
86	
87	    /** The sheet's today when the retirement date was set; null: before that was kept, or not retired. */
88	    @Column(name = "retired_on")
89	    private LocalDate retiredOn;
90	
91	    /** The reason a steward flagged the person; null: never flagged. */
92	    @Column(name = "flag_reason")
93	    private String flagReason;
94	
95	    /** The last day the person's flag is in force; null: never flagged. */
96	    @Column(name = "flag_until")
97	    private LocalDate flagUntil;
98	
99	    /** The user who may approve or reject the person's PENDING claims as a steward may; null: none. */
100	    @Column(name = "approver")
101	    private String approver;
102	
103	    @ElementCollection(fetch = FetchType.EAGER)
104	    @CollectionTable(name = "person_hold", joinColumns = @JoinColumn(name = "person_id"))
105	    private List<DatedHold> holds = new ArrayList<>();
106	
107	    /** The retirements the person was unretired from. */
108	    @ElementCollection(fetch = FetchType.EAGER)
109	    @CollectionTable(name = "person_retirement", joinColumns = @JoinColumn(name = "person_id"))
110	    private List<PastRetirement> pastRetirements = new ArrayList<>();
111	
112	    @ElementCollection(fetch = FetchType.EAGER)
113	    @CollectionTable(name = "person_alias", joinColumns = @JoinColumn(name = "person_id"))
114	    private List<PersonAlias> aliases = new ArrayList<>();
115	
116	    @Version
117	    @Column(name = "version", nullable = false)
118	    private long version;
119	
120	    protected Person() {
121	    }
122	
123	    public Person(String sheetId, String name, String grade) {
124	        this(sheetId, name, grade, null);
125	    }
126	
127	    /** A person added while the sheet's today was the date. */
128	    public Person(String sheetId, String name, String grade, LocalDate addedOn) {
129	        this.sheetId = sheetId;
130	        this.name = name;
131	        this.addedOn = addedOn;
132	        this.grades.add(new DatedGrade(grade, null, addedOn));
133	    }
134	
135	    /**
136	     * The person as they stood at the end of the day, for figures taken as of it: only the grades, holds and
137	     * retirement recorded while the sheet's today was on or before the day. Not to be saved.
138	     */
139	    public Person asOf(LocalDate day) {
140	        Person then = new Person();
141	        then.id = id;
142	        then.sheetId = sheetId;
143	        then.name = name;
144	        then.position = position;
145	        then.originSheet = originSheet;
146	        then.terms = terms;
147	        datedTerms.stream().filter(t -> t.madeBy(day)).forEach(then.datedTerms::add);
148	        then.addedOn = addedOn;
149	        then.version = version;
150	        grades.stream().filter(g -> g.madeBy(day)).forEach(then.grades::add);
151	        if (then.grades.isEmpty()) {
152	            // the first grade they were given stands for them
153	            grades.stream().filter(g -> g.getFrom() == null).forEach(then.grades::add);
154	        }
155	        holds.stream().filter(h -> h.madeBy(day)).forEach(then.holds::add);
156	        then.aliases.addAll(aliases);
157	        if (retiredOn == null || !retiredOn.isAfter(day)) {
158	            then.retiredFrom = retiredFrom;
159	            then.retiredOn = retiredOn;
160	        }
161	        for (PastRetirement r : pastRetirements) {
162	            if (r.unretiredBy(day)) {
163	                then.pastRetirements.add(r);
164	            } else if (r.retiredBy(day)) {
165	                // not yet unretired at the end of the day: still retired then
166	                then.retiredFrom = r.getFrom();
167	                then.retiredOn = r.getRetiredOn();
168	            }
169	        }
170	        return then;
171	    }
172	
173	    /** Whether the person had been added by the end of the day: added while the sheet's today was on or before it. */
174	    public boolean addedBy(LocalDate day) {
175	        return addedOn == null || !addedOn.isAfter(day);
176	    }
177	
178	    public Long getId() {
179	        return id;
180	    }
181	
182	    public String getSheetId() {
183	        return sheetId;
184	    }
185	
186	    public String getName() {
187	        return name;
188	    }
189	
190	    public void setName(String name) {
191	        this.name = name;
192	    }
193	
194	    public long getPosition() {
195	        return position;
196	    }
197	
198	    public void setPosition(long position) {
199	        this.position = position;
200	    }
201	
202	    /** Every grade recorded for the person, earliest from-date first (the one from the beginning of time first). */
203	    public List<DatedGrade> getGrades() {
204	        return grades.stream().sorted(Comparator.comparing(DatedGrade::getFrom,
205	                Comparator.nullsFirst(Comparator.naturalOrder()))).toList();
206	    }
207	
208	    /** The grade in force on the date: the one with the latest from-date on or before it. */
209	    public String gradeOn(LocalDate date) {
210	        return grades.stream().filter(g -> g.getFrom() == null || (date != null && !g.getFrom().isAfter(date)))
211	                .max(Comparator.comparing(DatedGrade::getFrom, Comparator.nullsFirst(Comparator.naturalOrder())))
212	                .map(DatedGrade::getGrade).orElse(null);
213	    }
214	
215	    /**
216	     * Makes every grade recorded for the person on the merged grade the other one, keeping its from-date and the day
217	     * it was recorded.
218	     */
219	    public void regrade(String merged, String into) {
220	        grades.replaceAll(g -> merged.equals(g.getGrade()) ? new DatedGrade(into, g.getFrom(), g.madeOn()) : g);
221	    }
222	
223	    /** Records the grade from the date, replacing one already recorded from that same date; the others are kept. */
224	    public void recordGrade(String grade, LocalDate from, LocalDate madeOn) {
225	        grades.removeIf(g -> Objects.equals(g.getFrom(), from));
226	        grades.add(new DatedGrade(grade, from, madeOn));
227	    }
228	
229	    /**
230	     * The person's own terms from the beginning of time in business days: a claim of theirs is due by that many business
231	     * days after its date, unless dated terms are in force on it; null for none.
232	     */
233	    public Integer getTerms() {
234	        return terms;
235	    }
236	
237	    /** Every dated terms recorded for the person, earliest from-date first. */
238	    public List<DatedTerms> getDatedTerms() {
239	        return datedTerms.stream().sorted(Comparator.comparing(DatedTerms::getFrom)).toList();
240	    }
241	
242	    /**
243	     * The person's own terms in force on the date: those with the latest from-date on or before it, else those from
244	     * the beginning of time; null for none.
245	     */
246	    public Integer termsOn(LocalDate date) {
247	        DatedTerms inForce = datedTerms.stream().filter(t -> date != null && !t.getFrom().isAfter(date))
248	                .max(Comparator.comparing(DatedTerms::getFrom)).orElse(null);
249	        return inForce != null ? inForce.getTerms() : terms;
250	    }
251	
252	    /** Records the terms (null: none) from the date, replacing those already recorded from that same date. */
253	    public void recordTerms(Integer terms, LocalDate from, LocalDate madeOn) {
254	        datedTerms.removeIf(t -> t.getFrom().equals(from));
255	        datedTerms.add(new DatedTerms(terms, from, madeOn));
256	    }
257	
258	    public void setTerms(Integer terms) {
259	        this.terms = terms;
260	    }
261	
262	    public String getContact() {
263	        return contact;
264	    }
265	
266	    public void setContact(String contact) {
267	        this.contact = contact;
268	    }
269	
270	    public String getTags() {
271	        return tags;
272	    }
273	
274	    public void setTags(String tags) {
275	        this.tags = tags;
276	    }
277	
278	    /** The date the person is retired from; null while they are not retired. */
279	    public LocalDate getRetiredFrom() {
280	        return retiredFrom;
281	    }
282	
283	    /** Retires the person from the date, set while the sheet's today was the made-on date. */
284	    public void setRetiredFrom(LocalDate retiredFrom, LocalDate madeOn) {
285	        this.retiredFrom = retiredFrom;
286	        this.retiredOn = madeOn;
287	    }
288	
289	    /**
290	     * Unretires the person, while the sheet's today is the date: their retirement is kept as a past one, from its
291	     * from-date to the date, and they are no longer retired.
292	     */
293	    public void unretire(LocalDate on) {
294	        pastRetirements.add(new PastRetirement(retiredFrom, on, retiredOn, on));
295	        this.retiredFrom = null;
296	        this.retiredOn = null;
297	    }
298	
299	    /** The retirements the person was unretired from, earliest from-date first. */
300	    public List<PastRetirement> getPastRetirements() {
301	        return pastRetirements.stream().sorted(Comparator.comparing(PastRetirement::getFrom)
302	                .thenComparing(PastRetirement::getTo)).toList();
303	    }
304	
305	    /**
306	     * Whether a claim of the person's dated on the date is refused for a retirement: dated after their retirement
307	     * date, or after the from-date and before the to-date of a past retirement.
308	     */
309	    public boolean refusesClaimOn(LocalDate date) {
310	        return (retiredFrom != null && date != null && date.isAfter(retiredFrom))
311	                || pastRetirements.stream().anyMatch(r -> r.refuses(date));
312	    }
313	
314	    /** A person with a retirement date set is retired at once, whatever the date. */
315	    public boolean isRetired() {
316	        return retiredFrom != null;
317	    }
318	
319	    /** Whether the person's retirement date is reached on the day: the day is on or after it. */
320	    public boolean isRetiredOn(LocalDate day) {
321	        return retiredFrom != null && day != null && !day.isBefore(retiredFrom);
322	    }
323	
324	    /** The person's aliases, sorted as names are compared: ignoring case. */
325	    public List<String> getAliases() {
326	        return aliases.stream().map(PersonAlias::getAlias)
327	                .sorted(Comparator.comparing((String a) -> a.toLowerCase(Locale.ROOT)).thenComparing(a -> a))
328	                .toList();
329	    }
330	
331	    /** The sheet the person was transferred from; null: not transferred. */
332	    public String getOriginSheet() {
333	        return originSheet;
334	    }
335	
336	    public String getApprover() {
337	        return approver;
338	    }
339	
340	    public void setApprover(String approver) {
341	        this.approver = approver;
342	    }
343	
344	    /** Flags the person with the reason until the date, replacing any flag before it. */
345	    public void flag(String reason, LocalDate until) {
346	        this.flagReason = reason;
347	        this.flagUntil = until;
348	    }
349	
350	    /** The reason of the person's flag while it is in force on the day (on or before its until-date); else null. */
351	    public String flagOn(LocalDate day) {
352	        return flagReason != null && flagUntil != null && !day.isAfter(flagUntil) ? flagReason : null;
353	    }
354	
355	    /** The sheet's today when the person arrived by transfer; null: not transferred, or before that was kept. */
356	    public LocalDate getArrivedOn() {
357	        return arrivedOn;
358	    }
359	
360	    /** The user who transferred the person here; null: not transferred, or before that was kept. */
361	    public String getArrivedBy() {
362	        return arrivedBy;
363	    }
364	
365	    /**
366	     * Moves the person, with their grades, holds and aliases, to the other sheet; they came from this one, transferred
367	     * by the user while the other sheet's today was the date.
368	     */
369	    public void moveToSheet(String sheetId, LocalDate arrivedOn, String arrivedBy) {
370	        this.originSheet = this.sheetId;
371	        this.sheetId = sheetId;
372	        this.arrivedOn = arrivedOn;
373	        this.arrivedBy = arrivedBy;
374	        List<PersonAlias> moved = aliases.stream().map(a -> new PersonAlias(sheetId, a.getAlias())).toList();
375	        aliases.clear();
376	        aliases.addAll(moved);
377	    }
378	
379	    /** Gives the person the alias, without surrounding spaces; the ones already given are kept. */
380	    public void addAlias(String alias) {
381	        aliases.add(new PersonAlias(sheetId, alias));
382	    }
383	
384	    /** Takes the aliases from the person; the others are kept. */
385	    public void removeAliases(Collection<String> removed) {
386	        aliases.removeIf(a -> removed.contains(a.getAlias()));
387	    }
388	
389	    /** Every hold put on the person, earliest from-date first. */
390	    public List<DatedHold> getHolds() {
391	        return holds.stream().sorted(Comparator.comparing(DatedHold::getFrom)).toList();
392	    }
393	
394	    /** Whether the person has any hold. */
395	    public boolean isHeld() {
396	        return !holds.isEmpty();
397	    }
398	
399	    /** Puts a hold on the person from the date to the date (null: with no end); the ones already put are kept. */
400	    public void addHold(LocalDate from, LocalDate to, LocalDate madeOn) {
401	        holds.add(new DatedHold(from, to, madeOn));
402	    }
403	
404	    /**
405	     * Whether the claim counts toward the person's live totals: one whose status counts, except an open one that no
406	     * statement binds once the person's retirement date is reached on the sheet's today, and one deferred on the sheet's
407	     * today. A hold (the person's or the claim's) leaves nothing out; it only takes the person's cut from the pools.
408	     */
409	    public boolean countsLive(Claim claim, LocalDate today) {
410	        return claim.getStatus().counts() && !claim.isDeferredOn(today)
411	                && !(claim.getStatus().isOpen() && !claim.isBound()
412	                && isRetiredOn(today));
413	    }
414	
415	    /**
416	     * Whether the claim's amount counts toward what the person has claimed: as the live rules say.
417	     */
418	    public boolean countsClaimed(Claim claim, LocalDate today) {
419	        return claim.getStatus().counts() && !claim.isDeferredOn(today)
420	                && !(claim.getStatus().isOpen() && !claim.isBound() && isRetiredOn(today));
421	    }
422	
423	    /**
424	     * Whether the claim counts toward the person's figure for a period ending on the day: one whose status at the end
425	     * of that day counts, left out as the live rules say when deferred on the sheet's today or retired.
426	     */
427	    public boolean countsAtEndOf(Claim claim, LocalDate end, LocalDate today) {
428	        ClaimStatus then = claim.statusAtEndOf(end);
429	        return then != null && then.counts() && !claim.isDeferredOn(today)
430	                && !(claim.getStatus().isOpen() && !claim.isBound()
431	                && isRetiredOn(today));
432	    }
433	
434	    /**
435	     * One line per dated thing about the person, in date order, and on a date their grade changes, then their claims,
436	     * then their holds, then their retirements, then their unretirements: {@code <date> grade <grade>},
437	     * {@code <date> claim <amount> <status>}, {@code <date> hold [to <date>]}, {@code <date> retired} and
438	     * {@code <date> unretired}. The grade given from the beginning of time has no date, so no line.
439	     */
440	    public List<String> timeline(List<Claim> claims) {
441	        record Line(LocalDate date, int kind, String text) {
442	        }
443	        List<Line> lines = new ArrayList<>();
444	        grades.stream().filter(g -> g.getFrom() != null)
445	                .forEach(g -> lines.add(new Line(g.getFrom(), 0, "grade " + g.getGrade())));
446	        claims.stream().filter(c -> c.getDate() != null).forEach(c -> lines.add(new Line(c.getDate(), 1,
447	                "claim " + c.getAmount().setScale(2, RoundingMode.HALF_UP).toPlainString() + " " + c.getStatus())));
448	        holds.forEach(h -> lines.add(new Line(h.getFrom(), 2, h.getTo() == null ? "hold" : "hold to " + h.getTo())));
449	        pastRetirements.forEach(r -> lines.add(new Line(r.getFrom(), 3, "retired")));
450	        if (retiredFrom != null) {
451	            lines.add(new Line(retiredFrom, 3, "retired"));
452	        }
453	        pastRetirements.forEach(r -> lines.add(new Line(r.getTo(), 4, "unretired")));
454	        // same-dated lines of a kind in the order of their text
455	        return lines.stream().sorted(Comparator.comparing(Line::date).thenComparingInt(Line::kind)
456	                .thenComparing(Line::text))
457	                .map(l -> l.date() + " " + l.text()).toList();
458	    }
459	
460	    /** The version of the person as stored, raised on each save. */
461	    public long getVersion() {
462	        return version;
463	    }
464	}
