23	/**
24	 * A claim a person makes on a sheet: an amount (two decimals), a date, a note and a status. A negative amount is a
25	 * correction of the settled claim of the same person whose number it names.
26	 */
27	@Entity
28	@Table(name = "claim")
29	public class Claim {
30	
31	    /** The kinds a proof can be; a proof added with none chosen is a receipt. */
32	    public static final String PROOF_RECEIPT = "receipt";
33	    public static final String PROOF_PHOTO = "photo";
34	    public static final List<String> PROOF_KINDS = List.of(PROOF_RECEIPT, PROOF_PHOTO);
35	
36	    @Id
37	    @GeneratedValue(strategy = GenerationType.IDENTITY)
38	    private Long id;
39	
40	    @Column(name = "sheet_id", nullable = false)
41	    private String sheetId;
42	
43	    @Column(name = "person_id", nullable = false)
44	    private Long personId;
45	
46	    @Column(name = "amount", nullable = false, precision = 14, scale = 2)
47	    private BigDecimal amount;
48	
49	    @Column(name = "claim_date", nullable = false)
50	    private LocalDate date;
51	
52	    @Column(name = "note", nullable = false)
53	    private String note;
54	
55	    /** The claim's external reference, unique on its sheet without regard to case; null for a claim with none. */
56	    @Column(name = "ref")
57	    private String ref;
58	
59	    /** The reason the claim was voided with; null for one not voided, or voided without one. */
60	    @Column(name = "void_reason")
61	    private String voidReason;
62	
63	    /** The claim's tags, sorted and comma separated; null for a claim with none. */
64	    @Column(name = "tags")
65	    private String tags;
66	
67	    @Enumerated(EnumType.STRING)
68	    @Column(name = "status", nullable = false)
69	    private ClaimStatus status = ClaimStatus.DRAFT;
70	
71	    /**
72	     * The number given when the claim is settled (or approved): the next in the fiscal year of its due-by across the sheet's tree
73	     * (FY2026-1, FY2026-2, ...; plain 1, 2, ... given before), or while the sheet numbers by period its period's next
74	     * (P1-1, X-1 for no period); kept when it is voided, never reused; null for a claim never settled (claims
75	     * numbered when they were opened, as they once were, keep their numbers).
76	     */
77	    @Column(name = "claim_number")
78	    private String number;
79	
80	    /** The sequence a period-numbered claim was counted in: its period's name, or X; null otherwise. */
81	    @Column(name = "number_sequence")
82	    private String numberSequence;
83	
84	    /** The claim's place in its number sequence; null unless period-numbered. */
85	    @Column(name = "number_in_sequence")
86	    private Long numberInSequence;
87	
88	    /** The due fixed when the claim was settled; null while it is live. */
89	    @Column(name = "settled_due", precision = 14, scale = 2)
90	    private BigDecimal settledDue;
91	
92	    /** The user who opened the claim; null for a claim never opened. */
93	    @Column(name = "opened_by")
94	    private String openedBy;
95	
96	    /** The user who last edited the claim; null for a claim never edited. */
97	    @Column(name = "edited_by")
98	    private String editedBy;
99	
100	    /** The number of the bulk settle batch that settled the claim (or made it PENDING); null for none. */
101	    @Column(name = "settle_batch")
102	    private Integer settleBatch;
103	
104	    /** The user whose open editor holds the claim, so no one else may edit it; null while none does. */
105	    @Column(name = "locked_by")
106	    private String lockedBy;
107	
108	    /** Whether the claim is bound by its person's last statement. */
109	    @Column(name = "stated", nullable = false)
110	    private boolean stated;
