641	        if (log.isEmpty()) {
642	            return status;
643	        }
644	        ClaimStatus then = null;
645	        for (ClaimLogEntry e : log) {
646	            if (e.getOn() == null || !e.getOn().isAfter(day)) {
647	                then = e.getStatus();
