210	    /**
211	     * Saves the edit; with a terms from-date the terms are recorded from it, and without one an edit leaving the terms
212	     * in force today as they are records nothing, while any other sets the terms from the beginning of time.
213	     */
214	    private Person update(String by, String sheetId, Long id, long version, String name, String grade,
215	            LocalDate gradeFrom, Integer terms, LocalDate termsFrom, String contact, String tagged,
216	            boolean checkTree) {
217	        String personTags = ClaimService.tagsOf(tagged);
218	        LocalDate today = today(sheetId);
219	        RollupService.Snapshot before = rollup.snapshot(sheetId);
220	        Person person = people.findByIdAndSheetId(id, sheetId)
221	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
222	        if (person.getVersion() != version) {
223	            throw stale();
224	        }
225	        // keeping a retired grade as it is, with no from-date, is not a choice of it
226	        boolean gradeChosen = gradeFrom != null || !grade.equals(person.gradeOn(today));
227	        if (gradeChosen && !sheets.load(sheetId).isGrade(grade)) {
228	            throw noSuchGrade(grade);
229	        }
230	        if (gradeChosen && sheets.load(sheetId).isGradeRetired(grade)) {
231	            throw gradeRetired(grade);
232	        }
233	        String trimmed = name.strip();
234	        if (people.existsBySheetIdAndNameIgnoreCaseAndIdNot(sheetId, trimmed, id)
235	                || people.findBySheetIdAndAlias(sheetId, trimmed).isPresent()) {
236	            throw nameInUse();
237	        }
238	        if (checkTree) {
239	            Set<String> tree = tree(sheetId);
240	            if (inUseOn(tree, trimmed) || person.getAliases().stream().anyMatch(a -> inUseOn(tree, a))) {
241	                throw nameInUse();
242	            }
243	        }
244	        String key = contactKey(contact);
245	        if (key != null && people.existsBySheetIdAndContactAndIdNot(sheetId, key, id)) {
246	            throw contactInUse();
247	        }
248	        person.setName(trimmed);
249	        if (gradeChosen) {
250	            person.recordGrade(grade, gradeFrom != null ? gradeFrom : today, today);
251	        }
252	        boolean termsChanged;
253	        if (termsFrom != null) {
254	            termsChanged = person.getDatedTerms().stream().noneMatch(t -> t.getFrom().equals(termsFrom)
255	                    && Objects.equals(t.getTerms(), terms));
256	            person.recordTerms(terms, termsFrom, today);
257	        } else {
258	            // a change is one from the terms in force today, dated terms included
259	            termsChanged = !Objects.equals(terms, person.termsOn(today));
260	            if (termsChanged) {
261	                person.setTerms(terms);
262	            }
263	        }
264	        boolean contactChanged = !Objects.equals(key, person.getContact());
265	        person.setContact(key);
266	        if (tagged != null) {
267	            person.setTags(personTags);
268	            keepTags(sheetId, personTags);
269	        }
270	        Person saved = save(person);
271	        audit.recordOnCommit(record("PERSON_EDITED", by, saved, today)
272	                + (termsChanged ? " terms=" + Objects.toString(saved.termsOn(today), "") : "")
273	                + (contactChanged ? " contact=" + (key != null ? key : "") : ""));
274	        rollup.recordChanges(by, sheetId, before);
275	        return saved;
276	    }
