298	    /**
299	     * A steward merges the grade into another: every person whose grade in force on the sheet's today is the merged
300	     * grade is given the other from the sheet's today, in list order, exactly as saving each one's edit with it would,
301	     * all or none; then every grade record of theirs on the merged grade becomes the other, so all their claims,
302	     * whatever their date, take the other grade's rates, terms and thresholds (frozen figures and those bound by a
303	     * statement are unchanged). It then records the rollup changes of the merge as a whole. Refused unless the user is a steward, and
304	     * for the same grade twice. The people as saved.
305	     */
306	    @Transactional
307	    public List<Person> mergeGrade(String by, String sheetId, String from, String into) {
308	        if (!settings.isSteward(sheetId, by)) {
309	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can merge grades.");
310	        }
311	        Sheet sheet = sheets.load(sheetId);
312	        if (!sheet.isGrade(from) || !sheet.isGrade(into)) {
313	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY, "The grades must be grades of the sheet.");
314	        }
315	        if (from.equals(into)) {
316	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A grade cannot be merged into itself.");
317	        }
318	        LocalDate today = today(sheetId);
319	        RollupService.Snapshot before = rollup.snapshot(sheetId);
320	        audit.recordOnCommit("GRADE_MERGED sheet=" + sheetId + " by=" + by + " from=" + from + " into=" + into);
321	        Set<Long> ids = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
322	                .filter(p -> from.equals(p.gradeOn(today))).map(Person::getId)
323	                .collect(Collectors.toCollection(LinkedHashSet::new));
324	        List<Person> graded = bulkGrade(by, sheetId, ids, into, null);
325	        // the merge is retroactive: every grade record of theirs on the merged grade becomes the other
326	        List<Person> saved = new ArrayList<>();
327	        for (Person p : graded) {
328	            p.regrade(from, into);
329	            saved.add(save(p));
330	        }
331	        // the merge as a whole changes the rollup as its edits together did
332	        rollup.recordChanges(by, sheetId, before);
333	        return saved;
334	    }
