336	    /**
337	     * Swaps the person with the one above them in the list (up) or below them (down); refused for the top person
338	     * moving up and the bottom one moving down. Neither person's version changes: their place is not an edit of them.
339	     */
340	    @Transactional
341	    public void move(String by, String sheetId, Long id, boolean up) {
342	        sheets.lock(sheetId);
343	        List<Person> listed = people.findBySheetIdOrderByPositionAscIdAsc(sheetId);
344	        int at = -1;
345	        for (int i = 0; i < listed.size(); i++) {
346	            if (listed.get(i).getId().equals(id)) {
347	                at = i;
348	            }
349	        }
350	        if (at < 0) {
351	            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person.");
352	        }
353	        int to = up ? at - 1 : at + 1;
354	        if (to < 0 || to >= listed.size()) {
355	            throw new ResponseStatusException(HttpStatus.CONFLICT,
356	                    up ? "The top person cannot move up." : "The bottom person cannot move down.");
357	        }
358	        Person person = listed.get(at);
359	        Person other = listed.get(to);
360	        // the positions are renumbered from 1 in list order, so swapping two always changes their order
361	        for (int i = 0; i < listed.size(); i++) {
362	            Person p = i == at ? other : i == to ? person : listed.get(i);
363	            if (p.getPosition() != i + 1) {
364	                people.placeAt(p.getId(), i + 1);
365	            }
366	        }
367	        audit.recordOnCommit("PERSON_MOVED sheet=" + sheetId + " by=" + by + " name=" + person.getName()
368	                + " position=" + (to + 1));
369	    }
