572	    /**
573	     * The ids of the people on the sheet who clash: whose name or an alias is, ignoring case, a name or an alias on
574	     * another sheet of its tree (they came to clash before such names were refused, or as the tree was linked).
575	     */
576	    @Transactional(readOnly = true)
577	    public Set<Long> clashing(String sheetId) {
578	        Set<String> tree = tree(sheetId);
579	        if (tree.isEmpty()) {
580	            return Set.of();
581	        }
582	        Set<String> taken = new HashSet<>();
583	        for (Person p : people.findBySheetIdIn(tree)) {
584	            taken.add(p.getName().toLowerCase(Locale.ROOT));
585	            p.getAliases().forEach(a -> taken.add(a.toLowerCase(Locale.ROOT)));
586	        }
587	        Set<Long> clashing = new HashSet<>();
588	        for (Person p : people.findBySheetIdOrderByPositionAscIdAsc(sheetId)) {
589	            if (taken.contains(p.getName().toLowerCase(Locale.ROOT))
590	                    || p.getAliases().stream().anyMatch(a -> taken.contains(a.toLowerCase(Locale.ROOT)))) {
591	                clashing.add(p.getId());
