601	    /**
602	     * Every person on the sheet or another sheet of its tree whose name or an alias contains the text, ignoring case:
603	     * the sheet's own people first in list order, then the other sheets' by sheet id, each sheet's in list order.
604	     */
605	    @Transactional(readOnly = true)
606	    public List<Found> searchTree(String sheetId, String text) {
607	        String wanted = text == null ? "" : text.trim().toLowerCase(Locale.ROOT);
608	        List<String> sheetIds = new ArrayList<>(List.of(sheetId));
609	        sheetIds.addAll(tree(sheetId).stream().sorted().toList());
610	        List<Found> found = new ArrayList<>();
611	        for (String id : sheetIds) {
612	            Map<Long, RollupService.Figures> figures = rollup.snapshot(id).people();
613	            LocalDate today = today(id);
614	            for (Person p : people.findBySheetIdOrderByPositionAscIdAsc(id)) {
615	                if (p.getName().toLowerCase(Locale.ROOT).contains(wanted)
616	                        || p.getAliases().stream().anyMatch(a -> a.toLowerCase(Locale.ROOT).contains(wanted))) {
617	                    RollupService.Figures f = figures.get(p.getId());
618	                    found.add(new Found(id, p.getName(), p.gradeOn(today), f == null ? null : f.dueTotal()));
619	                }
620	            }
621	        }
622	        return found;
623	    }
