625	    /**
626	     * The other sheets of the sheet's tree, among the sheets that exist: its parent, their parent and so on, and the
627	     * sheets naming it as parent, the ones naming those, and so on.
628	     */
629	    private Set<String> tree(String sheetId) {
630	        Set<String> tree = new LinkedHashSet<>();
631	        Set<String> seen = new HashSet<>(Set.of(sheetId));
632	        String at = sheetRepository.findById(sheetId).map(Sheet::getParentId).orElse(null);
633	        while (at != null && seen.add(at)) {
634	            Sheet parent = sheetRepository.findById(at).orElse(null);
635	            if (parent == null) {
636	                break;
637	            }
638	            tree.add(at);
639	            at = parent.getParentId();
640	        }
641	        ArrayDeque<String> toVisit = new ArrayDeque<>(List.of(sheetId));
642	        Set<String> below = new HashSet<>(Set.of(sheetId));
643	        while (!toVisit.isEmpty()) {
644	            for (Sheet child : sheetRepository.findByParentIdOrderByIdAsc(toVisit.poll())) {
645	                if (below.add(child.getId())) {
646	                    toVisit.add(child.getId());
647	                    if (!child.getId().equals(sheetId)) {
648	                        tree.add(child.getId());
649	                    }
650	                }
651	            }
652	        }
653	        tree.remove(sheetId);
654	        return tree;
655	    }
