3	/**
4	 * A claim's status: it starts as DRAFT, is opened, then settled; a clerk's settling above the clerk limit makes it
5	 * PENDING until a steward approves it (SETTLED) or rejects it (OPEN again); a DRAFT, OPEN or PENDING claim can be
6	 * voided, and a SETTLED one by a steward within the days after its settlement. A DRAFT claim can be DELETED, and on
7	 * the sheet's today it was deleted restored to a DRAFT again; a DELETED claim counts nowhere. A DRAFT whose due is
8	 * above the review threshold in force on its date goes to REVIEW when opened, until a steward reviews it (OPEN); a
9	 * REVIEW claim counts nowhere and can be voided.
10	 */
11	public enum ClaimStatus {
12	    DRAFT, OPEN, PENDING, SETTLED, VOID, DELETED, REVIEW;
13	
14	    /** Whether a claim in this status may move to {@code next}. */
15	    public boolean canMoveTo(ClaimStatus next) {
16	        return switch (next) {
17	            case OPEN -> this == DRAFT || this == PENDING || this == REVIEW;
18	            case PENDING -> this == OPEN;
19	            case SETTLED -> this == OPEN || this == PENDING;
20	            case VOID -> this == DRAFT || this == OPEN || this == PENDING || this == SETTLED || this == REVIEW;
21	            case DRAFT -> this == DELETED;
22	            case DELETED -> this == DRAFT;
23	            case REVIEW -> this == DRAFT;
24	        };
25	    }
26	
27	    /** Whether a claim in this status counts toward what is claimed and due: only open, pending and settled ones do. */
28	    public boolean counts() {
29	        return this == OPEN || this == PENDING || this == SETTLED;
30	    }
31	
32	    /** Whether a claim in this status is open: OPEN or PENDING. An open claim goes overdue and bears the late charge. */
33	    public boolean isOpen() {
34	        return this == OPEN || this == PENDING;
35	    }
36	}
