1	package net.officefloor.hq.app.person;
2	
3	import java.util.ArrayList;
4	import java.util.HashSet;
5	import java.util.List;
6	import java.util.Locale;
7	import java.util.Set;
8	import net.officefloor.hq.app.sheet.SheetService;
9	import org.springframework.http.HttpStatus;
10	import org.springframework.stereotype.Service;
11	import org.springframework.transaction.annotation.Transactional;
12	import org.springframework.web.server.ResponseStatusException;
13	
14	/**
15	 * Adds a person for each pasted line of name,grade,terms,contact (the last two may be absent or blank), or updates the
16	 * person on the sheet the line names, all of them or none. A blank grade is the sheet's default grade.
17	 */
18	@Service
19	public class PersonImportService {
20	
21	    /** A pasted line read into the person form's fields. */
22	    private record Line(String name, String grade, Integer terms, String contact) {
23	    }
24	
25	    /** What an import did: the people it added and the people it updated, each in line order. */
26	    public record Result(List<Person> added, List<Person> updated) {
27	    }
28	
29	    private final PersonService people;
30	    private final PersonRepository repository;
31	    private final SheetService sheets;
32	
33	    public PersonImportService(PersonService people, PersonRepository repository, SheetService sheets) {
34	        this.people = people;
35	        this.repository = repository;
36	        this.sheets = sheets;
37	    }
38	
39	    /**
40	     * Reads every line first by the person form's rules, a name, person or contact repeated within the paste refused
41	     * too. Then, in line order, a line whose name is a name or alias of a person on the sheet (compared as names are)
42	     * updates that person as saving their edit would: the grade recorded from the sheet's today, and the terms and
43	     * contact set when the line gives them. Any other line adds a person as the form would. One change: any line
44	     * refused refuses them all, and nothing is stored or audited.
45	     */
46	    @Transactional
47	    public Result importPeople(String by, String sheetId, String text) {
48	        List<Line> lines = new ArrayList<>();
49	        List<Person> matches = new ArrayList<>();
50	        Set<String> names = new HashSet<>();
51	        Set<Long> matched = new HashSet<>();
52	        Set<String> contacts = new HashSet<>();
53	        String defaultGrade = sheets.load(sheetId).defaultGradeOrA();
54	        List<String> grades = sheets.load(sheetId).gradeList();
55	        int n = 0;
56	        for (String raw : text.split("\\r?\\n")) {
57	            n++;
58	            if (raw.isBlank()) {
59	                continue;
60	            }
61	            Line line = read(n, raw, defaultGrade, grades);
62	            if (!names.add(line.name().toLowerCase(Locale.ROOT))) {
63	                throw refused("Line " + n + " repeats the name " + line.name() + ".");
64	            }
65	            if (line.contact() != null && !contacts.add(line.contact())) {
66	                throw refused("Line " + n + " repeats the contact " + line.contact() + ".");
67	            }
68	            Person match = repository.findBySheetIdAndNameOrAlias(sheetId, line.name()).orElse(null);
69	            if (match != null && !matched.add(match.getId())) {
70	                throw refused("Line " + n + " repeats the person " + match.getName() + ".");
71	            }
72	            if (match == null && people.nameOrAliasInUse(sheetId, line.name())) {
73	                throw refused("Line " + n + ": the name " + line.name() + " is already in use on this sheet.");
74	            }
75	            if (line.contact() != null && (match == null
76	                    ? repository.existsBySheetIdAndContact(sheetId, line.contact())
77	                    : repository.existsBySheetIdAndContactAndIdNot(sheetId, line.contact(), match.getId()))) {
78	                throw refused("Line " + n + ": the contact " + line.contact() + " is already in use on this sheet.");
79	            }
80	            lines.add(line);
81	            matches.add(match);
82	        }
83	        if (lines.isEmpty()) {
84	            throw refused("Paste at least one line of name,grade,terms,contact.");
85	        }
86	        List<Person> added = new ArrayList<>();
87	        List<Person> updated = new ArrayList<>();
88	        for (int i = 0; i < lines.size(); i++) {
89	            Line l = lines.get(i);
90	            Person match = matches.get(i);
91	            if (match == null) {
92	                added.add(people.add(by, sheetId, l.name(), l.grade(), l.terms(), l.contact()));
93	            } else {
94	                updated.add(people.update(by, sheetId, match.getId(), match.getVersion(), match.getName(), l.grade(),
95	                        null, l.terms() != null ? l.terms() : match.getTerms(),
96	                        l.contact() != null ? l.contact() : match.getContact()));
97	            }
98	        }
99	        return new Result(added, updated);
100	    }
101	
102	    private Line read(int n, String raw, String defaultGrade, List<String> grades) {
103	        String[] f = raw.split(",", 4);
104	        if (f.length < 2) {
105	            throw refused("Line " + n + " needs at least a name and a grade.");
106	        }
107	        String name = f[0].strip();
108	        if (name.isEmpty()) {
109	            throw refused("Line " + n + " has no name.");
110	        }
111	        if (name.length() > 200) {
112	            throw refused("Line " + n + " has a name longer than 200 characters.");
113	        }
114	        String grade = f[1].strip();
115	        if (grade.isEmpty()) {
116	            grade = defaultGrade;
117	        }
118	        if (!grades.contains(grade)) {
119	            throw refused("Line " + n + " has a grade that is not one of the grades.");
120	        }
121	        Integer terms = null;
122	        String termsText = f.length > 2 ? f[2].strip() : "";
123	        if (!termsText.isEmpty()) {
124	            if (!termsText.matches("\\d{1,5}")) {
125	                throw refused("Line " + n + " has terms that are not a whole number of days.");
126	            }
127	            terms = Integer.valueOf(termsText);
128	        }
129	        String contact = f.length > 3 ? f[3].strip() : "";
130	        if (contact.length() > 200) {
131	            throw refused("Line " + n + " has a contact longer than 200 characters.");
132	        }
133	        return new Line(name, grade, terms, contact.isEmpty() ? null : contact.toLowerCase(Locale.ROOT));
134	    }
135	
136	    private static ResponseStatusException refused(String reason) {
137	        return new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, reason);
138	    }
139	}
