88	    /**
89	     * The sheet's duplicate claims: for each person, date and amount with two or more claims (VOID and DELETED ones
90	     * left out), one line {@code <name> <date> <amount> x<count>}; people in list order, then by date, then by amount.
91	     */
92	    @Transactional(readOnly = true)
93	    public List<String> duplicates(String sheetId) {
94	        record Key(LocalDate date, BigDecimal amount) {}
95	        Map<Long, Map<Key, Integer>> counts = new HashMap<>();
96	        for (Claim c : claims.findBySheetIdOrderByIdDesc(sheetId)) {
97	            if (c.getStatus() == ClaimStatus.VOID || c.getStatus() == ClaimStatus.DELETED) continue;
98	            counts.computeIfAbsent(c.getPersonId(), k -> new TreeMap<>(
99	                    Comparator.comparing(Key::date).thenComparing(Key::amount)))
100	                    .merge(new Key(c.getDate(), c.getAmount().setScale(2, RoundingMode.HALF_UP)), 1, Integer::sum);
101	        }
102	        List<String> lines = new ArrayList<>();
103	        for (Person p : people.findBySheetIdOrderByPositionAscIdAsc(sheetId)) {
104	            counts.getOrDefault(p.getId(), Map.of()).forEach((k, n) -> {
105	                if (n >= 2) lines.add(p.getName() + " " + k.date() + " " + k.amount().toPlainString() + " x" + n);
106	            });
107	        }
108	        return lines;
109	    }
