111	    /**
112	     * The sheet's policy versions, oldest first: one line {@code <version> <from> <key>=<value> <count>} each, where
113	     * the count is of the claims (DELETED ones left out) whose policy version, the one in force on their date, it is.
114	     */
115	    @Transactional(readOnly = true)
116	    public List<String> policy(String sheetId) {
117	        Sheet sheet = sheets.load(sheetId);
118	        Map<Integer, Integer> counts = new HashMap<>();
119	        for (Claim c : claims.findBySheetIdOrderByIdDesc(sheetId)) {
120	            if (c.getStatus() == ClaimStatus.DELETED) continue;
121	            counts.merge(sheet.policyVersionOn(c.getDate()), 1, Integer::sum);
122	        }
123	        List<String> lines = new ArrayList<>();
124	        List<SettingChange> changes = sheet.policyChanges();
125	        for (int i = 0; i < changes.size(); i++) {
126	            SettingChange ch = changes.get(i);
127	            int version = i + 1;
128	            lines.add(version + " " + (ch.getFrom() == null ? "start" : ch.getFrom()) + " " + ch.getKey() + "="
129	                    + (ch.getValue() == null ? "" : ch.getValue()) + " " + counts.getOrDefault(version, 0));
130	        }
131	        return lines;
132	    }
