134	    /**
135	     * The sheet's policy versions as CSV rows, oldest first: version, from (blank for one counting from the start),
136	     * key, value, the count of the claims (DELETED ones left out) whose policy version it is, and the due of those
137	     * of them that count (open, pending and settled ones, n/a dues left out) added up, to two decimals.
138	     */
139	    @Transactional(readOnly = true)
140	    public List<List<String>> policyCsv(String sheetId) {
141	        Sheet sheet = sheets.load(sheetId);
142	        Map<Long, Person> byId = new HashMap<>();
143	        for (Person p : people.findBySheetIdOrderByPositionAscIdAsc(sheetId)) byId.put(p.getId(), p);
144	        Map<Integer, Integer> counts = new HashMap<>();
145	        Map<Integer, BigDecimal> dues = new HashMap<>();
146	        for (Claim c : claims.findBySheetIdOrderByIdDesc(sheetId)) {
147	            if (c.getStatus() == ClaimStatus.DELETED) continue;
148	            int version = sheet.policyVersionOn(c.getDate());
149	            counts.merge(version, 1, Integer::sum);
150	            Person person = byId.get(c.getPersonId());
151	            if (!c.getStatus().counts() || person == null) continue;
152	            BigDecimal due = due(sheetId, person, c);
153	            if (due != null) dues.merge(version, due, BigDecimal::add);
154	        }
155	        List<List<String>> rows = new ArrayList<>();
156	        rows.add(List.of("version", "from", "key", "value", "claims", "due-total"));
157	        List<SettingChange> changes = sheet.policyChanges();
158	        for (int i = 0; i < changes.size(); i++) {
159	            SettingChange ch = changes.get(i);
160	            int version = i + 1;
161	            rows.add(List.of(String.valueOf(version), ch.getFrom() == null ? "" : ch.getFrom().toString(),
162	                    ch.getKey(), ch.getValue() == null ? "" : ch.getValue(),
163	                    String.valueOf(counts.getOrDefault(version, 0)),
164	                    dues.getOrDefault(version, BigDecimal.ZERO).setScale(2, RoundingMode.HALF_UP).toPlainString()));
165	        }
166	        return rows;
167	    }
