202	    /**
203	     * Adds a claim as {@link #add(String, String, Long, BigDecimal, LocalDate, String, String)} does, carrying the
204	     * external reference (stripped; blank for none). Refused too when the reference is already used on the sheet,
205	     * comparing without regard to case. Its tags (comma separated) are trimmed, lower-cased and kept once each.
206	     */
207	    @Transactional
208	    public Claim add(String by, String sheetId, Long personId, BigDecimal amount, LocalDate date, String note,
209	            String corrects, String ref, String tagged) {
210	        LocalDate on = dateOrEntryDate(sheetId, date);
211	        Person person = person(sheetId, personId);
212	        int terms = termsFor(sheetId, person);
213	        LocalDate dueBy = holidays.dueBy(sheetId, on, terms);
214	        refuseInClosedPeriod(sheetId, dueBy);
215	        RollupService.Snapshot before = rollup.snapshot(sheetId);
216	        refuseAfterRetirement(person, on);
217	        String corrected = correctedNumber(sheetId, personId, amount, corrects, null);
218	        String reference = refOf(sheetId, ref, null);
219	        Claim claim = new Claim(sheetId, personId, scaled(amount), on, noteOf(note));
220	        claim.setRef(reference);
221	        claim.setTags(tagsOf(tagged));
222	        claim.setCorrects(corrected);
223	        claim.setRoundsOn(roundsOn(sheetId, corrected, on));
224	        claim.setDueBy(dueBy);
225	        claim.setTerms(terms);
226	        claim.setLateEntry(periods.existsBySheetIdAndSoftClosedTrueAndFromLessThanEqualAndToGreaterThanEqual(sheetId,
227	                dueBy, dueBy));
228	        logStatus(by, sheetId, person, claim);
229	        Claim added = claims.saveAndFlush(claim);
230	        keepTags(sheetId, added.getTags());
231	        audit.recordOnCommit(record("CLAIM_ADDED", by, person, added)
232	                + (added.getRef() != null ? " ref=" + added.getRef() : "")
233	                + (added.getTags() != null ? " tags=" + added.getTags() : ""));
234	        if (added.isLateEntry()) {
235	            audit.recordOnCommit(record("LATE_ENTRY", by, person, added));
236	        }
237	        rollup.recordChanges(by, sheetId, before);
238	        return added;
239	    }
