241	    /**
242	     * Edits a claim; its due-by, and so its period, stay as they were fixed. Refused unless it is a draft, when its
243	     * due-by falls in a closed period, and for a claim with lines when the amount is not the one its lines make. An open claim is changed by voiding it and adding a new one.
244	     */
245	    @Transactional
246	    public Claim update(String by, String sheetId, Long id, BigDecimal amount, LocalDate date, String note,
247	            String corrects, String ref, String tagged) {
248	        LocalDate on = dateOrToday(sheetId, date);
249	        Claim claim = claims.findByIdAndSheetId(id, sheetId)
250	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
251	        if (claim.getStatus() != ClaimStatus.DRAFT) {
252	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a draft claim can be edited.");
253	        }
254	        refuseLockedByOther(by, claim);
255	        refuseInClosedPeriod(sheetId, claim.getDueBy());
256	        refuseAfterRetirement(person(sheetId, claim.getPersonId()), on);
257	        if (!claim.getLines().isEmpty() && scaled(amount).compareTo(claim.getAmount()) != 0) {
258	            throw new ResponseStatusException(HttpStatus.CONFLICT,
259	                    "A claim with lines has the sum of its lines as its amount.");
260	        }
261	        String corrected = correctedNumber(sheetId, claim.getPersonId(), amount, corrects, claim.getId());
262	        String reference = refOf(sheetId, ref, claim.getId());
263	        RollupService.Snapshot before = rollup.snapshot(sheetId);
264	        claim.setAmount(scaled(amount));
265	        claim.setCorrects(corrected);
266	        claim.setDate(on);
267	        claim.setRoundsOn(roundsOn(sheetId, corrected, on));
268	        claim.setNote(noteOf(note));
269	        claim.setRef(reference);
270	        claim.setTags(tagsOf(tagged));
271	        claim.setEditedBy(by);
272	        // the save closes the editor, which releases the claim
273	        claim.setLockedBy(null);
274	        Claim saved = claims.saveAndFlush(claim);
275	        keepTags(sheetId, saved.getTags());
276	        audit.recordOnCommit(record("CLAIM_EDITED", by, person(sheetId, saved.getPersonId()), saved));
277	        rollup.recordChanges(by, sheetId, before);
278	        return saved;
279	    }
