281	    /**
282	     * Opens the user's editor on a claim, which holds it for them: no one else may edit it until the editor is saved
283	     * or cancelled, or the sheet's today changes. Refused unless it is a draft, when its due-by falls in a closed period,
284	     * and when another user's editor holds it. An editor the user had open on another claim of the sheet is closed.
285	     */
286	    @Transactional
287	    public Claim lock(String by, String sheetId, Long id) {
288	        Claim claim = lockedClaim(sheetId, id);
289	        if (claim.getStatus() != ClaimStatus.DRAFT) {
290	            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a draft claim can be edited.");
291	        }
292	        refuseLockedByOther(by, claim);
293	        for (Claim held : claims.findBySheetIdAndLockedByNotNull(sheetId)) {
294	            if (by.equals(held.getLockedBy()) && !held.getId().equals(claim.getId())) {
295	                held.setLockedBy(null);
296	            }
297	        }
298	        claim.setLockedBy(by);
299	        return claims.saveAndFlush(claim);
300	    }
