370	    /**
371	     * Moves the claim to its next status. A part being settled was judged by the four-eyes rules and the proof rule
372	     * on the claim it was split off, so they are not judged on it again.
373	     */
374	    private Claim changeStatus(String by, String sheetId, Long id, ClaimStatus next, String reason, boolean part,
375	            LocalDate on) {
376	        Claim claim = lockedClaim(sheetId, id);
377	        switch (next) {
378	            case OPEN -> settings.refuseUnlessMay(sheetId, by, "open");
379	            case SETTLED -> settings.refuseUnlessMay(sheetId, by, "settle");
380	            case VOID -> settings.refuseUnlessMay(sheetId, by, "void");
381	            default -> {
382	            }
383	        }
384	        RollupService.Snapshot before = rollup.snapshot(sheetId);
385	        String tail = "";
386	        // settling is the step from OPEN; a pending claim is settled by approving it
387	        if (!claim.getStatus().canMoveTo(next) || next == ClaimStatus.PENDING
388	                || (next == ClaimStatus.SETTLED && claim.getStatus() != ClaimStatus.OPEN)
389	                || (next == ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.DRAFT)) {
390	            throw new ResponseStatusException(HttpStatus.CONFLICT,
391	                    "A " + claim.getStatus() + " claim cannot become " + next + ".");
392	        }
393	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.load(sheetId).getToday())) {
394	            throw new ResponseStatusException(HttpStatus.CONFLICT,
395	                    "The claim is deferred until " + claim.getDeferredUntil() + ".");
396	        }
397	        if (next == ClaimStatus.SETTLED && !part) {
398	            refuseFourEyes(by, claim);
399	        }
400	        if (next == ClaimStatus.DRAFT && claim.getCorrects() != null) {
401	            // a restored correction counts against its claim again
402	            refuseOverCorrection(sheetId, claim.getPersonId(), claim.getAmount(), claim.getCorrects(), claim.getId());
403	        }
404	        if (next == ClaimStatus.VOID && claim.getStatus() == ClaimStatus.SETTLED) {
405	            refuseVoidOfSettled(by, sheetId, claim);
406	            // the frozen figure leaves every total; the claim keeps its number and shows the figure it had
407	            tail = " reversed=" + text(claim.getSettledDue());
408	        }
409	        if (next == ClaimStatus.VOID) {
410	            String voidReason = voidReasons.refuseUnlessListed(sheetId, reason);
411	            claim.setVoidReason(voidReason);
412	            if (voidReason != null) {
413	                tail += " reason=" + voidReason;
414	            }
415	        }
416	        Person person = person(sheetId, claim.getPersonId());
417	        if (next == ClaimStatus.OPEN) {
418	            refuseFlaggedUnlessSteward(by, sheetId, person);
419	            refuseWithoutNote(sheetId, claim);
420	            refuseOverPeriodCap(sheetId, claim);
421	            refuseOverMaxOpen(sheetId, claim);
422	            if (aboveReviewThreshold(sheetId, person, claim)) {
423	                // it waits for a steward's review; like an OPEN claim it is numbered only once it is settled
424	                next = ClaimStatus.REVIEW;
425	            }
426	            claim.setOpenedBy(by);
427	        }
428	        String event = switch (next) {
429	            case OPEN -> "CLAIM_OPENED";
430	            case REVIEW -> "CLAIM_REVIEW";
431	            case SETTLED -> "CLAIM_SETTLED";
432	            case VOID -> "CLAIM_VOIDED";
433	            case DRAFT, PENDING, DELETED -> throw new IllegalStateException();
434	        };
435	        if (next == ClaimStatus.SETTLED) {
436	            // the due is fixed at the due a statement bound it to (late charge and floor included), else at the rate
437	            // the person's grade has in force on the claim's date, with the late charge it has gained by today, and
438	            // at least the floor in force on its date; with none it stays live
439	            BigDecimal fixed = on != null ? dueAsOf(sheetId, id, on)
440	                    : claim.isStated() && claim.getStatedDue() != null ? claim.getStatedDue()
441	                    : liveDue(rateFigure(sheetId, person, claim), claim, person, sheets.load(sheetId), true);
442	            if (!part) {
443	                refuseWithoutProof(sheetId, claim, fixed);
444	            }
445	            if (settings.aboveClerkLimit(sheetId, by, person.gradeOn(sheets.load(sheetId).getToday()), claim.getDate(), fixed)) {
446	                next = ClaimStatus.PENDING;
447	                event = "CLAIM_PENDING";
448	            } else {
449	                claim.setSettledDue(fixed);
450	                numberOnSettle(sheetId, claim);
451	                tail = " due=" + (fixed == null ? "n/a" : fixed.toPlainString())
452	                        + (on == null ? "" : " on=" + on);
453	            }
454	        }
455	        claim.setStatus(next);
456	        logStatus(by, sheetId, person, claim);
457	        Claim saved = claims.saveAndFlush(claim);
458	        audit.recordOnCommit(record(event, by, person, saved) + tail);
459	        if (next == ClaimStatus.SETTLED) {
460	            watches.notifyWatchers(by, sheetId, person, saved.getNumber());
461	        }
462	        rollup.recordChanges(by, sheetId, before);
463	        return saved;
464	    }
