467	     * The due the claim showed at the end of the day, as the sheet as of that day works it out. Refused for a day after
468	     * the sheet's today, and for a claim the sheet did not hold then.
469	     */
470	    private BigDecimal dueAsOf(String sheetId, Long id, LocalDate on) {
471	        LocalDate today = sheets.load(sheetId).getToday();
472	        if (today != null && on.isAfter(today)) {
473	            throw new ResponseStatusException(HttpStatus.CONFLICT,
474	                    "A claim cannot be settled as of " + on + ", after the sheet's today " + today + ".");
475	        }
476	        record Then(boolean held, BigDecimal due) {
477	        }
478	        Then then = asOf.readAsOf(sheetId, on, () -> claims.findByIdAndSheetId(id, sheetId)
479	                .flatMap(c -> people.findByIdAndSheetId(c.getPersonId(), sheetId)
480	                        .map(p -> new Then(true, due(sheetId, p, c))))
481	                .orElse(new Then(false, null)));
482	        if (!then.held()) {
483	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY, "The claim did not exist on " + on + ".");
484	        }
485	        return then.due();
486	    }
