510	    /**
511	     * Restores a DELETED claim to a DRAFT again. Refused for a claim that is not DELETED, unless the sheet's today is
512	     * the one it was deleted on, and in a closed period.
513	     */
514	    @Transactional
515	    public Claim restore(String by, String sheetId, Long id) {
516	        Claim claim = lockedClaim(sheetId, id);
517	        if (claim.getStatus() != ClaimStatus.DELETED) {
