259	    public Sheet asOf(LocalDate day) {
260	        Sheet then = new Sheet();
261	        then.id = id;
262	        then.createdAt = createdAt;
263	        then.today = day;
264	        then.permissions.putAll(permissions);
265	        then.policyDate = policyDate;
266	        then.periodNumberingFrom = periodNumberingFrom;
267	        then.entryDate = entryDate;
268	        then.graceDays = graceDays;
269	        then.escalateAfter = escalateAfter;
270	        then.reviewSla = reviewSla;
271	        then.pendingSla = pendingSla;
272	        then.maxOpen = maxOpen;
273	        then.scoreMid = scoreMid;
274	        then.scoreHigh = scoreHigh;
275	        then.scoreLog = scoreLog;
276	        then.proofKinds = proofKinds;
277	        then.defaultGrade = defaultGrade;
278	        then.retiredGrades = retiredGrades;
279	        then.addedGrades = addedGrades;
280	        then.pot = pot;
281	        then.alertThreshold = alertThreshold;
282	        then.fiscalStartMonth = fiscalStartMonth;
283	        then.parentId = parentId;
284	        then.clonedFrom = clonedFrom;
285	        then.archived = archived;
286	        then.lastSettleBatch = lastSettleBatch;
287	        settingChanges.stream().filter(c -> c.madeBy(day)).forEach(then.settingChanges::add);
288	        // a value recorded before changes were kept stands as it is
289	        for (DatedSetting s : settings) {
290	            if (settingChanges.stream()
291	                    .noneMatch(c -> c.getKey().equals(s.getKey()) && c.getFrom().equals(s.getFrom()))) {
292	                then.settings.add(s);
293	            }
294	        }
295	        for (SettingChange c : settingChanges) {
296	            if (c.madeBy(day)) {
297	                then.settings.removeIf(s -> s.getKey().equals(c.getKey()) && s.getFrom().equals(c.getFrom()));
298	                then.settings.add(new DatedSetting(c.getKey(), c.getFrom(), c.getValue()));
299	            }
300	        }
301	        return then;
302	    }
