679	    /**
680	     * The due-total (null for n/a, which is not capped) held to the cap in force on the date (the date of the
681	     * person's latest claim that counts; null for the sheet's today) less the person's cut total (null for none), not
682	     * below 0.00, when it is above that.
683	     */
684	    public BigDecimal capped(BigDecimal dueTotal, BigDecimal cutTotal, LocalDate on) {
685	        BigDecimal cap = capOn(on != null ? on : getToday());
686	        if (cap == null || dueTotal == null) {
687	            return dueTotal;
688	        }
689	        BigDecimal room = cutTotal == null ? cap : cap.subtract(cutTotal).max(BigDecimal.ZERO);
690	        return dueTotal.compareTo(room) > 0 ? room.setScale(2) : dueTotal;
691	    }
