698	    /**
699	     * How a claim's live figures round, by the date its rounding follows: by the rounding mode in force on it when
700	     * one is; else half up before the policy date (the sheet's today when it is blank), half to even on or after it.
701	     */
702	    public RoundingMode roundingOn(LocalDate roundsOn) {
703	        Optional<String> mode = roundingModeOn(roundsOn);
704	        if (mode.isPresent()) {
705	            return HALF_UP.equals(mode.get()) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
706	        }
707	        LocalDate policy = policyDate != null ? policyDate : getToday();
708	        return policy != null && roundsOn.isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
709	    }
