1	package net.officefloor.hq.app.sheet;
2	
3	import java.time.LocalDate;
4	import java.util.ArrayDeque;
5	import java.util.HashSet;
6	import java.util.LinkedHashSet;
7	import java.util.List;
8	import java.util.Set;
9	import net.officefloor.hq.app.rollup.RollupService;
10	import org.springframework.context.ApplicationEventPublisher;
11	import org.springframework.dao.DataIntegrityViolationException;
12	import org.springframework.stereotype.Service;
13	import org.springframework.transaction.annotation.Transactional;
14	
15	/** Loads a sheet by id; a sheet never loaded before starts empty. */
16	@Service
17	public class SheetService {
18	
19	    private final SheetRepository sheets;
20	    private final RollupService rollup;
21	    private final ApplicationEventPublisher events;
22	
23	    public SheetService(SheetRepository sheets, RollupService rollup, ApplicationEventPublisher events) {
24	        this.sheets = sheets;
25	        this.rollup = rollup;
26	        this.events = events;
27	    }
28	
29	    public Sheet load(String id) {
30	        return sheets.findById(id).orElseGet(() -> create(id));
31	    }
32	
33	    /**
34	     * Change the sheet's today; every date decision on the sheet follows it. It has no audit line of its own, only
35	     * the figures it moves, after a SNAPSHOT line per person with their due-total on the day being left. What follows
36	     * a today change (the periods it closes) runs before those are rolled up. While the sheet's score log is on, a
37	     * SCORE line per person with their score on the day being left comes before the SNAPSHOT lines.
38	     */
39	    @Transactional
40	    public Sheet setToday(String by, String id, LocalDate today) {
41	        Sheet sheet = load(id);
42	        RollupService.Snapshot before = rollup.snapshot(id);
43	        if (sheet.isScoreLog()) {
44	            rollup.recordScores(by, id, before);
45	        }
46	        rollup.recordSnapshot(by, id, before, sheet.getToday());
47	        sheet.setToday(today);
48	        Sheet saved = sheets.saveAndFlush(sheet);
49	        events.publishEvent(new TodayChanged(by, saved));
50	        rollup.recordChanges(by, id, before);
51	        return saved;
52	    }
53	
54	    /** Loads the sheet and locks it until the transaction ends, so changes checked against the whole sheet run in turn. */
55	    @Transactional
56	    public Sheet lock(String id) {
57	        load(id);
58	        return sheets.findWithLockById(id).orElseThrow();
59	    }
60	
61	    /**
62	     * Takes the sheet's next claim number in the fiscal year: the one after the last given in that year on any sheet of
63	     * its tree, which share one sequence per fiscal year. The tree's root is locked, so two callers on the tree at once
64	     * never get the same one.
65	     */
66	    @Transactional
67	    public long nextFiscalClaimNumber(String id, int fiscalYear) {
68	        load(id);
69	        Set<String> tree = tree(id);
70	        sheets.findWithLockById(root(id)).orElseThrow();
71	        long next = sheets.lastFiscalClaimNumberOf(tree, fiscalYear) + 1;
72	        sheets.setFiscalClaimNumber(id, fiscalYear, next);
73	        return next;
74	    }
75	
76	    /** The top of the sheet's tree: its parent, their parent and so on, as far as the sheets exist. */
77	    private String root(String id) {
78	        Set<String> seen = new HashSet<>();
79	        String at = id;
80	        while (seen.add(at)) {
81	            String parent = sheets.findById(at).map(Sheet::getParentId).orElse(null);
82	            if (parent == null || !sheets.existsById(parent)) {
83	                break;
84	            }
85	            at = parent;
86	        }
87	        return at;
88	    }
89	
90	    /** Every sheet of the sheet's tree, the sheet itself among them: its root and all the sheets below it. */
91	    private Set<String> tree(String id) {
92	        String root = root(id);
93	        Set<String> tree = new LinkedHashSet<>(List.of(root));
94	        ArrayDeque<String> toVisit = new ArrayDeque<>(List.of(root));
95	        while (!toVisit.isEmpty()) {
96	            for (Sheet child : sheets.findByParentIdOrderByIdAsc(toVisit.poll())) {
97	                if (tree.add(child.getId())) {
98	                    toVisit.add(child.getId());
99	                }
100	            }
101	        }
102	        tree.add(id);
103	        return tree;
104	    }
105	
106	    /** Whether the other sheet is one of the sheet's descendants: a sheet naming it as parent, one naming that, and so on. */
107	    @Transactional(readOnly = true)
108	    public boolean isDescendant(String id, String other) {
109	        Set<String> seen = new HashSet<>(Set.of(id));
110	        ArrayDeque<String> toVisit = new ArrayDeque<>(List.of(id));
111	        while (!toVisit.isEmpty()) {
112	            for (Sheet child : sheets.findByParentIdOrderByIdAsc(toVisit.poll())) {
113	                if (child.getId().equals(other)) {
114	                    return true;
115	                }
116	                if (seen.add(child.getId())) {
117	                    toVisit.add(child.getId());
118	                }
119	            }
120	        }
121	        return false;
122	    }
123	
124	    /** Takes the sheet's next settle batch number; two callers at once never get the same one. */
125	    @Transactional
126	    public int nextSettleBatch(String id) {
127	        load(id);
128	        sheets.incrementSettleBatch(id);
129	        return sheets.lastSettleBatch(id);
130	    }
131	
132	    private Sheet create(String id) {
133	        try {
134	            return sheets.saveAndFlush(new Sheet(id));
135	        } catch (DataIntegrityViolationException e) {
136	            // another user created it at the same moment
137	            return sheets.findById(id).orElseThrow(() -> e);
138	        }
139	    }
140	}
