52	    /**
53	     * A steward clones the sheet to the other id. The clone records the sheet it was cloned from, whose rates apply
54	     * to a grade with none in force on the clone nor on its parents (see {@code RateChain}). The clone gets the sheet's today, settings, roles, rates (and their
55	     * history), holidays, void reasons, templates and claim tags; its people with their grades, terms, contacts,
56	     * aliases, holds, retirements and patrons, in list order; its pools and their members; its crews and their members; its periods, all open; and
57	     * its claims with status, frozen figures, dates, notes, tags, references, comments and logs, listed as they were.
58	     * Each claim that had a number takes the clone's next, in the order the claims were opened (by the sheet's today
59	     * when each was opened, then the order they were added to the clone: by person in list order, then as they were
60	     * listed). Statements, the figures they bound, watches, delegations and settle batches are not copied. Refused
61	     * unless the user is a steward, and unless the other id was never used.
62	     */
63	    @Transactional
64	    public void cloneSheet(String by, String sheetId, String toSheetId) {
65	        if (!settings.isSteward(sheetId, by)) {
66	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can clone the sheet.");
67	        }
68	        sheetService.lock(sheetId);
69	        if (sheetId.equals(toSheetId) || sheets.existsById(toSheetId)) {
70	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The other sheet must be one never used.");
71	        }
72	        claims.flush();
73	        try {
74	            jdbc.update("INSERT INTO sheet (id, created_at, today, policy_date, period_numbering_from, entry_date,"
75	                    + " grace_days, pot, alert_threshold, parent_id, fiscal_start_month, escalate_after, review_sla, pending_sla, max_open, proof_kinds,"
76	                    + " score_mid, score_high, score_log, added_grades, cloned_from)"
77	                    + " SELECT ?, CURRENT_TIMESTAMP, today, policy_date, period_numbering_from, entry_date, grace_days, pot,"
78	                    + " alert_threshold, parent_id, fiscal_start_month, escalate_after, review_sla, pending_sla, max_open, proof_kinds, score_mid, score_high, score_log, added_grades, id"
79	                    + " FROM sheet WHERE id = ?",
80	                    toSheetId, sheetId);
81	        } catch (DataIntegrityViolationException e) {
82	            // another user started it at the same moment
83	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The other sheet must be one never used.");
84	        }
85	        copySettings(sheetId, toSheetId);
86	        Map<Long, Long> people = copyPeople(sheetId, toSheetId);
87	        copyPools(sheetId, toSheetId, people);
88	        copyCrews(sheetId, toSheetId, people);
89	        jdbc.update("INSERT INTO period (sheet_id, name, from_date, to_date) SELECT ?, name, from_date, to_date"
90	                + " FROM period WHERE sheet_id = ? ORDER BY id", toSheetId, sheetId);
91	        copyClaims(sheetId, toSheetId, people);
92	
93	        audit.recordOnCommit("SHEET_CLONE_MADE sheet=" + sheetId + " by=" + by + " to=" + toSheetId);
94	        audit.recordOnCommit("SHEET_CLONED sheet=" + toSheetId + " by=" + by + " from=" + sheetId);
95	        rollup.recordAll(by, toSheetId);
96	    }
