191	    private void copyClaims(String sheetId, String toSheetId, Map<Long, Long> people) {
192	        List<Claim> originals = new ArrayList<>(claims.findBySheetIdOrderByListedDescIdDesc(sheetId));
193	        originals.sort(Comparator.comparing(Claim::getListed).thenComparing(Claim::getId));
194	        Map<Long, Long> copies = new LinkedHashMap<>();
195	        for (Long person : people.keySet()) {
196	            for (Claim c : originals) {
197	                if (!c.getPersonId().equals(person)) {
198	                    continue;
199	                }
200	                Long copy = insert("INSERT INTO claim (sheet_id, person_id, amount, claim_date, note, status,"
201	                        + " settled_due, opened_by, edited_by, corrects, split_from, rounds_on, due_by, terms,"
202	                        + " deferred_until, deferred_on, reminded_on, late_entry, proofs, proof_photos, ref, tags, void_reason,"
203	                        + " added_mark, escalated, waived_on, held, due_by_set) SELECT ?, ?, amount, claim_date, note, status, settled_due, opened_by,"
204	                        + " edited_by, corrects, split_from, rounds_on, due_by, terms, deferred_until, deferred_on,"
205	                        + " reminded_on, late_entry, proofs, proof_photos, ref, tags, void_reason, added_mark, escalated, waived_on, held, due_by_set FROM claim"
206	                        + " WHERE id = ?", toSheetId,
207	                        people.get(person), c.getId());
208	                copies.put(c.getId(), copy);
209	                jdbc.update("INSERT INTO claim_log (claim_id, status, by_user, on_date, due) SELECT ?, status,"
210	                        + " by_user, on_date, due FROM claim_log WHERE claim_id = ? ORDER BY id", copy, c.getId());
211	                jdbc.update("INSERT INTO claim_comment (claim_id, by_user, on_date, text) SELECT ?, by_user,"
212	                        + " on_date, text FROM claim_comment WHERE claim_id = ? ORDER BY id", copy, c.getId());
213	                jdbc.update("INSERT INTO claim_line (claim_id, label, qty, unit) SELECT ?, label, qty, unit"
214	                        + " FROM claim_line WHERE claim_id = ? ORDER BY id", copy, c.getId());
215	            }
216	        }
217	
218	        Map<Long, Claim> numbered = new LinkedHashMap<>();
219	        for (Claim c : originals) {
220	            if (c.getNumber() != null) {
221	                numbered.put(copies.get(c.getId()), c);
222	            }
223	        }
224	        List<Claim> cloned = new ArrayList<>(claims.findAllById(numbered.keySet()));
225	        // numbered afresh in the order they were opened, then added
226	        cloned.sort(Comparator.comparing(Claim::openedOn, Comparator.nullsFirst(Comparator.naturalOrder()))
227	                .thenComparing(Claim::getId));
228	        Map<String, String> renumbered = new HashMap<>();
229	        for (Claim c : cloned) {
230	            claimService.numberCopy(toSheetId, c);
231	            claims.saveAndFlush(c);
232	            renumbered.put(numbered.get(c.getId()).getNumber(), c.getNumber());
233	        }
234	        // a claim naming another by number names it by its new one
235	        for (Claim c : claims.findAllById(copies.values())) {
236	            if (c.getCorrects() != null || c.getSplitFrom() != null) {
237	                c.setCorrects(c.getCorrects() == null ? null : renumbered.get(c.getCorrects()));
238	                c.setSplitFrom(c.getSplitFrom() == null ? null : renumbered.get(c.getSplitFrom()));
239	                claims.saveAndFlush(c);
240	            }
241	        }
242	        // listed in the order they were listed on the sheet
243	        for (Claim c : originals) {
244	            claims.relist(copies.get(c.getId()));
245	        }
246	    }
