561	    /**
562	     * Writes a reminder for an OPEN or PENDING claim, which shows the sheet's today as its reminded date. Refused for
563	     * a claim in any other status and one already reminded on the sheet's today; a reminder changes none of the
564	     * claim's figures, so one whose due-by falls in a closed period may still be reminded. When the sheet has an
565	     * escalation gap and the claim's previous reminder was at least that many days before the sheet's today, the
566	     * claim is escalated: an ESCALATE line follows the REMIND line, once per claim ever.
567	     */
568	    @Transactional
569	    public Claim remind(String by, String sheetId, Long id) {
570	        sheets.lock(sheetId);
571	        Claim claim = claims.findWithLockByIdAndSheetId(id, sheetId)
572	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
573	        if (!claim.getStatus().isOpen()) {
574	            throw new ResponseStatusException(HttpStatus.CONFLICT,
575	                    "A " + claim.getStatus() + " claim cannot be reminded.");
576	        }
577	        Sheet sheet = sheets.load(sheetId);
578	        LocalDate today = sheet.getToday();
579	        if (today != null && today.equals(claim.getRemindedOn())) {
580	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The claim was already reminded today.");
581	        }
582	        Integer gap = sheet.getEscalateAfter();
583	        LocalDate previous = claim.getRemindedOn();
584	        boolean escalate = gap != null && !claim.isEscalated() && previous != null && today != null
585	                && !previous.plusDays(gap).isAfter(today);
586	        claim.setRemindedOn(today);
587	        if (escalate) {
588	            claim.setEscalated(true);
589	        }
590	        Claim saved = claims.saveAndFlush(claim);
591	        Person person = person(sheetId, saved.getPersonId());
592	        audit.recordOnCommit(record("REMIND", by, person, saved));
593	        if (escalate) {
594	            audit.recordOnCommit(record("ESCALATE", by, person, saved));
595	        }
596	        return saved;
597	    }
