627	    /**
628	     * Shares the claim with another person of its sheet, who holds the share (two decimals, more than 0.00) of it:
629	     * their due-total counts their part, the claim's amount times the share divided by 100 times the rate of their
630	     * own grade in force on the claim's date divided by 100, rounded like the claim (0.00 when their grade has no
631	     * rate), and its own person's counts the claim's due less those parts. A settled or bound claim keeps its parts as
632	     * frozen: its due times each share divided by 100, rounded half to even.
633	     * Refused for the claim's own person, a person already holding a share of it, shares totalling more than 100.00, and a SETTLED, VOID or DELETED claim.
634	     */
635	    @Transactional
636	    public Claim share(String by, String sheetId, Long id, Long personId, BigDecimal share) {
637	        if (share == null || share.signum() <= 0 || share.stripTrailingZeros().scale() > 2) {
638	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
639	                    "A share is more than 0.00, with up to two decimals.");
640	        }
641	        // a share leaves the claim itself as it is, so one due by a date in a closed period can still be shared
642	        sheets.lock(sheetId);
643	        Claim claim = claims.findWithLockByIdAndSheetId(id, sheetId)
644	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such claim."));
645	        ClaimStatus status = claim.getStatus();
646	        if (status == ClaimStatus.SETTLED || status == ClaimStatus.VOID || status == ClaimStatus.DELETED) {
647	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A " + status + " claim cannot be shared.");
648	        }
649	        Person holder = person(sheetId, personId);
650	        if (holder.getId().equals(claim.getPersonId())) {
651	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A claim cannot be shared with its own person.");
652	        }
653	        if (claim.getShares().stream().anyMatch(s -> s.getPersonId().equals(holder.getId()))) {
654	            throw new ResponseStatusException(HttpStatus.CONFLICT, holder.getName() + " already holds a share.");
655	        }
656	        BigDecimal scaled = share.setScale(2, RoundingMode.UNNECESSARY);
657	        if (claim.sharedTotal().add(scaled).compareTo(BigDecimal.valueOf(100)) > 0) {
658	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The shares would total more than 100.00.");
659	        }
660	        RollupService.Snapshot before = rollup.snapshot(sheetId);
661	        claim.share(holder.getId(), scaled);
662	        Claim saved = claims.saveAndFlush(claim);
663	        audit.recordOnCommit(record("CLAIM_SHARED", by, person(sheetId, saved.getPersonId()), saved) + " with="
664	                + holder.getName() + " share=" + scaled.toPlainString());
665	        rollup.recordChanges(by, sheetId, before);
666	        return saved;
667	    }
