763	    /**
764	     * Refuses settling or approving the claim at the due (null for n/a) when the due is above the proof threshold in
765	     * force on the claim's date (its person's grade's then when one is set, else the sheet's) and the claim has no
766	     * proof, or while the sheet's proof kinds are set, lacks a proof of any of them; an n/a due is within any
767	     * threshold.
768	     */
769	    private void refuseWithoutProof(String sheetId, Claim claim, BigDecimal due) {
770	        String grade = person(sheetId, claim.getPersonId()).gradeOn(claim.getDate());
771	        Sheet sheet = sheets.load(sheetId);
772	        BigDecimal threshold = sheet.proofThresholdFor(grade, claim.getDate());
773	        if (threshold == null || due == null || due.compareTo(threshold) <= 0) {
774	            return;
775	        }
776	        if (claim.getProofs() == 0) {
777	            throw new ResponseStatusException(HttpStatus.CONFLICT,
778	                    "A claim with a due above " + threshold.toPlainString() + " needs a proof first.");
779	        }
780	        for (String kind : sheet.proofKindList()) {
781	            if (claim.proofsOf(kind) == 0) {
782	                throw new ResponseStatusException(HttpStatus.CONFLICT,
783	                        "A claim with a due above " + threshold.toPlainString() + " needs a " + kind + " proof first.");
784	            }
785	        }
786	    }
