792	    /**
793	     * Refuses opening a claim whose due-by falls in a period with a cap when its person already has that many OPEN or
794	     * PENDING claims due by a date in it. The sheet stays locked until the transaction ends, so two opens are counted
795	     * in turn.
796	     */
797	    private void refuseOverPeriodCap(String sheetId, Claim claim) {
798	        Period period = periods.findFirstBySheetIdAndFromLessThanEqualAndToGreaterThanEqual(sheetId,
799	                claim.getDueBy(), claim.getDueBy()).orElse(null);
800	        if (period == null || period.getCap() == null) {
801	            return;
802	        }
803	        long held = claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, claim.getPersonId()).stream()
804	                .filter(c -> !c.getId().equals(claim.getId()))
805	                .filter(c -> c.getStatus() == ClaimStatus.OPEN || c.getStatus() == ClaimStatus.PENDING)
806	                .filter(c -> period.contains(c.getDueBy()))
807	                .count();
808	        if (held >= period.getCap()) {
809	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The person already has " + period.getCap()
810	                    + " open claims in period " + period.getName() + ".");
811	        }
812	    }
