905	     * A steward approves a pending claim: it is settled, its due fixed at the live figure it shows now. Refused
906	     * unless it is pending, unless the user is a steward, for the user who opened it or last edited it, and in a
907	     * closed period.
908	     */
909	    @Transactional
910	    public Claim approve(String by, String sheetId, Long id) {
911	        Claim claim = pendingClaim(by, sheetId, id);
912	        if (by.equals(claim.getOpenedBy())) {
913	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The user who opened a claim cannot approve it.");
914	        }
915	        if (by.equals(claim.getEditedBy())) {
916	            throw new ResponseStatusException(HttpStatus.CONFLICT,
917	                    "The user who last edited a claim cannot approve it.");
918	        }
919	        RollupService.Snapshot before = rollup.snapshot(sheetId);
920	        Person person = person(sheetId, claim.getPersonId());
921	        BigDecimal fixed = due(sheetId, person, claim);
922	        refuseWithoutProof(sheetId, claim, fixed);
923	        claim.setSettledDue(fixed);
924	        numberOnSettle(sheetId, claim);
925	        claim.setStatus(ClaimStatus.SETTLED);
926	        logStatus(by, sheetId, person, claim);
927	        Claim saved = claims.saveAndFlush(claim);
928	        audit.recordOnCommit(record("CLAIM_APPROVED", by, person, saved) + " due="
929	                + (fixed == null ? "n/a" : fixed.toPlainString()));
930	        watches.notifyWatchers(by, sheetId, person, saved.getNumber());
931	        rollup.recordChanges(by, sheetId, before);
