1325	    /**
1326	     * Previews the grade's rate at the percent on every date, saving nothing: the OPEN and PENDING claims whose
1327	     * person has the grade in force on the claim's date and whose due would differ, and the sum of new due minus
1328	     * current due (an n/a due counts as 0.00). A claim bound by a statement does not change.
1329	     */
1330	    @Transactional(readOnly = true)
1331	    public RatePreview previewRate(String sheetId, String grade, BigDecimal pct) {
1332	        Sheet sheet = sheets.load(sheetId);
1333	        if (!sheet.isGrade(grade)) {
1334	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY, "No such grade: " + grade + ".");
1335	        }
1336	        int count = 0;
1337	        BigDecimal diff = BigDecimal.ZERO.setScale(2);
1338	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
1339	            if (!claim.getStatus().isOpen() || claim.getSettledDue() != null || claim.isBound()) {
1340	                continue;
1341	            }
1342	            Person person = person(sheetId, claim.getPersonId());
1343	            if (!grade.equals(person.gradeOn(claim.getDate()))) {
1344	                continue;
1345	            }
1346	            BigDecimal current = due(sheetId, person, claim);
1347	            BigDecimal figure = dueOn(claim.getAmount(), pct, sheet.roundingOn(claim.getRoundsOn()));
1348	            BigDecimal next = liveDue(figure, claim, person, sheet, true);
1349	            BigDecimal before = current == null ? BigDecimal.ZERO : current;
1350	            if (current == null || before.compareTo(next) != 0) {
1351	                count++;
1352	                diff = diff.add(next.subtract(before));
1353	            }
1354	        }
1355	        return new RatePreview(count, diff.setScale(2));
1356	    }
