1380	    /**
1381	     * The live due of a claim on its (unfloored) figure: its floored figure (the greater of the floor in force on its
1382	     * date and the figure) plus the late charge gained on that floored figure (when charged); a correction has neither
1383	     * floor nor charge. Null (n/a) for an n/a figure.
1384	     */
1385	    public static BigDecimal liveDue(BigDecimal figure, Claim claim, Person person, Sheet sheet, boolean charged) {
1386	        if (figure == null || claim.isCorrection()) {
1387	            return figure;
1388	        }
1389	        BigDecimal base = sheet == null ? figure : floored(figure, sheet.floorOn(claim.getDate()));
1390	        return charged ? withLateCharge(base, claim, person, sheet) : base;
1391	    }
