1393	    /**
1394	     * The figure (null for n/a) of the claim, with a late charge added for every full 30 days it is overdue (past its
1395	     * late-from: its due-by plus its grace) by the sheet's today: for each such boundary (its late-from plus 30, 60,
1396	     * 90 ... days), the sheet's late
1397	     * percent in force on that boundary date of the figure plus the charges of the boundaries before it (it
1398	     * compounds), rounded like its due; a boundary whose percent is 0.00 adds nothing. A deferred claim is not overdue; a waived one bears no charge. While a statement binds the
1399	     * claim, its due as shown then (this charge included) stands instead.
1400	     */
1401	    public static BigDecimal withLateCharge(BigDecimal figure, Claim claim, Person person, Sheet sheet) {
1402	        if (figure == null || sheet == null || sheet.getToday() == null || claim.isDeferredOn(sheet.getToday())
1403	                || claim.isWaivedOn(sheet.getToday())) {
1404	            return figure;
1405	        }
1406	        LocalDate lateFrom = lateFrom(claim, person, sheet);
1407	        long overdue = ChronoUnit.DAYS.between(lateFrom, sheet.getToday());
1408	        long periods = overdue > 0 ? overdue / 30 : 0;
1409	        RoundingMode rounding = sheet.roundingOn(claim.getRoundsOn());
1410	        BigDecimal due = figure;
1411	        for (long k = 1; k <= periods; k++) {
1412	            BigDecimal latePct = sheet.latePctOn(lateFrom.plusDays(30 * k));
1413	            if (latePct.signum() != 0) {
1414	                due = due.add(dueOn(due, latePct, rounding));
1415	            }
1416	        }
1417	        return due;
1418	    }
