1463	    /** Refuses a correction of the amount that exceeds what remains of the claim with the number it corrects. */
1464	    private void refuseOverCorrection(String sheetId, Long personId, BigDecimal amount, String corrects, Long editing) {
1465	        List<Claim> all = claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId);
1466	        BigDecimal remains = all.stream().filter(c -> corrects.equals(c.getNumber())).map(Claim::getAmount)
1467	                .findFirst().orElse(BigDecimal.ZERO);
1468	        for (Claim c : all) {
1469	            if (corrects.equals(c.getCorrects()) && !c.getId().equals(editing) && c.getStatus() != ClaimStatus.VOID
1470	                    && c.getStatus() != ClaimStatus.DELETED) {
1471	                remains = remains.add(c.getAmount());
1472	            }
1473	        }
1474	        if (amount.negate().compareTo(remains) > 0) {
1475	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
1476	                    "A correction may not exceed what remains of the claim it corrects ("
1477	                            + scaled(remains.max(BigDecimal.ZERO)) + ").");
