133	public class SheetController {
134	
135	    /** A sheet as the screen shows it; lastBatch is the number of its last bulk settle batch, null for none. */
136	    public record SheetView(String id, LocalDate today, boolean archived, Integer lastBatch) {
137	        public static SheetView of(Sheet sheet) {
138	            return new SheetView(sheet.getId(), sheet.getToday(), sheet.isArchived(),
139	                    sheet.getLastSettleBatch() == 0 ? null : sheet.getLastSettleBatch());
140	        }
141	    }
142	
143	    public record TodayChange(@NotNull LocalDate today) {
144	    }
145	
146	    /** The id of the sheet to clone this one to. */
147	    public record CloneForm(@NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String toSheetId) {
148	    }
149	
150	    private final SheetService service;
151	    private final SheetCloneService clones;
152	    private final AsOfService asOf;
153	    private final SettingsService settings;
154	
155	    public SheetController(SheetService service, SheetCloneService clones, AsOfService asOf,
156	            SettingsService settings) {
157	        this.service = service;
158	        this.clones = clones;
159	        this.asOf = asOf;
160	        this.settings = settings;
161	    }
162	
163	    /** Load a sheet by id, starting it empty if it was never loaded before. */
164	    @PutMapping("/{id}")
165	    @ViewerPasses
166	    @AsOfReads
167	    public SheetView load(@PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String id) {
168	        return SheetView.of(service.load(id));
169	    }
170	
171	    /** Change the sheet's today; refused for a role the permission matrix does not let change it. */
172	    @PutMapping("/{id}/today")
173	    public SheetView setToday(@PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String id,
174	            @Valid @RequestBody TodayChange change, @SessionAttribute(SessionController.USER) String user) {
175	        settings.refuseUnlessMay(id, user, "today");
176	        return SheetView.of(service.setToday(user, id, change.today()));
177	    }
178	
179	    /** Clones the sheet to another id never used before; only a steward may. */
180	    @PostMapping("/{id}/clone")
181	    public void cloneSheet(@PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9_.-]+") String id,
182	            @Valid @RequestBody CloneForm form, @SessionAttribute(SessionController.USER) String user) {
183	        clones.cloneSheet(user, id, form.toSheetId());
184	        // the request's own sheet is stored as it now stands once answered; the clone is new too
185	        asOf.capture(form.toSheetId());
186	    }
187	}
