     1	import { HttpContextToken, HttpInterceptorFn } from '@angular/common/http';
     2	import { Injectable, inject, signal } from '@angular/core';
     3	
     4	// The date this user's screen shows the sheet as of (yyyy-mm-dd), or null for as it stands now. It belongs to the
     5	// screen: other users are unaffected.
     6	@Injectable({ providedIn: 'root' })
     7	export class AsOf {
     8	  readonly date = signal<string | null>(null);
     9	}
    10	
    11	// Marks a request answered as the sheet stands now, whatever date the screen shows it as of.
    12	export const LIVE = new HttpContextToken<boolean>(() => false);
    13	
    14	// Sends the as-of date with every request (but one marked LIVE), so the server answers as of it and refuses every
    15	// change.
    16	export const asOfInterceptor: HttpInterceptorFn = (req, next) => {
    17	  const date = req.context.get(LIVE) ? null : inject(AsOf).date();
    18	  return next(date ? req.clone({ setHeaders: { 'X-As-Of': date } }) : req);
    19	};
