    13	        @for (r of nav; track r.path) {
    14	          <a
    15	            [routerLink]="'/' + r.path"
    16	            [attr.data-testid]="'nav-' + r.data!['section']"
    17	            >{{ r.data!['label'] }}</a
    18	          >
    19	        }
    20	      </nav>
    21	      <main data-testid="app-home">
    22	        <router-outlet />
    23	      </main>
    24	    </div>
    25	  `,
    26	})
