1	package net.officefloor.hq.app.claim;
2	
3	import java.math.BigDecimal;
4	import java.math.RoundingMode;
5	import java.time.LocalDate;
6	import java.util.ArrayList;
7	import java.util.Comparator;
8	import java.util.HashMap;
9	import java.util.List;
10	import java.util.Map;
11	import java.util.Set;
12	import java.util.function.Function;
13	import net.officefloor.hq.app.Audit;
14	import net.officefloor.hq.app.person.Person;
15	import net.officefloor.hq.app.person.PersonRepository;
16	import net.officefloor.hq.app.settings.SettingsService;
17	import org.springframework.stereotype.Service;
18	import org.springframework.transaction.PlatformTransactionManager;
19	import org.springframework.transaction.support.TransactionTemplate;
20	import org.springframework.web.server.ResponseStatusException;
21	
22	/** Status changes made to several claims together: opens, moves, re-dates and voids each one on its own, a settle all or nothing. */
23	@Service
24	public class ClaimBulkService {
25	
26	    /** The claims a bulk action changed, in the order it took them, and how many it refused. */
27	    public record Result(List<Claim> changed, int refused) {
28	    }
29	
30	    /** The claims a bulk settle settled or made PENDING, how many it refused, and its batch number (null for none). */
31	    public record SettleResult(List<Claim> settled, int refused, Integer batch) {
32	    }
33	
34	    private final ClaimService claims;
35	    private final ClaimRepository repository;
36	    private final PersonRepository people;
37	    private final SettingsService settings;
38	    private final Audit audit;
39	    private final TransactionTemplate transactions;
40	
41	    public ClaimBulkService(ClaimService claims, ClaimRepository repository, PersonRepository people,
42	            SettingsService settings, Audit audit, PlatformTransactionManager transactionManager) {
43	        this.claims = claims;
44	        this.repository = repository;
45	        this.people = people;
46	        this.settings = settings;
47	        this.audit = audit;
48	        this.transactions = new TransactionTemplate(transactionManager);
49	    }
50	
51	    /**
52	     * Opens each of the claims that can be opened, in list order (the order of people, newest claim first within a
53	     * person), so they are numbered in that order. Each is opened in its own transaction: one that is refused, or is
54	     * not a claim of the sheet, is left as it is and counted as refused; one that goes to REVIEW counts as opened.
55	     */
56	    public Result open(String by, String sheetId, Set<Long> ids) {
57	        return each(by, sheetId, ids, id -> claims.changeStatus(by, sheetId, id, ClaimStatus.OPEN));
58	    }
59	
60	    /**
61	     * Settles the claims all or nothing, by the rules of settling one claim: one the clerk limit makes PENDING counts
62	     * as settled. When any of them is refused, or is not a claim of the sheet, none is settled, every one counts as
63	     * refused and nothing is written. Otherwise each is settled in list order in the one transaction, which is the
64	     * sheet's next batch: each claim it settled keeps the batch's number, and after the claims' own records a
65	     * BATCH_SETTLED record gives the batch, its count and the frozen figures of those SETTLED added up.
66	     */
67	    public SettleResult settle(String by, String sheetId, Set<Long> ids) {
68	        SettleResult refusedAll = new SettleResult(List.of(), ids.size(), null);
69	        if (settings.isReadOnly(sheetId, by)) {
70	            return refusedAll;
71	        }
72	        List<Long> ordered = ordered(sheetId, ids);
73	        if (ordered.isEmpty() || ordered.size() != ids.size()) {
74	            return refusedAll;
75	        }
76	        return transactions.execute(status -> {
77	            List<Claim> settled = new ArrayList<>();
78	            for (Long id : ordered) {
79	                try {
80	                    settled.add(claims.changeStatus(by, sheetId, id, ClaimStatus.SETTLED));
81	                } catch (ResponseStatusException e) {
82	                    // one refused refuses them all: the rollback drops every change and every record
83	                    status.setRollbackOnly();
84	                    return refusedAll;
85	                }
86	            }
87	            int batch = claims.numberSettleBatch(sheetId, settled.stream().map(Claim::getId).toList());
88	            settled.forEach(c -> c.setSettleBatch(batch));
89	            BigDecimal total = settled.stream()
90	                    .filter(c -> c.getStatus() == ClaimStatus.SETTLED && c.getSettledDue() != null)
91	                    .map(Claim::getSettledDue).reduce(BigDecimal.ZERO, BigDecimal::add)
92	                    .setScale(2, RoundingMode.HALF_UP);
93	            audit.recordOnCommit("BATCH_SETTLED sheet=" + sheetId + " by=" + by + " batch=" + batch + " count="
94	                    + settled.size() + " total=" + total.toPlainString());
95	            return new SettleResult(settled, 0, batch);
96	        });
97	    }
98	
99	    /**
100	     * Moves each of the claims that can be moved to the person, in list order, by the rules of moving one claim. Each
101	     * is moved in its own transaction: one that is refused, or is not a claim of the sheet, is left as it is and
102	     * counted as refused.
103	     */
104	    public Result reassign(String by, String sheetId, Set<Long> ids, Long toPersonId) {
105	        return each(by, sheetId, ids, id -> claims.reassign(by, sheetId, id, toPersonId, true));
106	    }
107	
108	    /**
109	     * Re-dates each of the claims that can be re-dated to the date, in list order, by the rules of re-dating one claim.
110	     * Each is re-dated in its own transaction: one that is refused, or is not a claim of the sheet, is left as it is and
111	     * counted as refused.
112	     */
113	    public Result redate(String by, String sheetId, Set<Long> ids, LocalDate date) {
114	        return each(by, sheetId, ids, id -> claims.redate(by, sheetId, id, date));
115	    }
116	
117	    /**
118	     * Voids each of the claims that can be voided with the reason, in list order, by the rules of voiding one claim.
119	     * Each is voided in its own transaction: one that is refused, or is not a claim of the sheet, is left as it is and
120	     * counted as refused.
121	     */
122	    public Result voidAll(String by, String sheetId, Set<Long> ids, String reason) {
123	        return each(by, sheetId, ids, id -> claims.voidClaim(by, sheetId, id, reason));
124	    }
125	
126	    /**
127	     * Applies the change to each of the sheet's claims among the ids in list order, counting the refused ones. A
128	     * viewer, or anyone on an archived sheet, changes none: every one is refused.
129	     */
130	    private Result each(String by, String sheetId, Set<Long> ids, Function<Long, Claim> change) {
131	        if (settings.isReadOnly(sheetId, by)) {
132	            return new Result(List.of(), ids.size());
133	        }
134	        List<Long> ordered = ordered(sheetId, ids);
135	        List<Claim> changed = new ArrayList<>();
136	        int refused = ids.size() - ordered.size();
137	        for (Long id : ordered) {
138	            try {
139	                changed.add(change.apply(id));
140	            } catch (ResponseStatusException e) {
141	                refused++;
142	            }
143	        }
144	        return new Result(changed, refused);
145	    }
146	
147	    /** The ids of the sheet's claims among the ids, in list order (the order of people, newest claim first). */
148	    private List<Long> ordered(String sheetId, Set<Long> ids) {
149	        Map<Long, Integer> personOrder = new HashMap<>();
150	        for (Person p : people.findBySheetIdOrderByPositionAscIdAsc(sheetId)) {
151	            personOrder.put(p.getId(), personOrder.size());
152	        }
153	        return repository.findBySheetIdOrderByListedDescIdDesc(sheetId).stream()
154	                .filter(c -> ids.contains(c.getId()))
155	                .sorted(Comparator.comparing((Claim c) -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE))
156	                        .thenComparing(Claim::getListed, Comparator.reverseOrder())
157	                        .thenComparing(Claim::getId, Comparator.reverseOrder()))
158	                .map(Claim::getId).toList();
159	    }
160	}
