70	    /**
71	     * A steward merges the person into another person of the sheet. The merged person's claims move to the other
72	     * (numbers and dates kept), listed after the other's in the order they were added, each keeping any figure a
73	     * statement bound; their name and aliases become the other's aliases; their patrons are added to the other's (not
74	     * the other themselves, no repeats), anyone naming them as patron names the other instead (no repeats), and their
75	     * pool memberships and plans move to the other (shares added, at most 100.00, where the other is already a member), as
76	     * do the crews they lead and their crew memberships (one the other already has, or leads, dropped); a
77	     * closed period's figure fixed for them is added to the other's. Their statements pass to the other, standing
78	     * before the other's own (the other's last statement stays theirs, or, having none, becomes the merged person's);
79	     * their holds, watchers and contact are dropped, and they leave the sheet. Refused unless the user is a steward, for the same person, and when
80	     * either of them is retired. The person merged into, as saved.
81	     */
82	    @Transactional
83	    public Person merge(String by, String sheetId, Long id, Long intoId) {
84	        if (!settings.isSteward(sheetId, by)) {
85	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can merge people.");
86	        }
87	        if (id.equals(intoId)) {
88	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A person cannot be merged into themselves.");
89	        }
90	        Person from = people.findWithLockByIdAndSheetId(id, sheetId)
91	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
92	        Person into = people.findWithLockByIdAndSheetId(intoId, sheetId)
93	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
94	        if (from.isRetired() || into.isRetired()) {
95	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A retired person cannot be merged.");
96	        }
97	        RollupService.Snapshot before = rollup.snapshot(sheetId);
98	        // the merged person is kept as they stand, so the merge can be undone
99	        long mergeId = records.keep(sheetId, from.getId(), into.getId(), by, sheets.load(sheetId).getToday());
100	        List<String> had = into.getAliases();
101	        Person saved = absorb(by, sheetId, from, into);
102	        records.keepGiven(mergeId, saved.getAliases().stream().filter(a -> !had.contains(a)).toList());
103	        rollup.recordChanges(by, sheetId, before);
104	        return saved;
105	    }
106	
107	    /**
108	     * The steward who made the last merge into the person undoes it on the sheet's today it was made: the merged
109	     * person is back, at the end of the list, as they were before it (with their grades, holds, terms and own
110	     * aliases, and their contact unless someone has it now), with the claims that came from them still the other's
111	     * (their numbers and status as they are now); the aliases the merge gave the other leave them. Patron, pool,
112	     * crew, plan, period and statement changes of the merge stay. Refused unless the user is a steward and the one who
113	     * made the merge, on any later day, for a person whose last merge into them is undone or who has none, and when
114	     * the merged person's name or an alias is someone else's now. The person brought back, as saved.
115	     */
116	    @Transactional
117	    public Person undo(String by, String sheetId, Long intoId) {
118	        if (!settings.isSteward(sheetId, by)) {
119	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can undo a merge.");
120	        }
121	        Person into = people.findWithLockByIdAndSheetId(intoId, sheetId)
122	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
123	        PersonMergeRecords.Merge merge = records.lastInto(sheetId, intoId).filter(m -> !m.undone())
124	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.CONFLICT, "There is no merge to undo."));
125	        if (!by.equals(merge.madeBy())) {
126	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only the steward who made the merge can undo it.");
127	        }
128	        if (!Objects.equals(merge.madeOn(), sheets.load(sheetId).getToday())) {
129	            throw new ResponseStatusException(HttpStatus.CONFLICT,
130	                    "A merge can only be undone on the day it was made.");
131	        }
132	        RollupService.Snapshot before = rollup.snapshot(sheetId);
133	
134	        // the aliases the merge gave the other leave them
135	        into.removeAliases(records.given(merge.id()));
136	        people.saveAndFlush(into);
137	        String name = records.name(merge.id());
138	        List<String> names = new ArrayList<>();
139	        names.add(name);
140	        names.addAll(records.aliases(merge.id()));
141	        if (names.stream().anyMatch(n -> people.nameOrAliasInUse(sheetId, n))) {
142	            throw new ResponseStatusException(HttpStatus.CONFLICT,
143	                    "The merged person's name or an alias is someone else's now.");
144	        }
145	        String contact = records.contact(merge.id());
146	        if (contact != null && people.existsBySheetIdAndContact(sheetId, contact)) {
147	            contact = null;
148	        }
149	        records.restore(merge.id(), people.nextPosition(sheetId), contact);
150	
151	        // the claims that came from them, still the other's, go back in the order they are listed
152	        List<Claim> back = new ArrayList<>(claims.findAllById(records.claims(merge.id())).stream()
153	                .filter(c -> c.getSheetId().equals(sheetId) && intoId.equals(c.getPersonId())).toList());
154	        back.sort(Comparator.comparing(Claim::getListed, Comparator.nullsFirst(Comparator.naturalOrder()))
155	                .thenComparing(Claim::getId));
156	        for (Claim c : back) {
157	            c.setPersonId(merge.fromId());
158	            claims.saveAndFlush(c);
159	            claims.relist(c.getId());
160	        }
161	
162	        audit.recordOnCommit("PERSON_MERGE_UNDONE sheet=" + sheetId + " by=" + by + " name=" + name + " from="
163	                + into.getName());
164	        rollup.recordChanges(by, sheetId, before);
165	        return people.findByIdAndSheetId(merge.fromId(), sheetId).orElseThrow();
166	    }
167	
168	    /**
169	     * Merges the one person into the other, both of the sheet and locked, exactly as a merge does, recording it; the
170	     * caller checks the merge may be made and records the changes to the figures.
171	     */
172	    Person absorb(String by, String sheetId, Person from, Person into) {
173	        // the claims, in the order they were added, each listed as the other's newest in turn
174	        List<Claim> moved = new ArrayList<>(claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, from.getId()));
175	        moved.sort(Comparator.comparing(Claim::getId));
176	        for (Claim c : moved) {
177	            c.setPersonId(into.getId());
178	            claims.saveAndFlush(c);
179	            claims.relist(c.getId());
180	        }
181	
182	        plans.movePlans(sheetId, from.getId(), into.getId());
183	        mergePatrons(sheetId, from.getId(), into.getId());
184	        mergePools(sheetId, from.getId(), into.getId());
185	        crews.merged(sheetId, from.getId(), into.getId());
186	        for (Period p : periods.findBySheetIdOrderByFromAsc(sheetId)) {
187	            p.mergePersonTotal(from.getId(), into.getId());
188	        }
189	        periods.flush();
190	        mergeStatements(sheetId, from.getId(), into.getId());
191	        watches.deleteAll(watches.findByPersonIdOrderByIdAsc(from.getId()));
192	        statements.flush();
193	        watches.flush();
194	
195	        String fromName = from.getName();
196	        List<String> names = new ArrayList<>();
197	        names.add(fromName);
198	        names.addAll(from.getAliases());
199	        people.delete(from);
200	        people.flush();
201	        // one they already have exactly is not given twice
202	        names.stream().filter(n -> !n.equals(into.getName()) && !into.getAliases().contains(n)).forEach(into::addAlias);
203	        Person saved = people.saveAndFlush(into);
204	
205	        audit.recordOnCommit("PERSON_MERGED sheet=" + sheetId + " by=" + by + " from=" + fromName + " into="
206	                + saved.getName());
207	        return saved;
208	    }
209	
210	    /**
211	     * The merged person's statements pass to the other, in their order, standing before the other's own, so the
212	     * other's last statement stays theirs (or, having none, becomes the merged person's).
213	     */
214	    private void mergeStatements(String sheetId, Long from, Long into) {
215	        List<Statement> moved = statements.findBySheetIdAndPersonIdInOrder(sheetId, from);
216	        List<Statement> theirs = statements.findBySheetIdAndPersonIdInOrder(sheetId, into);
217	        long place = theirs.isEmpty() ? 0 : theirs.get(0).getPlace() - moved.size();
218	        for (Statement s : moved) {
219	            s.moveTo(sheetId, into, theirs.isEmpty() ? s.getPlace() : place++);
220	        }
221	    }
222	
223	    /** The merged person's patrons pass to the other, and whoever named them names the other; never twice, nor self. */
224	    private void mergePatrons(String sheetId, Long from, Long into) {
225	        for (Patron p : patrons.findBySheetIdOrderByIdAsc(sheetId)) {
226	            if (!p.getPersonId().equals(from)) {
227	                continue;
228	            }
229	            if (p.getPatronId().equals(into) || patrons.existsByPersonIdAndPatronId(into, p.getPatronId())) {
230	                patrons.delete(p);
231	            } else {
232	                p.setPersonId(into);
233	                patrons.save(p);
234	            }
235	            patrons.flush();
236	        }
237	        for (Patron p : patrons.findBySheetIdOrderByIdAsc(sheetId)) {
238	            if (!p.getPatronId().equals(from)) {
239	                continue;
240	            }
241	            if (p.getPersonId().equals(into) || patrons.existsByPersonIdAndPatronId(p.getPersonId(), into)) {
242	                patrons.delete(p);
243	            } else {
244	                p.setPatronId(into);
245	                patrons.save(p);
246	            }
247	            patrons.flush();
248	        }
249	    }
250	
251	    /** The merged person's pool memberships pass to the other; where the other is a member, the shares are added. */
252	    private void mergePools(String sheetId, Long from, Long into) {
253	        List<PoolMember> all = poolMembers.findBySheetIdOrderByIdAsc(sheetId);
254	        for (PoolMember m : all) {
255	            if (!from.equals(m.getPersonId())) {
256	                continue;
257	            }
258	            PoolMember theirs = all.stream()
259	                    .filter(o -> o.getPoolId().equals(m.getPoolId()) && into.equals(o.getPersonId()))
260	                    .findFirst().orElse(null);
261	            if (theirs != null) {
262	                theirs.setShare(theirs.getShare().add(m.getShare()).min(HUNDRED));
263	                poolMembers.save(theirs);
264	                poolMembers.delete(m);
265	            } else {
266	                m.setPersonId(into);
267	                poolMembers.save(m);
268	            }
269	        }
270	        poolMembers.flush();
271	    }
272	}
