58	    /** The sheet's periods, by from-date. */
59	    @Transactional(readOnly = true)
60	    public List<Period> list(String sheetId) {
61	        return periods.findBySheetIdOrderByFromAsc(sheetId);
62	    }
63	
64	    /**
65	     * Adds a period; refused when its to-date is before its from-date, its name is in use on the sheet or its dates
66	     * overlap another period's. A cap, when given, is the most OPEN or PENDING claims a person may have in it.
67	     */
68	    @Transactional
69	    public Period add(String by, String sheetId, String name, LocalDate from, LocalDate to, Integer cap) {
70	        // the sheet stays locked until the transaction ends, so two periods added at once are checked in turn
71	        sheets.lock(sheetId);
72	        String trimmed = name.strip();
73	        if (to.isBefore(from)) {
74	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A period cannot end before it starts.");
75	        }
76	        if (periods.existsBySheetIdAndName(sheetId, trimmed)) {
77	            throw nameInUse();
78	        }
79	        if (periods.existsBySheetIdAndFromLessThanEqualAndToGreaterThanEqual(sheetId, to, from)) {
80	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That period overlaps another.");
81	        }
82	        Period added;
83	        try {
84	            added = periods.saveAndFlush(new Period(sheetId, trimmed, from, to, cap));
85	        } catch (DataIntegrityViolationException e) {
86	            throw nameInUse();
87	        }
88	        audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + by + " period=" + added.getName()
89	                + " from=" + added.getFrom() + " to=" + added.getTo()
90	                + (added.getCap() != null ? " cap=" + added.getCap() : ""));
91	        return added;
92	    }
93	
94	    /**
95	     * Adds one period per calendar month from the from-date's month to the to-date's month, each from the first to the
96	     * last day of its month and named yyyy-mm, by month. A month whose name is in use on the sheet or whose days
97	     * overlap a period is left out; the others are still made. Refused when the to-date is before the from-date. A user who
98	     * may change nothing (a viewer, or on an archived sheet) goes through with none made.
99	     */
100	    @Transactional
101	    public List<Period> generate(String by, String sheetId, LocalDate from, LocalDate to) {
102	        // the sheet stays locked until the transaction ends, so periods added at once are checked in turn
103	        sheets.lock(sheetId);
104	        if (to.isBefore(from)) {
105	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The to-date cannot be before the from-date.");
106	        }
107	        if (settings.isReadOnly(sheetId, by)) {
108	            return List.of();
109	        }
110	        List<Period> made = new ArrayList<>();
111	        for (YearMonth month = YearMonth.from(from); !month.isAfter(YearMonth.from(to)); month = month.plusMonths(1)) {
112	            String name = month.toString();
113	            LocalDate first = month.atDay(1);
114	            LocalDate last = month.atEndOfMonth();
115	            if (periods.existsBySheetIdAndName(sheetId, name)
116	                    || periods.existsBySheetIdAndFromLessThanEqualAndToGreaterThanEqual(sheetId, last, first)) {
117	                continue;
118	            }
119	            Period added = periods.saveAndFlush(new Period(sheetId, name, first, last));
120	            audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + by + " period=" + added.getName()
121	                    + " from=" + added.getFrom() + " to=" + added.getTo());
122	            made.add(added);
123	        }
124	        return made;
125	    }
126	
127	    /**
128	     * Adds the four calendar quarters of the year, named yyyy-Q1 to yyyy-Q4, each from the first day of its first month
129	     * to the last day of its third, by quarter. A quarter whose name is in use on the sheet or whose days overlap a
130	     * period is left out; the others are still made.
131	     */
132	    @Transactional
133	    public List<Period> generateQuarters(String by, String sheetId, int year) {
134	        // the sheet stays locked until the transaction ends, so periods added at once are checked in turn
135	        sheets.lock(sheetId);
136	        List<Period> made = new ArrayList<>();
137	        for (int quarter = 1; quarter <= 4; quarter++) {
138	            String name = String.format("%04d-Q%d", year, quarter);
139	            LocalDate first = YearMonth.of(year, quarter * 3 - 2).atDay(1);
140	            LocalDate last = YearMonth.of(year, quarter * 3).atEndOfMonth();
141	            if (periods.existsBySheetIdAndName(sheetId, name)
142	                    || periods.existsBySheetIdAndFromLessThanEqualAndToGreaterThanEqual(sheetId, last, first)) {
143	                continue;
144	            }
145	            Period added = periods.saveAndFlush(new Period(sheetId, name, first, last));
146	            audit.recordOnCommit("PERIOD_ADDED sheet=" + sheetId + " by=" + by + " period=" + added.getName()
147	                    + " from=" + added.getFrom() + " to=" + added.getTo());
148	            made.add(added);
149	        }
150	        return made;
151	    }
