153	    /**
154	     * Adds the twelve monthly periods of the fiscal year FY<year>, the one starting on the first of the sheet's fiscal
155	     * start month in that year, exactly as {@link #generate} does for its first through its last day.
156	     */
157	    @Transactional
158	    public List<Period> generateFiscalYear(String by, String sheetId, int year) {
159	        LocalDate first = YearMonth.of(year, sheets.lock(sheetId).getFiscalStartMonth()).atDay(1);
160	        return generate(by, sheetId, first, first.plusYears(1).minusDays(1));
161	    }
162	
163	    /**
164	     * Rolls the fiscal year FY<year> over: generates FY<year + 1>'s twelve monthly periods exactly as
165	     * {@link #generateFiscalYear} does, then adds each person's open figure at the end of FY<year>'s last period (the
166	     * figures of their claims that count, belonging to a period of FY<year>, still open or pending at the end of its last
167	     * day, skipping n/a) to their opening balance for FY<year + 1>'s first period, and then soft-closes every period of FY<year> still open, by
168	     * from-date, as {@link #softClose} does. Refused unless the user is a steward,
169	     * and when FY<year> has no periods. Answers the periods made.
170	     */
171	    @Transactional
172	    public List<Period> rollover(String by, String sheetId, int year) {
173	        Sheet sheet = sheets.lock(sheetId);
174	        if (!settings.isSteward(sheetId, by)) {
175	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can roll the year over.");
176	        }
177	        LocalDate today = sheet.getToday();
178	        List<Period> old = periods.findBySheetIdOrderByFromAsc(sheetId).stream()
179	                .filter(p -> sheet.fiscalYearOf(p.getFrom()) == year).toList();
180	        if (old.isEmpty()) {
181	            throw refused("FY" + year + " has no periods.");
182	        }
183	        LocalDate end = old.stream().map(Period::getTo).max(LocalDate::compareTo).orElseThrow();
184	        // the open figures are read before the new year's periods exist, so none of its claims belong to them
185	        List<Person> everyone = people.findBySheetIdOrderByPositionAscIdAsc(sheetId);
186	        Map<Long, Person> byId = everyone.stream().collect(Collectors.toMap(Person::getId, Function.identity()));
187	        Map<Long, BigDecimal> open = new HashMap<>();
188	        for (Claim c : claims.findBySheetIdOrderByIdDesc(sheetId)) {
189	            Person person = byId.get(c.getPersonId());
190	            if (person == null || c.getDueBy() == null || old.stream().noneMatch(p -> p.contains(c.getDueBy()))
191	                    || !person.countsAtEndOf(c, end, today) || !c.statusAtEndOf(end).isOpen()) {
192	                continue;
193	            }
194	            BigDecimal figure = claimService.due(sheetId, person, c);
195	            if (figure != null) {
196	                open.merge(person.getId(), figure, BigDecimal::add);
197	            }
198	        }
199	        List<Period> made = generateFiscalYear(by, sheetId, year + 1);
200	        LocalDate first = YearMonth.of(year + 1, sheet.getFiscalStartMonth()).atDay(1);
201	        Period opening = periods.findBySheetIdOrderByFromAsc(sheetId).stream().filter(p -> p.contains(first))
202	                .findFirst().orElse(null);
203	        List<PeriodRollover.Opening> set = new ArrayList<>();
204	        // a first period the rollover did not make was there already (the year was rolled over before): it is not carried into again
205	        if (opening != null && made.stream().anyMatch(p -> p.getId().equals(opening.getId()))) {
206	            for (Person person : everyone) {
207	                BigDecimal amount = open.getOrDefault(person.getId(), BigDecimal.ZERO).setScale(2);
208	                if (amount.signum() <= 0) {
209	                    continue;
210	                }
211	                opening.addOpening(person.getId(), amount);
212	                set.add(new PeriodRollover.Opening(opening.getId(), person.getId(), amount));
213	                audit.recordOnCommit("OPENING_SET sheet=" + sheetId + " by=" + by + " name=" + person.getName()
214	                        + " period=" + opening.getName() + " amount=" + amount.toPlainString());
215	            }
216	            periods.saveAndFlush(opening);
217	        }
218	        rollovers.saveAndFlush(new PeriodRollover(sheetId, by, today, year, made.stream().map(Period::getId).toList(),
219	                set));
220	        audit.recordOnCommit("ROLLOVER sheet=" + sheetId + " by=" + by + " fy=FY" + year + " periods=" + made.size());
221	        // every period of the old year still open is soft-closed, by from-date, as a soft close would
222	        for (Period period : old) {
223	            if (!period.isClosed() && !period.isSoftClosed()) {
224	                softClose(by, sheetId, period, today);
225	            }
226	        }
227	        return made;
