237	        Sheet sheet = sheets.lock(sheetId);
238	        if (!settings.isSteward(sheetId, by)) {
239	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can undo a rollover.");
240	        }
241	        PeriodRollover last = rollovers.findById(sheetId).orElseThrow(() -> refused("There is no rollover to undo."));
242	        if (!last.getMadeBy().equals(by)) {
243	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only the steward who rolled the year over can undo it.");
244	        }
245	        if (!last.getMadeOn().equals(sheet.getToday())) {
246	            throw refused("A rollover can only be undone on the day it was made.");
247	        }
248	        List<Period> made = last.getPeriodIds().stream()
249	                .map(id -> periods.findByIdAndSheetId(id, sheetId).orElse(null)).filter(p -> p != null).toList();
250	        for (Claim c : claims.findBySheetIdOrderByIdDesc(sheetId)) {
251	            if (c.getDate() != null && made.stream().anyMatch(p -> p.contains(c.getDate()))) {
252	                throw refused("A claim belongs to a period the rollover made.");
253	            }
254	        }
