353	    /**
354	     * Each person's due-total for the period now: the figures of their claims due by a date in it that counted at the end of
355	     * its last day, skipping n/a; 0.00 for a person with none.
356	     */
357	    private Map<Long, BigDecimal> personTotals(String sheetId, Period period, LocalDate today) {
358	        Map<Long, Person> byId = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
359	                .collect(Collectors.toMap(Person::getId, Function.identity()));
360	        // every person on the sheet now gets a figure, 0.00 when none of their counted claims is due by a date in it
361	        Map<Long, BigDecimal> personTotals = new HashMap<>();
362	        for (Long personId : byId.keySet()) {
363	            personTotals.put(personId, BigDecimal.ZERO.setScale(2));
364	        }
365	        for (Claim c : claims.findBySheetIdOrderByIdDesc(sheetId)) {
366	            Person person = byId.get(c.getPersonId());
367	            if (person == null || !person.countsAtEndOf(c, period.getTo(), today) || !period.contains(c.getDueBy())) {
368	                continue;
369	            }
370	            BigDecimal figure = claimService.due(sheetId, person, c);
371	            if (figure != null) {
372	                personTotals.merge(person.getId(), figure, BigDecimal::add);
373	            }
374	        }
375	        return personTotals;
376	    }
