378	    /**
379	     * Each person's carried figure for the period now: the figures of their claims belonging to a period of the sheet
380	     * that ends before this one starts and still open or pending at the end of its last day, skipping n/a, plus their
381	     * opening balance for it; 0.00 for a person with none.
382	     */
383	    private Map<Long, BigDecimal> personCarried(String sheetId, Period period, LocalDate today) {
384	        Map<Long, Person> byId = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
385	                .collect(Collectors.toMap(Person::getId, Function.identity()));
386	        List<Period> earlier = periods.findBySheetIdOrderByFromAsc(sheetId).stream()
387	                .filter(p -> p.getTo().isBefore(period.getFrom())).toList();
388	        Map<Long, BigDecimal> carried = new HashMap<>();
389	        for (Long personId : byId.keySet()) {
390	            carried.put(personId, period.getPersonOpenings().getOrDefault(personId, BigDecimal.ZERO).setScale(2));
391	        }
392	        for (Claim c : claims.findBySheetIdOrderByIdDesc(sheetId)) {
393	            Person person = byId.get(c.getPersonId());
394	            if (person == null || c.getDueBy() == null || earlier.stream().noneMatch(p -> p.contains(c.getDueBy()))
395	                    || !person.countsAtEndOf(c, period.getTo(), today)
396	                    || !c.statusAtEndOf(period.getTo()).isOpen()) {
397	                continue;
398	            }
399	            BigDecimal figure = claimService.due(sheetId, person, c);
400	            if (figure != null) {
401	                carried.merge(person.getId(), figure, BigDecimal::add);
402	            }
403	        }
404	        return carried;
405	    }
