411	    /**
412	     * Reads every pasted line of name,period,amount first (a person on the sheet by name or alias, a period on the sheet
413	     * by name, an amount of two decimals at most, 0.00 or more), then adds each line's amount to the person's opening
414	     * balance for the period, in order. One change: any line refused refuses them all, and nothing is stored or audited.
415	     * Answers how many lines went through.
416	     */
417	    @Transactional
418	    public int importOpenings(String by, String sheetId, String text) {
419	        sheets.lock(sheetId);
420	        Map<String, Period> byName = periods.findBySheetIdOrderByFromAsc(sheetId).stream()
421	                .collect(Collectors.toMap(Period::getName, Function.identity()));
422	        List<OpeningLine> lines = new ArrayList<>();
423	        int n = 0;
424	        for (String raw : text.split("\\r?\\n")) {
425	            n++;
426	            if (raw.isBlank()) {
427	                continue;
428	            }
429	            String[] f = raw.split(",", -1);
430	            if (f.length != 3) {
431	                throw refused("Line " + n + " is not name,period,amount.");
432	            }
433	            String name = f[0].strip();
434	            Person person = name.isEmpty() ? null : people.findBySheetIdAndNameOrAlias(sheetId, name).orElse(null);
435	            if (person == null) {
436	                throw refused("Line " + n + " names no one on the sheet.");
437	            }
438	            Period period = byName.get(f[1].strip());
439	            if (period == null) {
440	                throw refused("Line " + n + " names no period on the sheet.");
441	            }
442	            BigDecimal amount;
443	            try {
444	                amount = new BigDecimal(f[2].strip());
445	            } catch (NumberFormatException e) {
446	                throw refused("Line " + n + " has no amount.");
447	            }
448	            if (amount.scale() > 2 || amount.precision() - amount.scale() > 12) {
449	                throw refused("Line " + n + " has an amount with more than two decimals.");
450	            }
451	            if (amount.signum() < 0) {
452	                throw refused("Line " + n + " has an amount below 0.00.");
453	            }
454	            lines.add(new OpeningLine(person, period, amount.setScale(2)));
455	        }
456	        if (lines.isEmpty()) {
457	            throw refused("Paste at least one line of name,period,amount.");
458	        }
459	        for (OpeningLine l : lines) {
460	            l.period().addOpening(l.person().getId(), l.amount());
461	            audit.recordOnCommit("OPENING_SET sheet=" + sheetId + " by=" + by + " name=" + l.person().getName()
462	                    + " period=" + l.period().getName() + " amount=" + l.amount().toPlainString());
463	        }
464	        periods.saveAllAndFlush(lines.stream().map(OpeningLine::period).distinct().toList());
465	        return lines.size();
466	    }
