 19	/**
 20	 * A period of a sheet: a name unique on the sheet and a from and to date, inclusive. A closed period keeps the
 21	 * due-total it had when it was closed, each person's due-total and carried figure for it then, and the pools as they
 22	 * then stood (so each member's cut for it). A soft-closed period keeps them
 23	 * the same way, but claims due by a date in it can still change.
 24	 */
 25	@Entity
 26	@Table(name = "period")
 27	public class Period {
 28	
 29	    @Id
 30	    @GeneratedValue(strategy = GenerationType.IDENTITY)
 31	    private Long id;
 32	
 33	    @Column(name = "sheet_id", nullable = false)
 34	    private String sheetId;
 35	
 36	    @Column(name = "name", nullable = false)
 37	    private String name;
 38	
 39	    @Column(name = "from_date", nullable = false)
 40	    private LocalDate from;
 41	
 42	    @Column(name = "to_date", nullable = false)
 43	    private LocalDate to;
 44	
 45	    @Column(name = "claim_cap")
 46	    private Integer cap;
 47	
 48	    @Column(name = "closed", nullable = false)
 49	    private boolean closed;
 50	
 51	    @Column(name = "soft_closed", nullable = false)
 52	    private boolean softClosed;
 53	
 54	    @Column(name = "locked", nullable = false)
 55	    private boolean locked;
 56	
 57	    @Column(name = "closed_total")
 58	    private BigDecimal closedTotal;
 59	
 60	    @Column(name = "fixed_pools")
 61	    private String fixedPools;
 62	
 63	    @ElementCollection(fetch = FetchType.EAGER)
 64	    @CollectionTable(name = "period_person_total", joinColumns = @JoinColumn(name = "period_id"))
 65	    @MapKeyColumn(name = "person_id")
 66	    @Column(name = "total", nullable = false)
 67	    private Map<Long, BigDecimal> closedPersonTotals = new HashMap<>();
 68	
 69	    @ElementCollection(fetch = FetchType.EAGER)
 70	    @CollectionTable(name = "period_person_carried", joinColumns = @JoinColumn(name = "period_id"))
 71	    @MapKeyColumn(name = "person_id")
 72	    @Column(name = "carried", nullable = false)
 73	    private Map<Long, BigDecimal> closedPersonCarried = new HashMap<>();
 74	
 75	    @ElementCollection(fetch = FetchType.EAGER)
 76	    @CollectionTable(name = "period_person_opening", joinColumns = @JoinColumn(name = "period_id"))
 77	    @MapKeyColumn(name = "person_id")
 78	    @Column(name = "amount", nullable = false)
 79	    private Map<Long, BigDecimal> personOpenings = new HashMap<>();
 80	
 81	    protected Period() {
 82	    }
 83	
 84	    public Period(String sheetId, String name, LocalDate from, LocalDate to) {
 85	        this(sheetId, name, from, to, null);
 86	    }
 87	
 88	    public Period(String sheetId, String name, LocalDate from, LocalDate to, Integer cap) {
 89	        this.sheetId = sheetId;
 90	        this.name = name;
 91	        this.from = from;
 92	        this.to = to;
 93	        this.cap = cap;
 94	    }
 95	
 96	    public Long getId() {
 97	        return id;
 98	    }
 99	
100	    public String getSheetId() {
101	        return sheetId;
102	    }
103	
104	    public String getName() {
105	        return name;
106	    }
107	
108	    public LocalDate getFrom() {
109	        return from;
110	    }
111	
112	    public LocalDate getTo() {
113	        return to;
114	    }
115	
116	    /** The most OPEN or PENDING claims a person may have in the period; null for no cap. */
117	    public Integer getCap() {
118	        return cap;
119	    }
120	
121	    public boolean isClosed() {
122	        return closed;
123	    }
124	
125	    public boolean isSoftClosed() {
126	        return softClosed;
127	    }
128	
129	    /** Whether the period is locked: a locked period cannot be reopened until it is unlocked. */
130	    public boolean isLocked() {
131	        return locked;
132	    }
133	
134	    /** Locks or unlocks the period. */
135	    public void setLocked(boolean locked) {
136	        this.locked = locked;
137	    }
138	
139	    /** The due-total fixed when the period was closed or soft-closed; null while it is open. */
140	    public BigDecimal getClosedTotal() {
141	        return closedTotal;
142	    }
143	
144	    /** Each person's due-total fixed when the period was closed, by person id; empty while it is open. */
145	    public Map<Long, BigDecimal> getClosedPersonTotals() {
146	        return Map.copyOf(closedPersonTotals);
147	    }
148	
149	    /** Each person's carried figure fixed when the period was closed, by person id; empty while it is open. */
150	    public Map<Long, BigDecimal> getClosedPersonCarried() {
151	        return Map.copyOf(closedPersonCarried);
152	    }
153	
154	    /**
155	     * The pools as they stood when the period was closed or soft-closed (JSON), each member's cut for it fixed by them;
156	     * null while it is open.
157	     */
158	    public String getFixedPools() {
159	        return fixedPools;
160	    }
161	
162	    /** Each person's opening balance for the period, by person id; a person with none has no entry. */
163	    public Map<Long, BigDecimal> getPersonOpenings() {
164	        return Map.copyOf(personOpenings);
165	    }
166	
167	    /** Adds the amount to the person's opening balance for the period. */
168	    public void addOpening(Long personId, BigDecimal amount) {
169	        personOpenings.merge(personId, amount, BigDecimal::add);
170	    }
171	
172	    /** Takes the amount back off the person's opening balance for the period; one taken back to nothing is removed. */
173	    public void takeOpening(Long personId, BigDecimal amount) {
174	        BigDecimal left = personOpenings.getOrDefault(personId, BigDecimal.ZERO).subtract(amount);
175	        if (left.signum() == 0) {
176	            personOpenings.remove(personId);
177	        } else {
178	            personOpenings.put(personId, left);
179	        }
180	    }
181	
182	    /**
183	     * Folds the due-total and carried figure fixed for one person, and their opening balance, into another's (a person with none fixed takes them as theirs): the
184	     * merged person leaves the period, their figure kept under the person they were merged into.
185	     */
186	    public void mergePersonTotal(Long from, Long into) {
187	        BigDecimal moved = closedPersonTotals.remove(from);
188	        if (moved != null) {
189	            closedPersonTotals.merge(into, moved, BigDecimal::add);
190	        }
191	        BigDecimal carried = closedPersonCarried.remove(from);
192	        if (carried != null) {
193	            closedPersonCarried.merge(into, carried, BigDecimal::add);
194	        }
195	        BigDecimal opening = personOpenings.remove(from);
196	        if (opening != null) {
197	            personOpenings.merge(into, opening, BigDecimal::add);
198	        }
199	    }
200	
201	    /** Whether the date falls in the period. */
202	    public boolean contains(LocalDate date) {
203	        return !date.isBefore(from) && !date.isAfter(to);
204	    }
205	
206	    /**
207	     * Closes the period, fixing its due-total and each person's, each person's carried figure, and the pools as they
208	     * stand (so each member's cut).
209	     */
210	    public void close(BigDecimal total, Map<Long, BigDecimal> personTotals, Map<Long, BigDecimal> personCarried,
211	            String pools) {
212	        fix(total, personTotals, personCarried, pools);
213	        this.closed = true;
214	        this.softClosed = false;
215	    }
216	
217	    /**
218	     * Soft-closes the period, fixing its due-total and each person's, each person's carried figure, and the pools as
219	     * they stand; claims due by a date in it can still change.
220	     */
221	    public void softClose(BigDecimal total, Map<Long, BigDecimal> personTotals, Map<Long, BigDecimal> personCarried,
222	            String pools) {
223	        fix(total, personTotals, personCarried, pools);
224	        this.softClosed = true;
225	    }
226	
227	    private void fix(BigDecimal total, Map<Long, BigDecimal> personTotals, Map<Long, BigDecimal> personCarried,
228	            String pools) {
229	        this.closedTotal = total;
230	        this.fixedPools = pools;
231	        this.closedPersonTotals.clear();
232	        this.closedPersonTotals.putAll(personTotals);
233	        this.closedPersonCarried.clear();
234	        this.closedPersonCarried.putAll(personCarried);
235	    }
236	
237	    /** Reopens the period, closed or soft-closed: its due-total, carried figures and cuts are live again. */
238	    public void reopen() {
239	        this.closed = false;
240	        this.softClosed = false;
241	        this.closedTotal = null;
242	        this.fixedPools = null;
243	        this.closedPersonTotals.clear();
244	        this.closedPersonCarried.clear();
245	    }
246	}
