1145	  // claim's amount times their share divided by 100 times the rate of the holder's own grade in force on the claim's
1146	  // date divided by 100, rounded like the claim (n/a for the holder, and 0.00 given away, when that grade has no rate);
1147	  // a settled or bound claim keeps its parts as frozen, its figure times the share divided by 100, rounded half to
1148	  // even. And for each such claim what its own person gives away, its holders' parts added up. A claim with no figure
1149	  // (n/a) has no parts.
1150	  private readonly shareParts = computed(() => {
1151	    const grades = new Map(this.people().map((p) => [p.id, p.grades]));
1152	    const rates = this.rates.byClaim();
1153	    const floor = this.settings.floor();
1154	    const late = this.settings.lateness();
1155	    const held = new Map<number, { claim: Claim; part: string | null }[]>();
1156	    const given = new Map<number, string>();
1157	    for (const c of this.liveClaims()) {
1158	      if (c.shares.length === 0) continue;
1159	      const own = grades.get(c.personId) ?? [];
1160	      const due = dueOf(c, rates(c).get(gradeOn(own, c.date)) ?? [], floor, late, graceOf(c, own, late));
1161	      if (due === null) continue;
1162	      const frozen = c.settledDue !== null || isBound(c);
1163	      const parts = c.shares.map((s) =>
1164	        frozen
1165	          ? (dueOn(due, s.share) ?? '0.00')
1166	          : partOn(c.amount, s.share, rateOn(rates(c).get(gradeOn(grades.get(s.personId) ?? [], c.date)) ?? [], c.date), roundsHalfUp(c, late)),
1167	      );
1168	      c.shares.forEach((s, i) => held.set(s.personId, [...(held.get(s.personId) ?? []), { claim: c, part: parts[i] }]));
1169	      given.set(c.id, sumSkippingNa(parts));
1170	    }
1171	    return { held, given };
