1185	    const rates = this.rates.byClaim();
1186	    const floor = this.settings.floor();
1187	    const late = this.settings.lateness();
1188	    for (const p of this.people()) {
1189	      const counted = this.liveBy().get(p.id) ?? [];
1190	      // the grades whose rate today decides n/a: the one in force today and each counted claim's
1191	      const grades = [this.gradeToday(p), ...counted.map((c) => gradeOn(p.grades, c.date))];
1192	      const dues = counted.map((c) => this.ownFigure(c, dueOf(c, rates(c).get(gradeOn(p.grades, c.date)) ?? [], floor, late, graceOf(c, p.grades, late))));
1193	      // the parts they hold of others' shared claims count as figures of theirs
1194	      dues.push(...(this.shareParts().held.get(p.id) ?? []).map((h) => h.part));
