1206	  protected readonly splitBy = computed(() => {
1207	    const grades = new Map(this.people().map((p) => [p.id, p.grades]));
1208	    const rates = this.rates.byClaim();
1209	    const floor = this.settings.floor();
1210	    const late = this.settings.lateness();
1211	    const by = new Map<number, { settled: string; open: string; scored: string }>();
1212	    const { held } = this.shareParts();
1213	    const ids = new Set([...this.liveBy().keys(), ...held.keys()]);
1214	    for (const id of ids) {
1215	      const own = grades.get(id) ?? [];
1216	      const due = (c: Claim) => this.ownFigure(c, dueOf(c, rates(c).get(gradeOn(own, c.date)) ?? [], floor, late, graceOf(c, own, late)));
1217	      // their own claims less the parts given away, and the parts they hold of others'
1218	      const figures = [
1219	        ...(this.liveBy().get(id) ?? []).map((c) => ({ claim: c, figure: due(c) })),
1220	        ...(held.get(id) ?? []).map((h) => ({ claim: h.claim, figure: h.part })),
1221	      ];
1222	      const sum = (keep: (c: Claim) => boolean) => sumSkippingNa(figures.filter((f) => keep(f.claim)).map((f) => f.figure));
