1944	  protected async transferUndo(p: Person): Promise<void> {
1945	    this.clearRowErrors(p.id);
1946	    const sheet = this.session.sheetId();
1947	    if (!sheet) return;
1948	    const url = `/api/sheets/${encodeURIComponent(sheet)}/people/${p.id}/transfer-undo`;
1949	    try {
1950	      await firstValueFrom(this.http.post<void>(url, {}));
1951	    } catch (err) {
1952	      this.rowErrors.update((e) => ({
1953	        ...e,
1954	        [p.id]:
1955	          err instanceof HttpErrorResponse && err.status === 403
1956	            ? 'Only the steward who made the transfer can undo it.'
1957	            : 'Could not undo this transfer.',
1958	      }));
1959	      return;
1960	    }
