1972	    this.clearRowErrors(p.id);
1973	    const sheet = this.session.sheetId();
1974	    if (!sheet) return;
1975	    const alias = (this.aliasInputs()[p.id] ?? '').trim();
1976	    const refuse = (message: string) => this.rowErrors.update((e) => ({ ...e, [p.id]: message }));
1977	    if (!alias) {
1978	      refuse('Enter an alias.');
1979	      return;
1980	    }
1981	    const key = alias.toLowerCase();
1982	    if (this.people().some((q) => q.name.toLowerCase() === key || q.aliases.some((a) => a.toLowerCase() === key))) {
1983	      refuse('That name is already in use on this sheet.');
