65	    /**
66	     * A steward transfers the person to the other sheet. They arrive with every grade (and its from-date), their
67	     * holds, terms, contact and aliases, and their claims with status, dates, notes, tags, frozen figures and logs,
68	     * listed newest first as they were; each claim that had a number takes the other sheet's next, in the order the
69	     * claims were opened (by the sheet's today when each was opened, then the order they were added). Figures a
70	     * statement bound are kept, their statements go with them, and references are not carried. Their patron links, pool
71	     * memberships, crew memberships and watches are dropped, the crews they lead stay with no lead, and they leave this sheet. Refused unless the user is a steward, for a
72	     * retired person, for this sheet's own id, for an archived sheet, and when their contact is already a contact on
73	     * the other sheet. When their name or an alias is already a name or alias of someone on the other sheet (compared
74	     * as names are), they arrive and are merged into that person exactly as a merge does (their contact then dropped
75	     * rather than refused); refused when that person is retired, or when their names match more than one person.
76	     */
77	    @Transactional
78	    public void transfer(String by, String sheetId, Long id, String toSheetId) {
79	        if (!settings.isSteward(sheetId, by)) {
80	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can transfer people.");
81	        }
82	        if (sheetId.equals(toSheetId)) {
83	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A person cannot be transferred to their own sheet.");
84	        }
85	        // both sheets are locked, in the order of their ids, so two transfers between them never deadlock
86	        if (sheetId.compareTo(toSheetId) < 0) {
87	            sheets.lock(sheetId);
88	            sheets.lock(toSheetId);
89	        } else {
90	            sheets.lock(toSheetId);
91	            sheets.lock(sheetId);
92	        }
93	        if (settings.isArchived(toSheetId)) {
94	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The other sheet is archived.");
95	        }
96	        Person person = people.findWithLockByIdAndSheetId(id, sheetId)
97	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
98	        if (person.isRetired()) {
99	            throw new ResponseStatusException(HttpStatus.CONFLICT, "A retired person cannot be transferred.");
100	        }
101	        List<String> names = new ArrayList<>();
102	        names.add(person.getName());
103	        names.addAll(person.getAliases());
104	        List<Long> matches = names.stream()
105	                .map(n -> people.findBySheetIdAndNameOrAlias(toSheetId, n).map(Person::getId).orElse(null))
106	                .filter(m -> m != null).distinct().toList();
107	        if (matches.size() > 1) {
108	            throw new ResponseStatusException(HttpStatus.CONFLICT,
109	                    "The name and aliases match more than one person on the other sheet.");
110	        }
111	        Person into = matches.isEmpty() ? null
112	                : people.findWithLockByIdAndSheetId(matches.get(0), toSheetId).orElseThrow();
113	        if (into != null && into.isRetired()) {
114	            throw new ResponseStatusException(HttpStatus.CONFLICT,
115	                    "The person on the other sheet with the name is retired, so cannot be merged into.");
116	        }
117	        if (into == null && person.getContact() != null
118	                && people.existsBySheetIdAndContact(toSheetId, person.getContact())) {
119	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The contact is already on the other sheet.");
120	        }
121	        RollupService.Snapshot beforeHere = rollup.snapshot(sheetId);
122	        RollupService.Snapshot beforeThere = rollup.snapshot(toSheetId);
123	
124	        // what links the person to others on this sheet is dropped
125	        patrons.deleteAll(patrons.findBySheetIdOrderByIdAsc(sheetId).stream()
126	                .filter(p -> p.getPersonId().equals(id) || p.getPatronId().equals(id)).toList());
127	        List<PoolMember> memberships = poolMembers.findBySheetIdOrderByIdAsc(sheetId).stream()
128	                .filter(m -> id.equals(m.getPersonId())).toList();
129	        poolMembers.deleteAll(memberships);
130	        crews.left(sheetId, id);
131	        watches.deleteAll(watches.findByPersonIdOrderByIdAsc(id));
132	        // their statements go with them, in their order
133	        for (Statement s : statements.findBySheetIdAndPersonIdInOrder(sheetId, id)) {
134	            s.moveTo(toSheetId, id, s.getPlace());
135	        }
136	        plans.deleteAll(plans.findBySheetIdAndPersonIdOrderByIdAsc(sheetId, id));
137	        plans.flush();
138	        patrons.flush();
139	        poolMembers.flush();
140	        watches.flush();
141	        statements.flush();
142	
143	        // one merged on arrival is never listed there: their name is already someone's on the other sheet
144	        if (into == null) {
145	            person.moveToSheet(toSheetId, sheets.load(toSheetId).getToday(), by);
146	            // they go to the end of the other sheet's list
147	            person.setPosition(people.nextPosition(toSheetId));
148	            people.saveAndFlush(person);
149	        }
150	
151	        List<Claim> moved = new ArrayList<>(claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, id));
152	        // numbered afresh in the order they were opened
153	        moved.sort(Comparator.comparing(Claim::openedOn, Comparator.nullsFirst(Comparator.naturalOrder()))
154	                .thenComparing(Claim::getId));
155	        Map<String, String> renumbered = new HashMap<>();
156	        for (Claim c : moved) {
157	            String was = c.getNumber();
158	            c.moveToSheet(toSheetId);
159	            claimService.takeIn(toSheetId, c);
160	            if (was != null) {
161	                renumbered.put(was, c.getNumber());
162	            }
163	        }
164	        // a claim naming another of theirs by number names it by its new one; one naming any other names none
165	        for (Claim c : moved) {
166	            if (c.getCorrects() != null) {
167	                c.setCorrects(renumbered.get(c.getCorrects()));
168	            }
169	            if (c.getSplitFrom() != null) {
170	                c.setSplitFrom(renumbered.get(c.getSplitFrom()));
171	            }
172	            claims.saveAndFlush(c);
173	        }
174	        // listed as the other sheet's newest, in the order they were listed here
175	        moved.sort(Comparator.comparing(Claim::getListed, Comparator.nullsFirst(Comparator.naturalOrder()))
176	                .thenComparing(Claim::getId));
177	        for (Claim c : moved) {
178	            claims.relist(c.getId());
179	        }
180	
181	        String name = person.getName();
182	        audit.recordOnCommit("PERSON_TRANSFERRED sheet=" + sheetId + " by=" + by + " name=" + name + " to="
183	                + toSheetId);
184	        audit.recordOnCommit("PERSON_TRANSFERRED sheet=" + toSheetId + " by=" + by + " name=" + name + " from="
185	                + sheetId);
186	        if (into != null) {
187	            mergeService.absorb(by, toSheetId, person, into);
188	        }
189	        rollup.recordChanges(by, sheetId, beforeHere);
190	        rollup.recordChanges(by, toSheetId, beforeThere);
191	    }
192	
193	    /**
194	     * The steward who transferred the person to this sheet undoes it on the sheet's today they arrived: the person is
195	     * transferred back to the sheet they came from, exactly as a transfer does. Refused on any later day, for anyone
196	     * else, and for a person who did not arrive by transfer. The sheet they went back to.
197	     */
198	    @Transactional
199	    public String undo(String by, String sheetId, Long id) {
200	        if (!settings.isSteward(sheetId, by)) {
201	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can undo a transfer.");
202	        }
203	        Person person = people.findByIdAndSheetId(id, sheetId)
204	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
205	        String from = person.getOriginSheet();
206	        if (from == null || person.getArrivedOn() == null) {
207	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The person did not arrive by transfer.");
208	        }
209	        if (!by.equals(person.getArrivedBy())) {
210	            throw new ResponseStatusException(HttpStatus.FORBIDDEN,
211	                    "Only the steward who made the transfer can undo it.");
212	        }
213	        if (!person.getArrivedOn().equals(sheets.load(sheetId).getToday())) {
214	            throw new ResponseStatusException(HttpStatus.CONFLICT,
215	                    "A transfer can only be undone on the day the person arrived.");
216	        }
217	        RollupService.Snapshot before = rollup.snapshot(sheetId);
218	        String name = person.getName();
219	        transfer(by, sheetId, id, from);
220	        audit.recordOnCommit("PERSON_TRANSFER_UNDONE sheet=" + sheetId + " by=" + by + " name=" + name + " to=" + from);
221	        rollup.recordChanges(by, sheetId, before);
222	        return from;
223	    }
224	}
