 21	/**
 22	 * A rate for a grade on a sheet: a percent with two decimals, 0.00 or more, applying from its from-date (null: from
 23	 * the beginning of time) through its to-date (null: with no end).
 24	 */
 25	@Entity
 26	@Table(name = "rate")
 27	public class Rate {
 28	
 29	    @Id
 30	    @GeneratedValue(strategy = GenerationType.IDENTITY)
 31	    private Long id;
 32	
 33	    @Column(name = "sheet_id", nullable = false)
 34	    private String sheetId;
 35	
 36	    @Column(name = "grade", nullable = false)
 37	    private String grade;
 38	
 39	    @Column(name = "pct", nullable = false, precision = 7, scale = 2)
 40	    private BigDecimal pct;
 41	
 42	    @Column(name = "from_date")
 43	    private LocalDate from;
 44	
 45	    @Column(name = "to_date")
 46	    private LocalDate to;
 47	
 48	    /** The number of this, the newest version, counting from 1; the older ones are kept as {@link RateVersion}s. */
 49	    @Column(name = "version", nullable = false)
 50	    private int version = 1;
 51	
 52	    /**
 53	     * For a forward-only rate (one saved with a from-date on or after the sheet's today), the claim mark it was saved
 54	     * at: it applies only to claims added after, those with a greater mark (see {@link #appliesTo}). Null for a rate
 55	     * that applies to every claim.
 56	     */
 57	    @Column(name = "after_mark")
 58	    private Long afterMark;
 59	
 60	    protected Rate() {
 61	    }
