 63	    public Rate(String sheetId, String grade, LocalDate from, BigDecimal pct) {
 64	        this.sheetId = sheetId;
 65	        this.grade = grade;
 66	        this.from = from;
 67	        this.pct = pct;
 68	    }
 69	
 70	    public Long getId() {
 71	        return id;
 72	    }
 73	
 74	    public String getSheetId() {
 75	        return sheetId;
 76	    }
 77	
 78	    public String getGrade() {
 79	        return grade;
 80	    }
 81	
 82	    public BigDecimal getPct() {
 83	        return pct;
 84	    }
 85	
 86	    public void setPct(BigDecimal pct) {
 87	        this.pct = pct;
 88	    }
 89	
 90	    public LocalDate getFrom() {
 91	        return from;
 92	    }
 93	
 94	    public LocalDate getTo() {
 95	        return to;
 96	    }
 97	
 98	    public void setTo(LocalDate to) {
 99	        this.to = to;
100	    }
101	
102	    public int getVersion() {
103	        return version;
104	    }
105	
106	    public Long getAfterMark() {
107	        return afterMark;
108	    }
109	
110	    public void setAfterMark(Long afterMark) {
111	        this.afterMark = afterMark;
112	    }
113	
114	    /** Whether this version applies to a claim added at the mark: it is not forward-only, or was saved before it. */
115	    public boolean appliesTo(long mark) {
116	        return afterMark == null || mark > afterMark;
117	    }
118	
119	    /**
120	     * Replaces this version with a newer one of the percent, to-date and mark (null: applying to every claim); the
121	     * caller keeps the one replaced.
122	     */
123	    public void newVersion(BigDecimal pct, LocalDate to, Long afterMark) {
124	        this.version++;
125	        this.pct = pct;
126	        this.to = to;
127	        this.afterMark = afterMark;
128	    }
129	
130	    /** Replaces this, the newest version, with the older one before it, which the caller then drops. */
131	    public void restore(RateVersion older) {
132	        this.version = older.getVersion();
133	        this.pct = older.getPct();
134	        this.to = older.getTo();
135	        this.afterMark = older.getAfterMark();
136	    }
137	
138	    /**
139	     * The rates a claim added at the mark sees among one sheet's rate versions, given oldest first: for each grade and
140	     * from-date, the newest version that applies to it (see {@link #appliesTo}); none for one with no such version.
141	     * By grade, then from-date (no from-date first). Not to be saved.
142	     */
143	    public static List<Rate> seenBy(List<Rate> versions, long mark) {
144	        Map<List<Object>, Rate> by = new LinkedHashMap<>();
145	        for (Rate r : versions) {
146	            if (r.appliesTo(mark)) {
147	                by.put(Arrays.asList(r.getGrade(), r.getFrom()), r);
148	            }
149	        }
150	        List<Rate> seen = new ArrayList<>(by.values());
151	        seen.sort(Comparator.comparing(Rate::getGrade).thenComparing(Rate::getFrom,
152	                Comparator.nullsFirst(Comparator.naturalOrder())));
153	        return seen;
154	    }
155	
156	    /**
157	     * The rate in force on the date among one grade's rates: the one with the latest from-date on or before it, unless
158	     * the date is past that one's to-date; null with none.
159	     */
160	    public static Rate inForce(Collection<Rate> rates, LocalDate date) {
161	        Rate best = rates.stream().filter(r -> r.getFrom() == null || !r.getFrom().isAfter(date))
162	                .max(Comparator.comparing(Rate::getFrom,
163	                        Comparator.nullsFirst(Comparator.naturalOrder())))
164	                .orElse(null);
165	        return best == null || (best.getTo() != null && best.getTo().isBefore(date)) ? null : best;
166	    }
167	
168	    /**
169	     * One grade's rates as they apply through a chain of sheets: on each date, the rate the first level has in force
170	     * then (the sheet's own, then its parent's, and so on). Given as rates that do not overlap, so the one in force on
171	     * a date among them is the one the chain has; with one level, its rates as they are. Not to be saved.
172	     */
173	    public static List<Rate> chained(String sheetId, String grade, List<? extends Collection<Rate>> levels) {
174	        if (levels.size() == 1) {
175	            return List.copyOf(levels.get(0));
176	        }
177	        // the chain's rate can only change on a from-date, or the day after a to-date
178	        TreeSet<LocalDate> starts = new TreeSet<>();
179	        starts.add(LocalDate.MIN);
180	        for (Collection<Rate> level : levels) {
181	            for (Rate r : level) {
182	                if (r.getFrom() != null) {
183	                    starts.add(r.getFrom());
184	                }
185	                if (r.getTo() != null && r.getTo().isBefore(LocalDate.MAX)) {
186	                    starts.add(r.getTo().plusDays(1));
187	                }
188	            }
189	        }
190	        List<Rate> chained = new ArrayList<>();
191	        Rate last = null;
192	        for (LocalDate start : starts) {
193	            BigDecimal pct = levels.stream().map(level -> inForce(level, start)).filter(Objects::nonNull)
194	                    .map(Rate::getPct).findFirst().orElse(null);
195	            LocalDate end = starts.higher(start) == null ? null : starts.higher(start).minusDays(1);
196	            if (pct == null) {
197	                last = null;
198	            } else if (last != null && last.getPct().compareTo(pct) == 0) {
199	                last.setTo(end);
200	            } else {
201	                last = new Rate(sheetId, grade, start.equals(LocalDate.MIN) ? null : start, pct);
202	                last.setTo(end);
203	                chained.add(last);
204	            }
205	        }
206	        return chained;
207	    }
208	}
