225	/**
226	 * The rates that apply on a sheet: a grade with no rate in force on a date on the sheet takes its parent sheet's rate
227	 * for that date, then the parent's parent's, up to {@link #LEVELS_UP} levels up; with none there, a sheet that was
228	 * cloned takes the rate of the sheet it was cloned from, found the same way, and so on.
229	 */
230	@Component
231	public class RateChain {
232	
233	    /** How many levels of parent sheets a rate is looked for in. */
234	    public static final int LEVELS_UP = 3;
235	
236	    /**
237	     * The rates that apply on the sheet to the claims added up to a mark (inclusive; null: with no end) and after the
238	     * previous tier's: forward-only rates saved at a greater mark leave them out (see {@link Rate#appliesTo}).
239	     */
240	    public record Tier(Long upTo, List<Rate> rates) {
241	    }
242	
243	    private final RateRepository rates;
244	    private final RateChangeRepository changes;
245	    private final RateVersionRepository versions;
246	    private final SheetRepository sheets;
247	
248	    public RateChain(RateRepository rates, RateChangeRepository changes, RateVersionRepository versions,
249	            SheetRepository sheets) {
250	        this.rates = rates;
251	        this.changes = changes;
252	        this.versions = versions;
253	        this.sheets = sheets;
254	    }
255	
256	    /**
257	     * The sheet's id, then its parent's, and so on, up to {@link #LEVELS_UP} levels up; then, for a sheet that was
258	     * cloned, the lineage of the sheet it was cloned from, and so on. Each sheet appears once.
259	     */
260	    public List<String> lineage(String sheetId) {
261	        List<String> ids = new ArrayList<>();
262	        String from = sheetId;
263	        while (from != null && !ids.contains(from)) {
264	            ids.add(from);
265	            Sheet cloned = sheets.findById(from).orElse(null);
266	            String at = from;
267	            for (int up = 0; up < LEVELS_UP; up++) {
268	                String parent = sheets.findById(at).map(Sheet::getParentId).orElse(null);
269	                if (parent == null || ids.contains(parent)) {
270	                    break;
271	                }
272	                ids.add(parent);
273	                at = parent;
274	            }
275	            from = cloned == null ? null : cloned.getClonedFrom();
276	        }
277	        return ids;
278	    }
279	
280	    /** Every grade's rates as they apply on the sheet, by grade and then from-date (see {@link Rate#chained}). */
281	    public List<Rate> applying(String sheetId) {
282	        return applying(sheetId, rates::findBySheetIdOrderByGradeAscFromAsc);
283	    }
284	
285	    /**
286	     * Every grade's rates as they applied on the sheet at the end of the day: each sheet in its lineage with the
287	     * rates it had then.
288	     */
289	    public List<Rate> applyingAsOf(String sheetId, LocalDate day) {
290	        return applying(sheetId, id -> changes.ratesAsOf(id, day));
291	    }
292	
293	    /**
294	     * The rates that apply on the sheet by the claim mark they apply to, as tiers in mark order, the last (with no
295	     * end) the rates as they apply to claims added from now on: every grade's rates as they apply on the sheet.
296	     */
297	    public List<Tier> tiers(String sheetId) {
298	        return tiers(sheetId, this::versions);
299	    }
300	
301	    /** The tiers of the rates as they applied on the sheet at the end of the day (see {@link #applyingAsOf}). */
302	    public List<Tier> tiersAsOf(String sheetId, LocalDate day) {
303	        return tiers(sheetId, id -> changes.versionsAsOf(id, day));
304	    }
305	
306	    /** Among the tiers, the rates that apply to a claim added at the mark. */
307	    public static List<Rate> forMark(List<Tier> tiers, long mark) {
308	        return tiers.stream().filter(t -> t.upTo() == null || mark <= t.upTo()).findFirst().map(Tier::rates)
309	                .orElse(List.of());
310	    }
311	
312	    /**
313	     * The grade's rate that applies on the sheet on the date to a claim added at the mark: forward-only rates saved
314	     * after it are left out; empty with none.
315	     */
316	    public Optional<Rate> findInForce(String sheetId, String grade, LocalDate date, long mark) {
317	        List<Rate> seen = applying(sheetId, id -> Rate.seenBy(versions(id), mark)).stream()
318	                .filter(r -> r.getGrade().equals(grade)).toList();
319	        return Optional.ofNullable(Rate.inForce(seen, date));
320	    }
321	
322	    /** One sheet's rate versions, oldest first: each rate's older versions, then its newest. */
323	    private List<Rate> versions(String sheetId) {
324	        Map<Long, List<RateVersion>> older = new LinkedHashMap<>();
325	        for (RateVersion v : versions.findBySheet(sheetId)) {
326	            older.computeIfAbsent(v.getRateId(), id -> new ArrayList<>()).add(v);
327	        }
328	        List<Rate> all = new ArrayList<>();
329	        for (Rate r : rates.findBySheetIdOrderByGradeAscFromAsc(sheetId)) {
330	            for (RateVersion v : older.getOrDefault(r.getId(), List.of())) {
331	                Rate was = new Rate(sheetId, r.getGrade(), r.getFrom(), v.getPct());
332	                was.setTo(v.getTo());
333	                was.setAfterMark(v.getAfterMark());
334	                all.add(was);
335	            }
336	            all.add(r);
337	        }
338	        return all;
339	    }
340	
341	    private List<Tier> tiers(String sheetId, Function<String, List<Rate>> versionsOf) {
342	        Map<String, List<Rate>> byLevel = new LinkedHashMap<>();
343	        for (String id : lineage(sheetId)) {
344	            byLevel.put(id, versionsOf.apply(id));
345	        }
346	        TreeSet<Long> marks = new TreeSet<>();
347	        byLevel.values().forEach(l -> l.stream().map(Rate::getAfterMark).filter(Objects::nonNull).forEach(marks::add));
348	        List<Tier> tiers = new ArrayList<>();
349	        for (Long mark : marks) {
350	            tiers.add(new Tier(mark, applying(sheetId, id -> Rate.seenBy(byLevel.get(id), mark))));
351	        }
352	        tiers.add(new Tier(null, applying(sheetId, id -> Rate.seenBy(byLevel.get(id), Long.MAX_VALUE))));
353	        return tiers;
354	    }
355	
356	    /** The grade's rate that applies on the sheet on the date; empty with none. */
357	    public Optional<Rate> findInForce(String sheetId, String grade, LocalDate date) {
358	        List<String> lineage = lineage(sheetId);
359	        if (lineage.size() == 1) {
360	            return rates.findInForce(sheetId, grade, date);
361	        }
362	        return lineage.stream().map(id -> rates.findInForce(id, grade, date)).flatMap(Optional::stream).findFirst();
363	    }
364	
365	    private List<Rate> applying(String sheetId, Function<String, List<Rate>> ratesOf) {
366	        List<String> lineage = lineage(sheetId);
367	        if (lineage.size() == 1) {
368	            return ratesOf.apply(sheetId);
369	        }
370	        List<Map<String, List<Rate>>> levels = new ArrayList<>();
371	        for (String id : lineage) {
372	            Map<String, List<Rate>> byGrade = new LinkedHashMap<>();
373	            for (Rate r : ratesOf.apply(id)) {
374	                byGrade.computeIfAbsent(r.getGrade(), g -> new ArrayList<>()).add(r);
375	            }
376	            levels.add(byGrade);
377	        }
378	        Set<String> grades = new TreeSet<>();
379	        levels.forEach(l -> grades.addAll(l.keySet()));
380	        List<Rate> applying = new ArrayList<>();
381	        for (String grade : grades) {
382	            applying.addAll(Rate.chained(sheetId, grade,
383	                    levels.stream().map(l -> l.getOrDefault(grade, List.of())).toList()));
384	        }
385	        return applying;
386	    }
387	}
