426	        this.settings = settings;
427	        this.audit = audit;
428	    }
429	
430	    /** The rates set on the sheet, by grade and then from-date (no from-date first). */
431	    @Transactional(readOnly = true)
432	    public List<Rate> list(String sheetId) {
433	        return rates.findBySheetIdOrderByGradeAscFromAsc(sheetId);
434	    }
435	
436	    /** The rates that apply on the sheet, its parent sheets' filling in for it (see {@link RateChain}). */
437	    @Transactional(readOnly = true)
438	    public List<Rate> applying(String sheetId) {
439	        return chain.applying(sheetId);
440	    }
441	
442	    /** The rates that apply on the sheet by the claim mark they apply to (see {@link RateChain#tiers}). */
443	    @Transactional(readOnly = true)
444	    public List<RateChain.Tier> tiers(String sheetId) {
445	        return chain.tiers(sheetId);
446	    }
447	
448	    /**
449	     * Sets the grade's rate from the date (null: from the beginning of time) through the to-date (null: with no end),
450	     * as a new version of any rate it had for that from-date, the one it replaces kept as an older version. Set with a
451	     * from-date on or after the sheet's today, the version is forward-only: it applies only to claims added after it
452	     * is saved, the claims already on the sheet keeping the rates that applied to them (see {@link Rate#appliesTo}).
453	     */
454	    @Transactional
455	    public Rate set(String by, String sheetId, String grade, LocalDate from, LocalDate to, BigDecimal pct) {
456	        if (!sheets.load(sheetId).isGrade(grade)) {
457	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY, "No such grade: " + grade + ".");
458	        }
459	        LocalDate today = sheets.load(sheetId).getToday();
460	        RollupService.Snapshot before = rollup.snapshot(sheetId);
461	        BigDecimal scaled = pct.setScale(2, RoundingMode.UNNECESSARY);
462	        Long afterMark = from != null && !from.isBefore(today) ? rates.nextClaimMark() : null;
463	        Rate rate = rates.findExact(sheetId, grade, from).orElse(null);
464	        if (rate == null) {
465	            rate = new Rate(sheetId, grade, from, scaled);
466	            rate.setTo(to);
467	            rate.setAfterMark(afterMark);
468	        } else {
469	            versions.save(new RateVersion(rate));
470	            rate.newVersion(scaled, to, afterMark);
471	        }
472	        Rate saved;
473	        try {
474	            saved = rates.saveAndFlush(rate);
475	        } catch (DataIntegrityViolationException e) {
476	            // another user set this grade's rate for this from-date at the same moment
477	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That rate was just set by someone else.");
478	        }
479	        changes.saveAndFlush(new RateChange(saved, today));
480	        audit.recordOnCommit("RATE_SET sheet=" + sheetId + " by=" + by + " grade=" + grade
481	                + " rate=" + saved.getPct().toPlainString() + (from != null ? " from=" + from : "")
482	                + (to != null ? " to=" + to : ""));
483	        rollup.recordChanges(by, sheetId, before);
484	        return saved;
485	    }
486	
487	    /**
488	     * Withdraws the newest version of the grade's rate for the from-date (null: from the beginning of time): the
489	     * version before it applies again, and with none the rate is gone. Refused unless the user is a steward, and for a
490	     * grade and from-date with no rate. Returns the rate as it now is, or null when it is gone.
491	     */
492	    @Transactional
493	    public Rate withdraw(String by, String sheetId, String grade, LocalDate from) {
494	        if (!settings.isSteward(sheetId, by)) {
495	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can withdraw a rate.");
496	        }
497	        Rate rate = rates.findExact(sheetId, grade, from).orElseThrow(
498	                () -> new ResponseStatusException(HttpStatus.NOT_FOUND, "There is no such rate to withdraw."));
499	        LocalDate today = sheets.load(sheetId).getToday();
500	        RollupService.Snapshot before = rollup.snapshot(sheetId);
501	        changes.saveAndFlush(RateChange.withdrawal(rate, today));
502	        RateVersion older = versions.findByRateIdAndVersion(rate.getId(), rate.getVersion() - 1).orElse(null);
503	        Rate left;
504	        if (older == null) {
505	            rates.delete(rate);
506	            rates.flush();
507	            left = null;
508	        } else {
509	            rate.restore(older);
510	            versions.delete(older);
511	            versions.flush();
512	            left = rates.saveAndFlush(rate);
513	        }
514	        audit.recordOnCommit("RATE_WITHDRAWN sheet=" + sheetId + " by=" + by + " grade=" + grade
515	                + (from != null ? " from=" + from : ""));
516	        rollup.recordChanges(by, sheetId, before);
517	        return left;
518	    }
519	}

