108	// A clerk settling a claim whose due is above the clerk limit makes it PENDING, for a steward to approve (SETTLED)
109	// or reject (OPEN again). A deleted DRAFT is DELETED, counts nowhere, and on the day it was deleted can be restored.
110	// Opening a claim whose due is above the review threshold in force on its date makes it REVIEW, unnumbered and
111	// counting nowhere, until a steward reviews it (OPEN).
112	export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID' | 'DELETED' | 'REVIEW';
113	
114	type ClaimAction = 'open' | 'review' | 'settle' | 'resettle' | 'approve' | 'reject' | 'void' | 'delete' | 'restore';
115	
116	/** Only open, pending and settled claims count toward what is claimed and due. */
117	export function counts(c: Claim): boolean {
118	  return isOpen(c) || c.status === 'SETTLED';
119	}
120	
121	/**
122	 * The status the claim had at the end of the day, as its log records it: the last line logged on or before it (a
123	 * line with no date counts as before any day); null when the claim was added after it. A claim with no log has its
124	 * status now.
125	 */
126	export function statusAtEndOf(c: Pick<Claim, 'status' | 'log'>, day: string): ClaimStatus | null {
127	  if (c.log.length === 0) return c.status;
128	  let then: ClaimStatus | null = null;
129	  for (const line of c.log) if (line.on === null || line.on <= day) then = line.status;
130	  return then;
131	}
132	
133	/** Whether the claim is open: OPEN or PENDING. An open claim goes overdue and bears the late charge. */
134	export function isOpen(c: Claim): boolean {
135	  return c.status === 'OPEN' || c.status === 'PENDING';
136	}
137	
138	/** Whether the person's last statement binds the claim's figure (a pending claim is bound like any other). */
139	export function isBound(c: Claim): boolean {
140	  return c.stated;
141	}
142	
143	/** Whether the claim is a correction: one with a negative amount. */
144	export function isCorrection(c: Claim): boolean {
145	  return c.amount.startsWith('-');
146	}
147	
148	/**
149	 * Whether the claim's live figures round half up: by the rounding mode in force on the date its rounding follows
150	 * when one is; else when that date is before the policy date (the sheet's today when the setting is blank). Else
151	 * they round half to even.
152	 */
153	export function roundsHalfUp(c: Claim, late: Rounding): boolean {
154	  const mode = late.rounding(c.roundsOn);
155	  if (mode !== null) return mode === 'half-up';
156	  return late.policyDate !== null && c.roundsOn < late.policyDate;
157	}
158	
159	/**
160	 * The figure of a claim: its settled due, else the due a statement bound it to, else its
161	 * rate figure at the rate in force on its date (no floor), rounded as the rounding mode or the policy date decides
162	 * for it; null (n/a) with none.
163	 */
164	export function figureOf(c: Claim, rates: readonly RateView[], late: Rounding): string | null {
165	  if (c.settledDue !== null) return c.settledDue;
166	  if (isBound(c)) return c.statedDue;
167	  return dueOn(c.amount, rateOn(rates, c.date), roundsHalfUp(c, late));
168	}
169	
170	/** Whether the claim keeps a figure whatever the rates: a settled or bound one with a figure. */
171	export function keepsFigure(c: Claim): boolean {
172	  return c.settledDue !== null || (isBound(c) && c.statedDue !== null);
173	}
174	
175	/**
176	 * Whether the claim was deferred until a date after the sheet's today, whatever its status, and no statement binds
177	 * it (the deferral waits for the binding to end): as the row shows it.
178	 */
179	export function deferredUntilAfter(c: Claim, today: string | null): boolean {
180	  return !isBound(c) && c.deferredUntil !== null && today !== null && today < c.deferredUntil;
181	}
182	
183	/**
184	 * Whether a claim is deferred: deferred until a date after the sheet's today, bound by no statement, and counting
185	 * (OPEN, or settled while a statement bound it). Until today reaches that date it counts in no total, is not
186	 * overdue and cannot be settled; from then on it is a claim like any other.
187	 */
188	export function deferred(c: Claim, today: string | null): boolean {
189	  return counts(c) && deferredUntilAfter(c, today);
190	}
191	
192	/** Whether a claim's late charge is waived on the date: waived on or before it, so it bears no late charge. */
193	export function waivedOn(c: Claim, today: string | null): boolean {
194	  return c.waivedOn !== null && today !== null && c.waivedOn <= today;
195	}
196	
197	/** Whether a claim makes its person active: open (or pending) and dated within the 30 days up to and including today. */
198	export function activeOn(c: Claim, today: string | null): boolean {
199	  return isOpen(c) && today !== null && plusDays(today, -29) <= c.date && c.date <= today;
200	}
201	
202	/**
203	 * The date after which a claim is overdue: its due-by plus the grace days (those its person's grade in force on its
204	 * date has in force on that date). Its late charge's 30-day boundaries count from it; the due-by shown is unchanged.
205	 */
206	export function lateFrom(c: Claim, grace: number): string {
207	  return grace > 0 ? plusDays(c.dueBy, grace) : c.dueBy;
208	}
209	
210	/** Whether a claim is overdue: open (or pending), not deferred, and its due-by plus its grace is before the sheet's today. */
211	export function overdue(c: Claim, today: string | null, grace = 0): boolean {
212	  return isOpen(c) && today !== null && !deferred(c, today) && lateFrom(c, grace) < today;
213	}
214	
215	/**
216	 * Whether a claim is late in review: REVIEW, with a review SLA set, and its review day (the sheet's today when it
217	 * last went to REVIEW) plus the SLA days is before the sheet's today.
218	 */
219	export function reviewLate(c: Claim, today: string | null, sla: number | null): boolean {
220	  if (c.status !== 'REVIEW' || today === null || sla === null) return false;
221	  const on = [...c.log].reverse().find((l) => l.status === 'REVIEW')?.on ?? null;
222	  return on !== null && plusDays(on, sla) < today;
223	}
224	
225	/**
226	 * Whether a claim is late in pending: PENDING, with a pending SLA set, and its pending day (the sheet's today when it
227	 * last went to PENDING) plus the SLA days is before the sheet's today.
228	 */
229	export function pendingLate(c: Claim, today: string | null, sla: number | null): boolean {
230	  if (c.status !== 'PENDING' || today === null || sla === null) return false;
231	  const on = [...c.log].reverse().find((l) => l.status === 'PENDING')?.on ?? null;
232	  return on !== null && plusDays(on, sla) < today;
233	}
234	
235	/** The grace days of the claim: those its person's grade in force on its date has in force on that date. */
236	export function graceOf(c: Claim, grades: readonly DatedGrade[], late: Lateness): number {
237	  return late.grace(gradeOn(grades, c.date), c.date);
238	}
239	
240	/** The floor in force on a date. */
241	export type FloorOn = (date: string) => string;
242	
243	/**
244	 * What decides how a claim's live figures round: the rounding mode in force on a date (null for none), else the
245	 * policy date in force (the sheet's today when the setting is blank).
246	 */
247	export interface Rounding {
248	  policyDate: string | null;
249	  rounding: (date: string) => 'half-up' | 'half-even' | null;
250	}
251	
252	/**
253	 * What the late charge follows: the sheet's today and the late percent in force on a date; and how a claim's live
254	 * figures round.
255	 */
256	export interface Lateness extends Rounding {
257	  today: string | null;
258	  latePct: (date: string) => string;
259	  /** The grace days the grade has in force on a date; 0 with none. */
260	  grace: (grade: string | null, date: string) => number;
261	}
262	
263	/** The whole days from one date (yyyy-mm-dd) to another. */
264	function daysBetween(from: string, to: string): number {
265	  const utc = (d: string) => {
266	    const [y, m, day] = d.split('-').map(Number);
267	    return Date.UTC(y, m - 1, day);
268	  };
269	  return Math.round((utc(to) - utc(from)) / 86_400_000);
270	}
271	
272	/** The date (yyyy-mm-dd) the given whole days after another. */
273	export function plusDays(date: string, days: number): string {
274	  const [y, m, d] = date.split('-').map(Number);
275	  return new Date(Date.UTC(y, m - 1, d + days)).toISOString().slice(0, 10);
276	}
277	
278	/**
279	 * The due a claim shows and totals: a settled claim's frozen due; else its live due, its floored figure (the greater
280	 * of the floor in force on its date and its figure) plus the late charge worked out on that floored figure: for an
281	 * overdue claim, for each full 30 days it is overdue, the late percent in force on that boundary date (its due-by
282	 * plus its grace, plus 30, 60, 90 ... days) of the floored figure plus the charges of the boundaries before it (it compounds), rounded like the claim; a boundary whose percent is 0.00 adds nothing. A claim a statement binds shows the due it
283	 * bound, charge and floor included. A correction has neither; a waived claim bears no charge.
284	 */
285	export function dueOf(c: Claim, rates: readonly RateView[], floor: FloorOn, late: Lateness, grace = 0): string | null {
286	  const figure = figureOf(c, rates, late);
287	  if (figure === null || c.settledDue !== null || isBound(c) || isCorrection(c)) return figure;
288	  const floored = atLeast(figure, floor(c.date));
289	  if (!overdue(c, late.today, grace) || waivedOn(c, late.today)) return floored;
290	  const from = lateFrom(c, grace);
291	  const periods = Math.floor(daysBetween(from, late.today!) / 30);
292	  const halfUp = roundsHalfUp(c, late);
293	  let due = floored;
294	  for (let k = 1; k <= periods; k++) {
295	    due = sumSkippingNa([due, dueOn(due, late.latePct(plusDays(from, 30 * k)), halfUp)]);
296	  }
297	  return due;
298	}
