329	
330	/** The people each user watches on a sheet, and the notices a watched person's settled claims send them. */
331	@Service
332	public class WatchService {
333	
334	    private final WatchRepository watches;
335	    private final PersonRepository people;
336	    private final Audit audit;
337	
338	    public WatchService(WatchRepository watches, PersonRepository people, Audit audit) {
339	        this.watches = watches;
340	        this.people = people;
341	        this.audit = audit;
342	    }
343	
344	    /** The ids of the people the user watches on the sheet. */
345	    @Transactional(readOnly = true)
346	    public List<Long> watched(String sheetId, String user) {
347	        return watches.findBySheetIdAndUserNameOrderByIdAsc(sheetId, user).stream().map(Watch::getPersonId).toList();
348	    }
349	
350	    /** Starts (on) or stops the user watching the person; a person already in that state is left as they are. */
351	    @Transactional
352	    public boolean watch(String user, String sheetId, Long personId, boolean on) {
353	        Person person = people.findWithLockByIdAndSheetId(personId, sheetId)
354	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
355	        var existing = watches.findByPersonIdAndUserName(person.getId(), user);
356	        if (on && existing.isEmpty()) {
357	            try {
358	                watches.saveAndFlush(new Watch(sheetId, person.getId(), user));
359	            } catch (DataIntegrityViolationException e) {
360	                return true;
361	            }
362	            audit.recordOnCommit("PERSON_WATCHED sheet=" + sheetId + " by=" + user + " name=" + person.getName());
363	        } else if (!on && existing.isPresent()) {
364	            watches.delete(existing.get());
365	            watches.flush();
366	            audit.recordOnCommit("PERSON_UNWATCHED sheet=" + sheetId + " by=" + user + " name=" + person.getName());
367	        }
368	        return on;
369	    }
370	
371	    /**
372	     * Records one notice per user watching the person, in the order they started watching, that the claim with the
373	     * number was settled; called after the claim's own record and before the rollup's.
374	     */
375	    public void notifyWatchers(String by, String sheetId, Person person, String number) {
376	        for (Watch w : watches.findByPersonIdOrderByIdAsc(person.getId())) {
377	            audit.recordOnCommit("NOTIFY sheet=" + sheetId + " by=" + by + " user=" + w.getUserName() + " person="
378	                    + person.getName() + " number=" + number);
379	        }
380	    }
381	}
