165	import java.math.BigDecimal;
166	import java.time.LocalDate;
167	import java.time.format.DateTimeParseException;
168	import java.util.ArrayList;
169	import java.util.List;
170	import net.officefloor.hq.app.sheet.SheetService;
171	import org.springframework.http.HttpStatus;
172	import org.springframework.stereotype.Service;
173	import org.springframework.transaction.annotation.Transactional;
174	import org.springframework.web.server.ResponseStatusException;
175	
176	/** Sets a rate for each pasted line of grade,rate,from,to (the last two may be absent or blank), all of them or none. */
177	@Service
178	public class RateImportService {
179	
180	    /** A pasted line read into the rate form's fields. */
181	    private record Line(String grade, BigDecimal pct, LocalDate from, LocalDate to) {
182	    }
183	
184	    private final RateService rates;
185	    private final SheetService sheets;
186	
187	    public RateImportService(RateService rates, SheetService sheets) {
188	        this.rates = rates;
189	        this.sheets = sheets;
190	    }
191	
192	    /**
193	     * Reads every line first by the rate form's rules, then sets each in line order as the form would, replacing a
194	     * rate for the same grade and from-date. One change: any line refused refuses them all, and nothing is stored or
195	     * audited.
196	     */
197	    @Transactional
198	    public List<Rate> importRates(String by, String sheetId, String text) {
199	        List<String> grades = sheets.load(sheetId).gradeList();
200	        List<Line> lines = new ArrayList<>();
201	        int n = 0;
202	        for (String raw : text.split("\\r?\\n")) {
203	            n++;
204	            if (!raw.isBlank()) {
205	                lines.add(read(n, raw, grades));
206	            }
207	        }
208	        if (lines.isEmpty()) {
209	            throw refused("Paste at least one line of grade,rate,from,to.");
210	        }
211	        List<Rate> set = new ArrayList<>();
212	        for (Line l : lines) {
213	            set.add(rates.set(by, sheetId, l.grade(), l.from(), l.to(), l.pct()));
214	        }
215	        return set;
216	    }
217	
218	    private Line read(int n, String raw, List<String> grades) {
219	        String[] f = raw.split(",", -1);
220	        if (f.length < 2) {
221	            throw refused("Line " + n + " needs at least a grade and a rate.");
222	        }
223	        if (f.length > 4) {
224	            throw refused("Line " + n + " has more than grade,rate,from,to.");
225	        }
226	        String grade = f[0].strip();
227	        if (!grades.contains(grade)) {
228	            throw refused("Line " + n + " has a grade that is not one of the grades.");
229	        }
230	        String pct = f[1].strip();
231	        if (!pct.matches("\\d{1,5}(\\.\\d{1,2})?")) {
232	            throw refused("Line " + n + " has a rate that is not 0.00 or more with up to two decimals.");
233	        }
234	        LocalDate from = date(n, "from-date", f.length > 2 ? f[2] : "");
235	        LocalDate to = date(n, "to-date", f.length > 3 ? f[3] : "");
236	        if (from != null && to != null && to.isBefore(from)) {
237	            throw refused("Line " + n + " has a to-date before its from-date.");
238	        }
239	        return new Line(grade, new BigDecimal(pct), from, to);
240	    }
241	
242	    private static LocalDate date(int n, String what, String raw) {
243	        String text = raw.strip();
244	        if (text.isEmpty()) {
245	            return null;
246	        }
247	        try {
248	            return LocalDate.parse(text);
249	        } catch (DateTimeParseException e) {
250	            throw refused("Line " + n + " has a " + what + " that is not yyyy-mm-dd.");
251	        }
252	    }
253	
254	    private static ResponseStatusException refused(String reason) {
255	        return new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, reason);
256	    }
257	}
