458	public interface RateChangeRepository extends JpaRepository<RateChange, Long> {
459	
460	    List<RateChange> findBySheetIdOrderByIdAsc(String sheetId);
461	
462	    /**
463	     * The rates the sheet had at the end of the day: for each grade and from-date, the last rate set for it while the
464	     * sheet's today was on or before the day.
465	     */
466	    default List<Rate> ratesAsOf(String sheetId, LocalDate day) {
467	        return stacksAsOf(sheetId, day).values().stream().map(l -> l.get(l.size() - 1)).toList();
468	    }
469	
470	    /**
471	     * Every rate set while the sheet's today was on or before the day and not withdrawn by then, each grade and
472	     * from-date's in the order set (see {@link Rate#seenBy}).
473	     */
474	    default List<Rate> versionsAsOf(String sheetId, LocalDate day) {
475	        return stacksAsOf(sheetId, day).values().stream().flatMap(List::stream).toList();
476	    }
477	
478	    /**
479	     * For each grade and from-date, the versions set while the sheet's today was on or before the day, oldest first,
480	     * each withdrawal by then taking off the newest; one with none left is left out.
481	     */
482	    private Map<List<Object>, List<Rate>> stacksAsOf(String sheetId, LocalDate day) {
483	        Map<List<Object>, List<Rate>> by = new LinkedHashMap<>();
484	        for (RateChange c : findBySheetIdOrderByIdAsc(sheetId)) {
485	            if (!c.madeBy(day)) {
486	                continue;
487	            }
488	            List<Object> key = Arrays.asList(c.getGrade(), c.getFrom());
489	            if (c.isWithdrawn()) {
490	                List<Rate> stack = by.get(key);
491	                if (stack != null) {
492	                    stack.remove(stack.size() - 1);
493	                    if (stack.isEmpty()) {
494	                        by.remove(key);
495	                    }
496	                }
497	            } else {
498	                by.computeIfAbsent(key, k -> new ArrayList<>()).add(c.rate());
499	            }
500	        }
501	        return by;
502	    }
503	}
