1056	    const settleOn = (this.settleDates()[c.id] ?? '').trim();
1057	    const today = this.session.realToday();
1058	    if (
1059	      action === 'settle' &&
1060	      settleOn !== '' &&
1061	      (!/^\d{4}-\d{2}-\d{2}$/.test(settleOn) || (today !== null && settleOn > today))
1062	    ) {
1063	      this.setRowError(c.id, `Enter a date on or before ${today ?? 'today'} to settle this claim as of.`);
1064	      return;
1065	    }
1066	    const voidReason = this.voidReasonChoices()[c.id] ?? '';
1067	    const listed = this.voidReasons.list();
1068	    if (action === 'void' && listed.length > 0 && !listed.some((r) => r.reason === voidReason)) {
1069	      this.setRowError(c.id, 'Choose a reason from the list to void this claim.');
1070	      return;
1071	    }
1072	    try {
1073	      const body =
1074	        action === 'reject'
1075	          ? { reason }
1076	          : action === 'void'
1077	            ? { reason: voidReason || null }
1078	            : action === 'settle'
1079	              ? { on: settleOn || null }
1080	              : null;
1081	      this.saved.emit(await firstValueFrom(this.http.post<Claim>(url, body)));
1082	      if (action === 'settle') this.settleDates.update(({ [c.id]: _, ...rest }) => rest);
1083	      if (action === 'reject') this.rejectReasons.update(({ [c.id]: _, ...rest }) => rest);
1084	      if (action === 'void') this.voidReasonChoices.update(({ [c.id]: _, ...rest }) => rest);
1085	    } catch (e) {
1086	      const opener = c.openedBy !== null && c.openedBy === this.session.user();
1087	      const editor = c.editedBy !== null && c.editedBy === this.session.user();
1088	      const forbidden = e instanceof HttpErrorResponse && e.status === 403;
1089	      const err =
1090	        action === 'delete' && c.status !== 'DRAFT'
1091	          ? `A ${c.status} claim cannot be deleted; only a draft can.`
1092	          : action === 'restore' && c.status === 'DELETED'
1093	          ? 'A deleted claim can only be restored on the day it was deleted.'
1094	          : action === 'restore'
1095	          ? `A ${c.status} claim cannot be restored; only a deleted one can.`
1096	          : action === 'settle' && settleOn !== '' && e instanceof HttpErrorResponse && e.status === 422
1097	          ? `This claim did not exist on ${settleOn}, so it cannot be settled as of then.`
1098	          : action === 'settle' && deferred(c, this.session.realToday())
1099	          ? `This claim is deferred until ${c.deferredUntil}, so it cannot be settled yet.`
1100	          : action === 'void' && e instanceof HttpErrorResponse && e.status === 422
1101	          ? 'Choose a reason from the list to void this claim.'
1102	          : action === 'void' && c.status === 'SETTLED'
1103	          ? 'Only a steward can void a settled claim, and only within 7 days of its settlement.'
1104	          : (action === 'open' || action === 'settle' || action === 'void') && forbidden
1105	          ? `Your role may not ${action} a claim on this sheet.`
1106	          : action === 'settle' && opener
1107	          ? 'You opened this claim, so another user must settle it.'
1108	          : action === 'settle' && editor
1109	          ? 'You last edited this claim, so another user must settle it.'
1110	          : action === 'review' && forbidden
1111	          ? 'Only a steward can review a claim.'
1112	          : action === 'review' && c.status !== 'REVIEW'
1113	          ? `A ${c.status} claim cannot be reviewed; only one in REVIEW can.`
1114	          : (action === 'approve' || action === 'reject') && forbidden
1115	            ? 'Only a steward or the person\'s approver can approve or reject a pending claim.'
1116	            : action === 'resettle' && forbidden
1117	              ? 'Only a steward can re-settle a claim.'
1118	              : action === 'approve' && opener
1119	                ? 'You opened this claim, so another steward must approve it.'
1120	                : action === 'approve' && editor
1121	                ? 'You last edited this claim, so another steward must approve it.'
1122	                : ((action === 'settle' && c.status === 'OPEN') || (action === 'approve' && c.status === 'PENDING')) &&
1123	                    c.proofs === 0
1124	                  ? 'This claim\'s due is above the proof threshold, so it needs a proof first.'
1125	                  : (action === 'settle' && c.status === 'OPEN') || (action === 'approve' && c.status === 'PENDING')
