229	package net.officefloor.hq.app.crew;
230	
231	import java.util.List;
232	import net.officefloor.hq.app.Audit;
233	import net.officefloor.hq.app.person.Person;
234	import net.officefloor.hq.app.person.PersonRepository;
235	import net.officefloor.hq.app.pool.PoolRepository;
236	import net.officefloor.hq.app.sheet.SheetService;
237	import org.springframework.http.HttpStatus;
238	import org.springframework.stereotype.Service;
239	import org.springframework.transaction.annotation.Transactional;
240	import org.springframework.web.server.ResponseStatusException;
241	
242	/**
243	 * The sheet's crews and their members. A crew has a name (trimmed, not blank, at most once on the sheet) and a lead
244	 * chosen from the sheet's people; its members are other people of the sheet, each at most once, never its lead. A
245	 * person may lead or be in several crews. A crew is also a pool under its name (its lead and members at equal shares),
246	 * so a crew cannot take a pool's name.
247	 */
248	@Service
249	public class CrewService {
250	
251	    private final CrewRepository crews;
252	    private final CrewMemberRepository members;
253	    private final PersonRepository people;
254	    private final PoolRepository pools;
255	    private final SheetService sheets;
256	    private final Audit audit;
257	
258	    public CrewService(CrewRepository crews, CrewMemberRepository members, PersonRepository people,
259	            PoolRepository pools, SheetService sheets, Audit audit) {
260	        this.crews = crews;
261	        this.pools = pools;
262	        this.members = members;
263	        this.people = people;
264	        this.sheets = sheets;
265	        this.audit = audit;
266	    }
267	
268	    /** The sheet's crews, in the order they were added. */
269	    @Transactional(readOnly = true)
270	    public List<Crew> list(String sheetId) {
271	        return crews.findBySheetIdOrderByIdAsc(sheetId);
272	    }
273	
274	    /** The members of every crew on the sheet, in the order they were added. */
275	    @Transactional(readOnly = true)
276	    public List<CrewMember> members(String sheetId) {
277	        return members.findBySheetIdOrderByIdAsc(sheetId);
278	    }
279	
280	    /**
281	     * Adds a crew under its name, trimmed, led by the person; refused when blank, already a crew's name or a pool's, or
282	     * no lead.
283	     */
284	    @Transactional
285	    public Crew add(String by, String sheetId, String name, Long leadId) {
286	        String key = name == null ? "" : name.strip();
287	        if (key.isEmpty()) {
288	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "Enter a crew name.");
289	        }
290	        sheets.lock(sheetId);
291	        Person lead = person(sheetId, leadId, "Choose a lead.");
292	        if (crews.existsBySheetIdAndName(sheetId, key)) {
293	            throw new ResponseStatusException(HttpStatus.CONFLICT, key + " is already a crew.");
294	        }
295	        if (pools.existsBySheetIdAndName(sheetId, key)) {
296	            throw new ResponseStatusException(HttpStatus.CONFLICT, key + " is already a pool.");
297	        }
298	        Crew added = crews.saveAndFlush(new Crew(sheetId, key, lead.getId()));
299	        audit.recordOnCommit("CREW_ADDED sheet=" + sheetId + " by=" + by + " name=" + key + " lead=" + lead.getName());
300	        return added;
301	    }
302	
303	    /** Adds the person to the crew; refused when they lead it or are already in it. */
304	    @Transactional
305	    public CrewMember addMember(String by, String sheetId, Long crewId, Long personId) {
306	        sheets.lock(sheetId);
307	        Crew crew = crews.findById(crewId).filter(c -> c.getSheetId().equals(sheetId))
308	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such crew."));
309	        Person person = person(sheetId, personId, "Choose a person.");
310	        if (person.getId().equals(crew.getLeadId())) {
311	            throw new ResponseStatusException(HttpStatus.CONFLICT,
312	                    person.getName() + " leads " + crew.getName() + ".");
313	        }
314	        if (members.existsByCrewIdAndPersonId(crew.getId(), person.getId())) {
315	            throw new ResponseStatusException(HttpStatus.CONFLICT,
316	                    person.getName() + " is already in " + crew.getName() + ".");
317	        }
318	        CrewMember added = members.saveAndFlush(new CrewMember(sheetId, crew.getId(), person.getId()));
319	        audit.recordOnCommit("CREW_MEMBER_ADDED sheet=" + sheetId + " by=" + by + " crew=" + crew.getName()
320	                + " name=" + person.getName());
321	        return added;
322	    }
323	
324	    /**
325	     * A person merged into another: the crews they lead pass to the other, and their memberships too; a membership the
326	     * other already has, or of a crew the other now leads, is dropped.
327	     */
328	    @Transactional
329	    public void merged(String sheetId, Long from, Long into) {
330	        List<Crew> all = crews.findBySheetIdOrderByIdAsc(sheetId);
331	        for (Crew c : all) {
332	            if (from.equals(c.getLeadId())) {
333	                c.setLeadId(into);
334	                crews.save(c);
335	            }
336	        }
337	        crews.flush();
338	        List<CrewMember> memberships = members.findBySheetIdOrderByIdAsc(sheetId);
339	        for (CrewMember m : memberships) {
340	            boolean intoLeads = all.stream().anyMatch(c -> c.getId().equals(m.getCrewId()) && into.equals(c.getLeadId()));
341	            if (into.equals(m.getPersonId()) && intoLeads) {
342	                members.delete(m);
343	            } else if (from.equals(m.getPersonId())) {
344	                boolean intoIn = memberships.stream()
345	                        .anyMatch(o -> o.getCrewId().equals(m.getCrewId()) && into.equals(o.getPersonId()));
346	                if (intoIn || intoLeads) {
347	                    members.delete(m);
348	                } else {
349	                    m.setPersonId(into);
350	                    members.save(m);
351	                }
352	            }
353	        }
354	        members.flush();
355	    }
356	
357	    /** A person leaving the sheet: their memberships are dropped, and the crews they lead stay, with no lead. */
358	    @Transactional
359	    public void left(String sheetId, Long personId) {
360	        members.deleteAll(members.findBySheetIdOrderByIdAsc(sheetId).stream()
361	                .filter(m -> personId.equals(m.getPersonId())).toList());
362	        members.flush();
363	        for (Crew c : crews.findBySheetIdOrderByIdAsc(sheetId)) {
364	            if (personId.equals(c.getLeadId())) {
365	                c.setLeadId(null);
366	                crews.save(c);
367	            }
368	        }
369	        crews.flush();
370	    }
371	
372	    private Person person(String sheetId, Long personId, String refusal) {
373	        if (personId == null) {
374	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, refusal);
375	        }
376	        return people.findByIdAndSheetId(personId, sheetId)
377	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, refusal));
378	    }
379	}

