8	export interface RateView {
9	  grade: string;
10	  pct: string;
11	  // The date the rate applies from; null for a rate that applies from the beginning of time.
12	  from: string | null;
13	  // The date the rate applies through; null for a rate with no end.
14	  to: string | null;
15	  // How many versions the rate has; the one shown is the newest, the one in force.
16	  version: number;
17	}
18	
19	// The rates that apply to the claims added up to a mark (inclusive; null: with no end) and after the previous tier's:
20	// a forward-only rate applies only to the claims added after it was saved.
21	export interface RateTier {
22	  upTo: number | null;
23	  rates: RateView[];
24	}
25	
26	export const GRADES = ['A', 'B', 'C'];
27	
28	// What a candidate rate for a grade would change: how many claims would show a different due, and the sum of the
29	// differences (new due minus current due), with two decimals.
30	export interface RatePreview {
31	  count: number;
32	  diff: string;
33	}
34	
35	// A grade a person has from its from-date; null for the first one given, which applies from the beginning of time.
36	export interface DatedGrade {
37	  grade: string;
38	  from: string | null;
39	}
40	
41	/** The grade in force on the date: the one with the latest from-date on or before it; '' with none. */
42	export function gradeOn(grades: readonly DatedGrade[], date: string | null): string {
43	  let best: DatedGrade | undefined;
44	  for (const g of grades) {
45	    if (g.from !== null && (date === null || g.from > date)) continue;
46	    if (!best || (g.from !== null && (best.from === null || g.from > best.from))) best = g;
47	  }
48	  return best?.grade ?? '';
49	}
50	
51	const PCT = /^\d{1,5}(\.\d{1,2})?$/;
52	
53	/** Whole cents of a two-decimal value. */
54	function cents(value: string): bigint {
55	  const negative = value.startsWith('-');
56	  const [whole, frac = ''] = (negative ? value.slice(1) : value).split('.');
57	  const c = BigInt(whole) * 100n + BigInt((frac + '00').slice(0, 2));
58	  return negative ? -c : c;
59	}
60	
61	/**
62	 * The due on an amount at a rate (both two-decimal strings): amount times rate divided by 100,
63	 * rounded half to even (or half up, when asked) to two decimals; null (n/a) when there is no rate.
64	 * Worked in whole numbers so nothing drifts.
65	 */
66	export function dueOn(amount: string, pct: string | undefined, halfUp = false): string | null {
67	  if (pct === undefined) return null;
68	  const product = cents(amount) * cents(pct);
69	  // rounded on the size, so a negative amount (a correction) rounds like its positive
70	  const size = product < 0n ? -product : product;
71	  let due = size / 10000n;
72	  const rest = size % 10000n;
73	  if (rest > 5000n || (rest === 5000n && (halfUp || due % 2n === 1n))) due += 1n;
74	  return formatCents(product < 0n ? -due : due);
75	}
76	
77	/**
78	 * A holder's part of a shared claim: the amount times the share divided by 100, times the rate divided by 100 (all
79	 * two-decimal strings), rounded half to even (or half up, when asked) to two decimals; null (n/a) when there is no
80	 * rate.
81	 */
82	export function partOn(amount: string, share: string, pct: string | undefined, halfUp = false): string | null {
83	  if (pct === undefined) return null;
84	  const product = cents(amount) * cents(share) * cents(pct);
85	  const size = product < 0n ? -product : product;
86	  let part = size / 100000000n;
87	  const rest = size % 100000000n;
88	  if (rest > 50000000n || (rest === 50000000n && (halfUp || part % 2n === 1n))) part += 1n;
89	  return formatCents(product < 0n ? -part : part);
90	}
91	
92	/** The two-decimal value, raised to the floor when it is below it. */
93	export function atLeast(value: string, floor: string): string {
94	  return cents(value) < cents(floor) ? formatCents(cents(floor)) : value;
95	}
96	
97	/** The two-decimal value held to the cap when it is above it; n/a, or no cap (null), leaves it as it is. */
98	export function atMost(value: string | null, cap: string | null): string | null {
99	  return value !== null && cap !== null && cents(value) > cents(cap) ? formatCents(cents(cap)) : value;
100	}
101	
102	/** What the two-decimal value is above the cap: 0.00 when it is not, is n/a, or there is no cap (null). */
103	export function excessOver(value: string | null, cap: string | null): string {
104	  return value !== null && cap !== null && cents(value) > cents(cap) ? formatCents(cents(value) - cents(cap)) : '0.00';
105	}
106	
107	/** The cap less the cut total (both two decimals), not below 0.00; no cap (null) stays none. */
108	export function capLess(cap: string | null, cut: string): string | null {
109	  if (cap === null) return null;
110	  const room = cents(cap) - cents(cut);
111	  return formatCents(room < 0n ? 0n : room);
112	}
113	
114	/** The sum of two-decimal values, skipping n/a. */
115	export function sumSkippingNa(values: readonly (string | null)[]): string {
116	  return formatCents(values.reduce((sum, v) => (v === null ? sum : sum + cents(v)), 0n));
117	}
118	
119	/** One two-decimal figure minus another, as a two-decimal figure with a minus sign when negative. */
120	export function difference(value: string, minus: string): string {
121	  return formatCents(cents(value) - cents(minus));
122	}
123	
124	/**
125	 * 100.00 split equally into the given number of two-decimal shares, each rounded half to even, with the remainder
126	 * (100.00 minus the shares added up) given to the first.
127	 */
128	export function equalShares(count: number): string[] {
129	  if (count <= 0) return [];
130	  const n = BigInt(count);
131	  let share = 10000n / n;
132	  const rest = 10000n % n;
133	  if (rest * 2n > n || (rest * 2n === n && share % 2n === 1n)) share += 1n;
134	  return Array.from({ length: count }, (_, i) => formatCents(i === 0 ? 10000n - share * (n - 1n) : share));
135	}
136	
137	/** The sum of each two-decimal figure times its two-decimal share divided by 100, rounded half to even. */
138	export function sharedSum(parts: readonly { figure: string; share: string }[]): string {
139	  const product = parts.reduce((sum, p) => sum + cents(p.figure) * cents(p.share), 0n);
140	  const size = product < 0n ? -product : product;
141	  let total = size / 10000n;
142	  const rest = size % 10000n;
143	  if (rest > 5000n || (rest === 5000n && total % 2n === 1n)) total += 1n;
144	  return formatCents(product < 0n ? -total : total);
145	}
146	
147	/**
148	 * A score: the two-decimal figure divided by 100, minus 5 for each of the count, rounded half to even to a whole
149	 * number, with a minus sign when negative.
150	 */
151	export function scoreOf(figure: string, minusFives: number): string {
152	  const value = cents(figure) - BigInt(minusFives) * 50000n;
153	  const size = value < 0n ? -value : value;
154	  let score = size / 10000n;
155	  const rest = size % 10000n;
156	  if (rest > 5000n || (rest === 5000n && score % 2n === 1n)) score += 1n;
157	  return (value < 0n && score > 0n ? '-' : '') + score.toString();
158	}
159	
160	/**
161	 * The sheet-total of two-decimal figures, skipping n/a: with three or more figures, the single highest and the
162	 * single lowest are left out.
163	 */
164	export function trimmedSum(values: readonly (string | null)[]): string {
165	  const figures = values.filter((v): v is string => v !== null).map(cents);
166	  let sum = figures.reduce((total, c) => total + c, 0n);
167	  if (figures.length >= 3) {
168	    const max = figures.reduce((a, b) => (b > a ? b : a));
169	    const min = figures.reduce((a, b) => (b < a ? b : a));
170	    sum -= max + min;
171	  }
172	  return formatCents(sum);
173	}
