175	/**
176	 * The percent of the rate in force on the date among one grade's rates: the one with the latest
177	 * from-date on or before it, a rate with no from-date applying from the beginning of time;
178	 * undefined (n/a) when none applies yet, or when the date is past that one's to-date.
179	 */
180	export function rateOn(rates: readonly RateView[], date: string | null): string | undefined {
181	  let best: RateView | undefined;
182	  for (const r of rates) {
183	    if (r.from !== null && (date === null || r.from > date)) continue;
184	    if (!best || (r.from !== null && (best.from === null || r.from > best.from))) best = r;
185	  }
186	  if (best?.to && date !== null && date > best.to) return undefined;
187	  return best?.pct;
188	}
189	
190	function formatCents(c: bigint): string {
191	  const size = c < 0n ? -c : c;
192	  return `${c < 0n ? '-' : ''}${size / 100n}.${(size % 100n).toString().padStart(2, '0')}`;
193	}
194	
195	/** The rates by grade, each grade's in the order given. */
196	function byGrade(rates: readonly RateView[]): ReadonlyMap<string, readonly RateView[]> {
197	  const by = new Map<string, RateView[]>();
198	  for (const r of rates) by.set(r.grade, [...(by.get(r.grade) ?? []), r]);
199	  return by;
200	}
201	
202	/** Orders rates by grade, then from-date with no from-date first. */
203	function byGradeThenFrom(a: RateView, b: RateView): number {
204	  if (a.grade !== b.grade) return a.grade < b.grade ? -1 : 1;
205	  return (a.from ?? '').localeCompare(b.from ?? '');
206	}
