208	// The rates set on the active sheet, each grade's by from-date; a grade with no rate is not in the map.
209	@Injectable({ providedIn: 'root' })
210	export class RateStore {
211	  private readonly http = inject(HttpClient);
212	  private readonly session = inject(Session);
213	
214	  // Every rate on the sheet, by grade and then from-date.
215	  readonly list = signal<readonly RateView[]>([]);
216	  // The rates that apply on the sheet: its own, and for a date on which a grade has none in force, its parent sheets'
217	  // (up to three levels up), given as rates that do not overlap; by grade and then from-date.
218	  readonly applying = signal<readonly RateView[]>([]);
219	  readonly rates = computed(() => byGrade(this.applying()));
220	  // The rates that apply on the sheet by the mark of the claims they apply to, in mark order; the last, with no end,
221	  // is the rates as they apply to claims added from now on.
222	  readonly tiers = signal<readonly RateTier[]>([]);
223	  // The rates that apply to a claim, by grade: those of the first tier its mark is within (a claim just added, with
224	  // no mark yet, is the newest). The rates panel and the rate in force today do not go by this.
225	  readonly byClaim = computed(() => {
226	    const tiers = this.tiers().map((t) => ({ upTo: t.upTo, rates: byGrade(t.rates) }));
227	    const newest = tiers.length ? tiers[tiers.length - 1].rates : this.rates();
228	    return (c: { mark: number | null }): ReadonlyMap<string, readonly RateView[]> =>
229	      (c.mark === null ? undefined : tiers.find((t) => t.upTo === null || c.mark! <= t.upTo))?.rates ?? newest;
230	  });
231	  // Each grade's rate in force on the sheet's today; a grade with none is not in the map.
232	  readonly current = computed(() => {
233	    const today = this.session.sheetToday();
234	    const by = new Map<string, string>();
235	    for (const [g, list] of this.rates()) {
236	      const pct = rateOn(list, today);
237	      if (pct !== undefined) by.set(g, pct);
238	    }
239	    return by as ReadonlyMap<string, string>;
240	  });
241	  // For each month of the sheet's today's calendar year (as yyyy-mm), each grade's rate in force on its first day;
242	  // a grade with none is not in that month's map. Empty with no today.
243	  readonly calendar = computed(() => {
244	    const year = this.session.sheetToday()?.slice(0, 4);
245	    if (!year) return [] as { month: string; rates: ReadonlyMap<string, string> }[];
246	    return Array.from({ length: 12 }, (_, i) => {
247	      const month = `${year}-${String(i + 1).padStart(2, '0')}`;
248	      const by = new Map<string, string>();
249	      for (const [g, list] of this.rates()) {
250	        const pct = rateOn(list, `${month}-01`);
251	        if (pct !== undefined) by.set(g, pct);
252	      }
253	      return { month, rates: by as ReadonlyMap<string, string> };
254	    });
255	  });
256	
257	  /** Re-read the sheet's rates from the store. */
258	  async load(sheet: string): Promise<void> {
259	    this.list.set([]);
260	    this.applying.set([]);
261	    this.tiers.set([]);
262	    const base = `/api/sheets/${encodeURIComponent(sheet)}/rates`;
263	    const [list, applying, tiers] = await Promise.all([
264	      firstValueFrom(this.http.get<RateView[]>(base)),
265	      firstValueFrom(this.http.get<RateView[]>(`${base}/applying`)),
266	      firstValueFrom(this.http.get<RateTier[]>(`${base}/tiers`)),
267	    ]);
268	    if (this.session.sheetId() === sheet) {
269	      this.list.set([...list].sort(byGradeThenFrom));
270	      this.applying.set([...applying].sort(byGradeThenFrom));
271	      this.tiers.set(tiers);
272	    }
273	  }
274	
275	  /** Re-read the rates that apply on the sheet, its parent sheets' filling in for its own, and their tiers. */
276	  private async loadApplying(sheet: string): Promise<void> {
277	    const base = `/api/sheets/${encodeURIComponent(sheet)}/rates`;
278	    const [applying, tiers] = await Promise.all([
279	      firstValueFrom(this.http.get<RateView[]>(`${base}/applying`)),
280	      firstValueFrom(this.http.get<RateTier[]>(`${base}/tiers`)),
281	    ]);
282	    if (this.session.sheetId() === sheet) {
283	      this.applying.set([...applying].sort(byGradeThenFrom));
284	      this.tiers.set(tiers);
285	    }
286	  }
287	
288	  /**
289	   * Set the grade's rate from the date (null: from the beginning of time) through the to-date (null: with no end),
290	   * replacing the one it had for that from-date.
291	   */
292	  async set(sheet: string, grade: string, pct: string, from: string | null, to: string | null): Promise<void> {
293	    const r = await firstValueFrom(
294	      this.http.put<RateView>(`/api/sheets/${encodeURIComponent(sheet)}/rates/${grade}`, { pct, from, to }),
295	    );
296	    if (this.session.sheetId() === sheet) {
297	      this.list.update((l) => [...l.filter((x) => x.grade !== r.grade || x.from !== r.from), r].sort(byGradeThenFrom));
298	      await this.loadApplying(sheet);
299	    }
300	  }
301	
302	  /**
303	   * Withdraw the newest version of the grade's rate for the from-date (null: from the beginning of time): the version
304	   * before it applies again, and with none the rate is gone.
305	   */
306	  async withdraw(sheet: string, grade: string, from: string | null): Promise<void> {
307	    const params: Record<string, string> = from === null ? {} : { from };
308	    const r = await firstValueFrom(
309	      this.http.post<RateView | null>(
310	        `/api/sheets/${encodeURIComponent(sheet)}/rates/${grade}/withdraw`,
311	        null,
312	        { params },
313	      ),
314	    );
315	    if (this.session.sheetId() === sheet) {
316	      this.list.update((l) =>
317	        [...l.filter((x) => x.grade !== grade || x.from !== from), ...(r ? [r] : [])].sort(byGradeThenFrom),
318	      );
319	      await this.loadApplying(sheet);
320	    }
321	  }
322	
323	  /**
324	   * Set a rate for each line of grade,rate,from,to, in order, all of them or none; the store checks every line by the
325	   * rate form's rules first. Resolves to how many were set.
326	   */
327	  async importRates(sheet: string, text: string): Promise<number> {
328	    const set = await firstValueFrom(
329	      this.http.post<RateView[]>(`/api/sheets/${encodeURIComponent(sheet)}/rates/import`, { text }),
330	    );
331	    if (this.session.sheetId() === sheet) await this.load(sheet);
332	    return set.length;
333	  }
334	
335	  /** Preview the grade's rate at the percent on every date; nothing is saved. */
336	  preview(sheet: string, grade: string, pct: string): Promise<RatePreview> {
337	    return firstValueFrom(
338	      this.http.post<RatePreview>(`/api/sheets/${encodeURIComponent(sheet)}/rates/${grade}/preview`, { pct }),
339	    );
340	  }
341	}
