45	/** Whether a claim with the status counts: open, pending or settled. */
46	function countingStatus(status: ClaimStatus | null | undefined): boolean {
47	  return status === 'OPEN' || status === 'PENDING' || status === 'SETTLED';
48	}
49	
50	/** Whether the claim counted at the end of the day: its status then is open, pending or settled. */
51	function countedAtEndOf(f: DatedFigure, day: string): boolean {
52	  return countingStatus(statusAtEndOf(f, day));
53	}
54	
55	/** Whether the claim counts by its status now (open, pending or settled), whatever it was at the end of the day. */
56	function countedNow(f: DatedFigure): boolean {
57	  return countingStatus(f.status);
58	}
59	
60	/** How a period's due-total decides whether a claim counts: given the claim and the period's last day. */
61	export type PeriodCounting = (f: DatedFigure, lastDay: string) => boolean;
62	
63	const DATE = /^\d{4}-\d{2}-\d{2}$/;
64	
65	/**
66	 * The fiscal year the date falls in, named FY<yyyy> by the calendar year its first day falls in: fiscal years start on
67	 * the first of the start month (1 to 12).
68	 */
69	export function fiscalYearOf(date: string, startMonth: number): string {
70	  const year = Number(date.slice(0, 4));
71	  const month = Number(date.slice(5, 7));
72	  return `FY${month >= startMonth ? year : year - 1}`;
73	}
74	
75	/** The period whose dates contain the date; undefined when none does. */
76	export function periodOn(periods: readonly PeriodView[], date: string): PeriodView | undefined {
77	  return periods.find((p) => p.from <= date && date <= p.to);
78	}
79	
80	/** Whether a closed period contains the date. */
81	export function inClosedPeriod(periods: readonly PeriodView[], date: string): boolean {
82	  return periodOn(periods, date)?.closed ?? false;
83	}
84	
85	/**
86	 * The person's due-total for each period, by period id: a closed one's figure fixed for them when it was closed
87	 * (0.00 for a person added since), else the figures now of their claims due by a date in it that counted at the end of its
88	 * last day, skipping n/a.
89	 */
90	export function personPeriodDueTotals(
91	  periods: readonly PeriodView[],
92	  personId: number,
93	  figures: readonly DatedFigure[],
94	  counted: PeriodCounting = countedAtEndOf,
95	): Map<number, string> {
96	  const by = new Map<number, (string | null)[]>();
97	  for (const p of periods) by.set(p.id, []);
98	  for (const f of figures) {
99	    if (f.personId !== personId) continue;
100	    const p = periodOn(periods, f.dueBy);
101	    if (p && counted(f, p.to)) by.get(p.id)?.push(f.figure);
102	  }
103	  return new Map(
104	    periods.map((p) => [
105	      p.id,
106	      p.closed || p.softClosed ? (p.closedPersonTotals[personId] ?? '0.00') : sumSkippingNa(by.get(p.id) ?? []),
107	    ]),
108	  );
109	}
110	
111	/** Each period's count of the claims due by a date in it, by period id, VOID and DELETED claims left out. */
112	export function periodClaimCounts(periods: readonly PeriodView[], figures: readonly DatedFigure[]): Map<number, number> {
113	  const counts = new Map<number, number>(periods.map((p) => [p.id, 0]));
114	  for (const f of figures) {
115	    if (f.status === 'VOID' || f.status === 'DELETED') continue;
116	    const p = periodOn(periods, f.dueBy);
117	    if (p) counts.set(p.id, (counts.get(p.id) ?? 0) + 1);
118	  }
119	  return counts;
120	}
121	
122	/**
123	 * The person's carried figure for each period, by period id: a closed or soft-closed one's figure fixed for them when it
124	 * was closed (0.00 for a person added since), else the figures now of their claims belonging to a period that ends
125	 * before this one starts and still open or pending at the end of this one's last day, skipping n/a, plus their opening
126	 * balance for it.
127	 */
128	export function personPeriodCarried(
129	  periods: readonly PeriodView[],
130	  personId: number,
131	  figures: readonly DatedFigure[],
132	): Map<number, string> {
133	  const by = new Map<number, (string | null)[]>();
134	  for (const p of periods) by.set(p.id, [p.personOpenings[personId] ?? '0.00']);
135	  for (const f of figures) {
136	    if (f.personId !== personId) continue;
137	    const own = periodOn(periods, f.dueBy);
138	    if (!own) continue;
139	    for (const p of periods) {
140	      if (own.to >= p.from) continue;
141	      const status = statusAtEndOf(f, p.to);
142	      if (status === 'OPEN' || status === 'PENDING') by.get(p.id)?.push(f.figure);
143	    }
144	  }
145	  return new Map(
146	    periods.map((p) => [
147	      p.id,
148	      p.closed || p.softClosed ? (p.closedPersonCarried[personId] ?? '0.00') : sumSkippingNa(by.get(p.id) ?? []),
149	    ]),
150	  );
151	}
152	
153	/** Each period's due-total, by period id: the sum of the people's due-totals for it. */
154	export function periodDueTotals(
155	  periods: readonly PeriodView[],
156	  figures: readonly DatedFigure[],
157	  counted: PeriodCounting = countedAtEndOf,
158	): Map<number, string> {
159	  // everyone with a figure for some period: a counted claim, or one fixed when a period closed
160	  const people = new Set(figures.map((f) => f.personId));
161	  for (const p of periods) for (const id of Object.keys(p.closedPersonTotals)) people.add(Number(id));
162	  const each = [...people].map((id) => personPeriodDueTotals(periods, id, figures, counted));
163	  return new Map(periods.map((p) => [p.id, sumSkippingNa(each.map((m) => m.get(p.id) ?? null))]));
164	}
165	
166	/**
167	 * Each period's classic due-total, by period id: as periodDueTotals, but each claim counted by its status now (open,
168	 * pending or settled) rather than at the end of the period; a closed period still shows the figure fixed when it closed.
169	 */
170	export function classicPeriodDueTotals(
171	  periods: readonly PeriodView[],
172	  figures: readonly DatedFigure[],
173	): Map<number, string> {
174	  return periodDueTotals(periods, figures, countedNow);
175	}
