177	// The periods of the active sheet, by from-date.
178	@Injectable({ providedIn: 'root' })
179	export class PeriodStore {
180	  private readonly http = inject(HttpClient);
181	  private readonly session = inject(Session);
182	
183	  readonly list = signal<readonly PeriodView[]>([]);
184	
185	  /** Re-read the sheet's periods from the store. */
186	  async load(sheet: string): Promise<void> {
187	    this.list.set([]);
188	    const list = await firstValueFrom(this.http.get<PeriodView[]>(`/api/sheets/${encodeURIComponent(sheet)}/periods`));
189	    if (this.session.sheetId() === sheet) this.list.set(list);
190	  }
191	
192	  async add(sheet: string, name: string, from: string, to: string, cap: number | null): Promise<void> {
193	    const p = await firstValueFrom(
194	      this.http.post<PeriodView>(`/api/sheets/${encodeURIComponent(sheet)}/periods`, { name, from, to, cap }),
195	    );
196	    this.put(sheet, p);
197	  }
198	
199	  /** Generate one period per month from the from-date's month to the to-date's; answers how many were made. */
200	  async generate(sheet: string, from: string, to: string): Promise<number> {
201	    const made = await firstValueFrom(
202	      this.http.post<PeriodView[]>(`/api/sheets/${encodeURIComponent(sheet)}/periods/generate`, { from, to }),
203	    );
204	    for (const p of made) this.put(sheet, p);
205	    return made.length;
206	  }
207	
208	  /** Generate the fiscal year FY<year>'s twelve monthly periods as generate does; answers how many were made. */
209	  async generateFiscalYear(sheet: string, year: number): Promise<number> {
210	    const made = await firstValueFrom(
211	      this.http.post<PeriodView[]>(`/api/sheets/${encodeURIComponent(sheet)}/periods/generate-fy`, { year }),
212	    );
213	    for (const p of made) this.put(sheet, p);
214	    return made.length;
215	  }
216	
217	  /**
218	   * Roll FY<year> over: generate FY<year + 1>'s periods and carry each person's open figure into its first period's
219	   * opening balances; answers how many periods were made.
220	   */
221	  async rollover(sheet: string, year: number): Promise<number> {
222	    const made = await firstValueFrom(
223	      this.http.post<PeriodView[]>(`/api/sheets/${encodeURIComponent(sheet)}/periods/rollover`, { year }),
224	    );
225	    await this.load(sheet);
226	    return made.length;
227	  }
228	
229	  /** Undo the sheet's last rollover: its periods are removed and the opening balances it set taken back. */
230	  async undoRollover(sheet: string): Promise<void> {
231	    await firstValueFrom(this.http.post<void>(`/api/sheets/${encodeURIComponent(sheet)}/periods/rollover/undo`, {}));
232	    await this.load(sheet);
233	  }
234	
235	  /** Generate the calendar year's four quarterly periods, <yyyy>-Q1 to <yyyy>-Q4; answers how many were made. */
236	  async generateQuarters(sheet: string, year: number): Promise<number> {
237	    const made = await firstValueFrom(
238	      this.http.post<PeriodView[]>(`/api/sheets/${encodeURIComponent(sheet)}/periods/generate-quarters`, { year }),
239	    );
240	    for (const p of made) this.put(sheet, p);
241	    return made.length;
242	  }
243	
244	  async close(sheet: string, id: number): Promise<void> {
245	    const p = await firstValueFrom(
246	      this.http.post<PeriodView>(`/api/sheets/${encodeURIComponent(sheet)}/periods/${id}/close`, null),
247	    );
248	    this.put(sheet, p);
249	  }
250	
251	  async softClose(sheet: string, id: number): Promise<void> {
252	    const p = await firstValueFrom(
253	      this.http.post<PeriodView>(`/api/sheets/${encodeURIComponent(sheet)}/periods/${id}/soft-close`, null),
254	    );
255	    this.put(sheet, p);
256	  }
257	
258	  async reopen(sheet: string, id: number): Promise<void> {
259	    const p = await firstValueFrom(
260	      this.http.post<PeriodView>(`/api/sheets/${encodeURIComponent(sheet)}/periods/${id}/reopen`, null),
261	    );
262	    this.put(sheet, p);
263	  }
264	
265	  /** Lock the period, or unlock it. */
266	  async setLocked(sheet: string, id: number, locked: boolean): Promise<void> {
267	    const p = await firstValueFrom(
268	      this.http.post<PeriodView>(
269	        `/api/sheets/${encodeURIComponent(sheet)}/periods/${id}/${locked ? 'lock' : 'unlock'}`,
270	        null,
271	      ),
272	    );
273	    this.put(sheet, p);
274	  }
275	
276	  /** Add each pasted line of name,period,amount to the opening balances, all or none; answers how many went through. */
277	  async importOpenings(sheet: string, text: string): Promise<number> {
278	    const done = await firstValueFrom(
279	      this.http.post<{ count: number }>(`/api/sheets/${encodeURIComponent(sheet)}/periods/openings`, { text }),
280	    );
281	    await this.load(sheet);
282	    return done.count;
283	  }
284	
285	  private put(sheet: string, p: PeriodView): void {
286	    if (this.session.sheetId() === sheet) {
287	      this.list.update((l) => [...l.filter((x) => x.id !== p.id), p].sort((a, b) => a.from.localeCompare(b.from)));
288	    }
289	  }
290	}
