 19	/**
 20	 * Each person's cut total as the screen works it out: their cuts of the pots across every pool they are a member of
 21	 * (each crew counting as a pool), for the pools as they stand now on the sheet's today.
 22	 */
 23	@Service
 24	public class PoolCuts {
 25	
 26	    private static final BigInteger HUNDRED_PERCENT = BigInteger.valueOf(10000);
 27	
 28	    private final PoolStanding standing;
 29	
 30	    public PoolCuts(PoolStanding standing) {
 31	        this.standing = standing;
 32	    }
 33	
 34	    /** Each person's cut total, by person id; a person with no cut is absent. */
 35	    public Map<Long, BigDecimal> totals(String sheetId, LocalDate today) {
 36	        return totals(standing.now(sheetId, "", today, false));
 37	    }
 38	
 39	    /** A member as counted: its share in hundredths, and whether it has no cut or is left out. */
 40	    private record Counted(Long personId, Long poolId, long share, boolean retired, boolean held, boolean out) {
 41	    }
 42	
 43	    /** Each person's cut total for the pools as they then stood, by person id; a person with no cut is absent. */
 44	    public static Map<Long, BigDecimal> totals(PeriodPools standing) {
 45	        LocalDate day = standing.day();
 46	        Map<Long, Boolean> retired = new HashMap<>();
 47	        Set<Long> held = new HashSet<>();
 48	        for (RosterView p : standing.people()) {
 49	            retired.put(p.id(), p.retiredFrom() != null);
 50	            if (day != null && p.holds().stream().anyMatch(
 51	                    h -> !h.from().isAfter(day) && (h.to() == null || !day.isAfter(h.to())))) {
 52	                held.add(p.id());
 53	            }
 54	        }
 55	        List<PoolView> pools = new ArrayList<>(standing.pools());
 56	        for (CrewView crew : standing.crews()) {
 57	            pools.add(crewPool(crew));
 58	        }
 59	        Map<Long, Long> parent = new HashMap<>();
 60	        Map<Long, List<Counted>> counted = new HashMap<>();
 61	        Map<Long, Boolean> balanced = new HashMap<>();
 62	        for (PoolView pool : pools) {
 63	            List<Counted> members = new ArrayList<>();
 64	            long total = 0;
 65	            for (MemberView m : pool.members()) {
 66	                if (m.poolId() != null) {
 67	                    parent.put(m.poolId(), pool.id());
 68	                }
 69	                boolean out = day != null && ((m.from() != null && m.from().isAfter(day))
 70	                        || (m.to() != null && day.isAfter(m.to())));
 71	                long share = hundredths(m.share());
 72	                members.add(new Counted(m.personId(), m.poolId(), share,
 73	                        m.personId() != null && retired.getOrDefault(m.personId(), m.retired()),
 74	                        m.personId() != null && held.contains(m.personId()), out));
 75	                if (!out) {
 76	                    total += share;
 77	                }
 78	            }
 79	            counted.put(pool.id(), members);
 80	            balanced.put(pool.id(), total == 10000);
 81	        }
 82	        Map<Long, BigInteger[]> cutsOf = new HashMap<>();
 83	        Map<Long, BigInteger> sums = new HashMap<>();
 84	        for (PoolView pool : pools) {
 85	            BigInteger[] cut = poolCuts(pool.id(), standing.pot(), parent, counted, balanced, cutsOf);
 86	            if (cut == null) {
 87	                continue;
 88	            }
 89	            List<Counted> members = counted.get(pool.id());
 90	            for (int i = 0; i < members.size(); i++) {
 91	                Counted m = members.get(i);
 92	                if (m.personId() != null && !m.out()) {
 93	                    sums.merge(m.personId(), cut[i], BigInteger::add);
 94	                }
 95	            }
 96	        }
 97	        Map<Long, BigDecimal> totals = new HashMap<>();
 98	        sums.forEach((id, c) -> totals.put(id, new BigDecimal(c, 2)));
 99	        return totals;
100	    }
101	
102	    /** The pool's cuts (in cents, in member order), or null for none; worked out top down. */
103	    private static BigInteger[] poolCuts(Long id, String sheetPot, Map<Long, Long> parent,
104	            Map<Long, List<Counted>> counted, Map<Long, Boolean> balanced, Map<Long, BigInteger[]> cutsOf) {
105	        if (cutsOf.containsKey(id)) {
106	            return cutsOf.get(id);
107	        }
108	        BigInteger pot = null;
109	        Long above = parent.get(id);
110	        if (above == null) {
111	            pot = sheetPot == null ? null : new BigDecimal(sheetPot).movePointRight(2).toBigIntegerExact();
112	        } else if (counted.containsKey(above)) {
113	            BigInteger[] aboveCuts = poolCuts(above, sheetPot, parent, counted, balanced, cutsOf);
114	            List<Counted> members = counted.get(above);
115	            for (int i = 0; i < members.size(); i++) {
116	                if (id.equals(members.get(i).poolId())) {
117	                    pot = aboveCuts == null ? null : aboveCuts[i];
118	                    break;
119	                }
120	            }
121	        }
122	        BigInteger[] result = balanced.getOrDefault(id, false) && pot != null ? cuts(pot, counted.get(id)) : null;
123	        cutsOf.put(id, result);
124	        return result;
125	    }
126	
127	    /**
128	     * Each member's cut of the pot (in cents), in member order: the pot times their share over the shares of the
129	     * members with a cut added up, rounded half to even to the cent; a retired member, a held one, and one left out,
130	     * has none (0). The remainder left by the rounding goes to the member with the smallest non-zero cut (the latest
131	     * added on a tie), or, with none, to the last member with a share; a pool whose every member is retired has no
132	     * cuts at all (null).
133	     */
134	    private static BigInteger[] cuts(BigInteger pot, List<Counted> members) {
135	        if (!members.isEmpty() && members.stream().allMatch(Counted::retired)) {
136	            return null;
137	        }
138	        BigInteger[] shares = new BigInteger[members.size()];
139	        BigInteger of = BigInteger.ZERO;
140	        for (int i = 0; i < shares.length; i++) {
141	            Counted m = members.get(i);
142	            shares[i] = m.retired() || m.held() || m.out() ? BigInteger.ZERO : BigInteger.valueOf(m.share());
143	            of = of.add(shares[i]);
144	        }
145	        BigInteger[] result = new BigInteger[shares.length];
146	        if (of.signum() == 0) {
147	            java.util.Arrays.fill(result, BigInteger.ZERO);
148	            return result;
149	        }
150	        BigInteger sum = BigInteger.ZERO;
151	        for (int i = 0; i < shares.length; i++) {
152	            BigInteger[] qr = pot.multiply(shares[i]).divideAndRemainder(of);
153	            BigInteger q = qr[0];
154	            int r = qr[1].shiftLeft(1).compareTo(of);
155	            if (r > 0 || (r == 0 && q.testBit(0))) {
156	                q = q.add(BigInteger.ONE);
157	            }
158	            result[i] = q;
159	            sum = sum.add(q);
160	        }
161	        int to = -1;
162	        for (int i = 0; i < result.length; i++) {
163	            if (result[i].signum() != 0 && (to < 0 || result[i].compareTo(result[to]) <= 0)) {
164	                to = i;
165	            }
166	        }
167	        if (to < 0) {
168	            for (int i = 0; i < shares.length; i++) {
169	                if (shares[i].signum() > 0) {
170	                    to = i;
171	                }
172	            }
173	        }
174	        result[to] = result[to].add(pot.subtract(sum));
175	        return result;
176	    }
177	
178	    /** A crew as a pool: its lead and members, in that order, at equal shares of 100.00, the remainder on the lead. */
179	    private static PoolView crewPool(CrewView crew) {
180	        List<Long> people = new ArrayList<>();
181	        if (crew.leadId() != null) {
182	            people.add(crew.leadId());
183	        }
184	        crew.members().forEach(m -> people.add(m.personId()));
185	        List<MemberView> members = new ArrayList<>();
186	        if (!people.isEmpty()) {
187	            BigInteger n = BigInteger.valueOf(people.size());
188	            BigInteger[] qr = HUNDRED_PERCENT.divideAndRemainder(n);
189	            BigInteger share = qr[0];
190	            int r = qr[1].shiftLeft(1).compareTo(n);
191	            if (r > 0 || (r == 0 && share.testBit(0))) {
192	                share = share.add(BigInteger.ONE);
193	            }
194	            BigInteger first = HUNDRED_PERCENT.subtract(share.multiply(n.subtract(BigInteger.ONE)));
195	            for (int i = 0; i < people.size(); i++) {
196	                members.add(new MemberView(people.get(i), null, "",
197	                        new BigDecimal(i == 0 ? first : share, 2).toPlainString(), false, null, null, true));
198	            }
199	        }
200	        return new PoolView(-crew.id(), crew.name(), members, "100.00", true);
201	    }
202	
203	    private static long hundredths(String share) {
204	        return new BigDecimal(share).movePointRight(2).longValueExact();
205	    }
206	}
