221	/**
222	 * The pools of a sheet as they stand in the store read now: what the screen works out a member's cut from (the pools,
223	 * the crews, the people with their retirement and holds, and the pot), for a period with a day standing in for the
224	 * sheet's today. A closed period keeps them as JSON, so its cuts stay as they were when it closed.
225	 */
226	@Service
227	public class PoolStanding {
228	
229	    private final SheetService sheets;
230	    private final PersonRepository people;
231	    private final PoolController pools;
232	    private final CrewController crews;
233	    private final JsonMapper json;
234	
235	    public PoolStanding(SheetService sheets, PersonRepository people, PoolController pools, CrewController crews,
236	            JsonMapper json) {
237	        this.sheets = sheets;
238	        this.people = people;
239	        this.pools = pools;
240	        this.crews = crews;
241	        this.json = json;
242	    }
243	
244	    /** The pools as they stand now, for the period, with the day as its today; fixed: kept from a close. */
245	    public PeriodPools now(String sheetId, String period, LocalDate day, boolean fixed) {
246	        Sheet sheet = sheets.load(sheetId);
247	        List<RosterView> roster = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
248	                .map(p -> new RosterView(p.getId(), p.getName(), p.getRetiredFrom(),
249	                        p.getHolds().stream().map(HoldView::of).toList()))
250	                .toList();
251	        return new PeriodPools(period, day, pools.list(sheetId), crews.list(sheetId), roster,
252	                sheet.getPot() == null ? null : sheet.getPot().setScale(2).toPlainString(), fixed);
253	    }
254	
255	    /** The pools as they stand now, with the sheet's today, as kept on a period when it closes. */
256	    public String fix(String sheetId, String period) {
257	        return json.writeValueAsString(now(sheetId, period, sheets.load(sheetId).getToday(), true));
258	    }
259	
260	    /** Pools kept by {@link #fix}, under the period's name now. */
261	    public PeriodPools fixed(String kept, String period) {
262	        PeriodPools p = json.readValue(kept, PeriodPools.class);
263	        return new PeriodPools(period, p.day(), p.pools(), p.crews(), p.people(), p.pot(), true);
264	    }
