25	/**
26	 * A sheet's settings: the role each user name has; the clerk limit, the floor, the terms (the sheet's and each
27	 * grade's), the late percent and the cap, each recorded from a from-date; the policy date and the period numbering
28	 * from; the grace days; the permission matrix, the roles that may take each action; and the delegations of the
29	 * steward role. It tells the audit for whom a delegated user acts.
30	 */
31	@Service
32	public class SettingsService implements Audit.OnBehalf {
33	
34	    /** The actions of the permission matrix, with the roles that may take each while none are set. */
35	    public static final Map<String, List<String>> STANDING_PERMISSIONS = Map.of(
36	            "open", List.of(SheetRole.CLERK, SheetRole.STEWARD),
37	            "settle", List.of(SheetRole.CLERK, SheetRole.STEWARD),
38	            "void", List.of(SheetRole.CLERK, SheetRole.STEWARD),
39	            "reassign", List.of(SheetRole.STEWARD),
40	            "close", List.of(SheetRole.CLERK, SheetRole.STEWARD),
41	            "reopen", List.of(SheetRole.STEWARD),
42	            "today", List.of(SheetRole.CLERK, SheetRole.STEWARD, SheetRole.RESTRICTED));
43	
44	    private final SheetRoleRepository roles;
45	    private final DelegationRepository delegations;
46	    private final SheetRepository sheetRepository;
47	    private final SheetService sheets;
48	    private final RollupService rollup;
49	    private final Audit audit;
50	
51	    public SettingsService(SheetRoleRepository roles, DelegationRepository delegations,
52	            SheetRepository sheetRepository, SheetService sheets, RollupService rollup, Audit audit) {
53	        this.roles = roles;
54	        this.delegations = delegations;
55	        this.sheetRepository = sheetRepository;
56	        this.sheets = sheets;
57	        this.rollup = rollup;
58	        this.audit = audit;
59	    }
60	
61	    /** The roles set on the sheet, by user name. */
62	    @Transactional(readOnly = true)
63	    public List<SheetRole> roles(String sheetId) {
64	        return roles.findBySheetIdOrderByUserAsc(sheetId);
65	    }
66	
67	    /**
68	     * The role the user acts in on the sheet: steward while a steward's delegation to them covers the sheet's today,
69	     * else the role set for them, clerk unless set otherwise.
70	     */
71	    @Transactional(readOnly = true)
72	    public String roleOf(String sheetId, String user) {
73	        String set = setRoleOf(sheetId, user);
74	        if (!SheetRole.STEWARD.equals(set) && delegatorOf(sheetId, user).isPresent()) {
75	            return SheetRole.STEWARD;
76	        }
77	        return set;
78	    }
79	
80	    /** The role set for the user on the sheet, leaving delegations aside: clerk unless set otherwise. */
81	    private String setRoleOf(String sheetId, String user) {
82	        return roles.findBySheetIdAndUser(sheetId, user).map(SheetRole::getRole).orElse(SheetRole.CLERK);
83	    }
84	
85	    /**
86	     * The steward the user acts for on the sheet: the one whose delegation to them, made first, covers the sheet's
87	     * today and who is still a steward; empty when there is none.
88	     */
89	    @Transactional(readOnly = true)
90	    public Optional<String> delegatorOf(String sheetId, String user) {
91	        List<Delegation> made = delegations.findBySheetIdAndUserOrderByIdAsc(sheetId, user);
92	        if (made.isEmpty()) {
93	            return Optional.empty();
94	        }
95	        LocalDate today = sheets.load(sheetId).getToday();
96	        return made.stream().filter(d -> d.covers(today))
97	                .filter(d -> SheetRole.STEWARD.equals(setRoleOf(sheetId, d.getDelegatedBy())))
98	                .map(Delegation::getDelegatedBy).findFirst();
99	    }
100	
101	    @Override
102	    public Optional<String> forOf(String sheetId, String user) {
103	        return delegatorOf(sheetId, user);
104	    }
105	
106	    /** The delegations made on the sheet, in the order they were made. */
107	    @Transactional(readOnly = true)
108	    public List<Delegation> delegations(String sheetId) {
109	        return delegations.findBySheetIdOrderByIdAsc(sheetId);
110	    }
111	
112	    /**
113	     * Delegates the steward role to the user from the from-date to the to-date, inclusive (each the sheet's today
114	     * when null). Refused unless the one delegating has the steward role set (not delegated), or when the to-date
115	     * is before the from-date.
116	     */
117	    @Transactional
118	    public Delegation delegate(String by, String sheetId, String user, LocalDate from, LocalDate to) {
119	        Sheet sheet = sheets.lock(sheetId);
120	        if (!SheetRole.STEWARD.equals(setRoleOf(sheetId, by))) {
121	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can delegate the steward role.");
122	        }
123	        LocalDate start = from == null ? sheet.getToday() : from;
124	        LocalDate end = to == null ? sheet.getToday() : to;
125	        if (end.isBefore(start)) {
126	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
127	                    "The to-date cannot be before the from-date.");
128	        }
129	        Delegation saved = delegations.saveAndFlush(new Delegation(sheetId, user, by, start, end));
130	        audit.recordOnCommit("DELEGATED sheet=" + sheetId + " by=" + by + " user=" + user + " from=" + start
131	                + " to=" + end);
132	        return saved;
133	    }
134	
135	    /** Archives the sheet, after which every change on it is refused. Refused unless the one archiving is a steward. */
136	    @Transactional
137	    public Sheet archive(String by, String sheetId) {
138	        Sheet sheet = sheets.lock(sheetId);
139	        if (!isSteward(sheetId, by)) {
140	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can archive the sheet.");
141	        }
142	        sheet.archive();
143	        Sheet saved = sheetRepository.saveAndFlush(sheet);
144	        audit.recordOnCommit("SHEET_ARCHIVED sheet=" + sheetId + " by=" + by);
145	        return saved;
146	    }
