148	    /** Sets the user's role on the sheet; refused unless it is clerk, steward, viewer or restricted. */
149	    @Transactional
150	    public SheetRole setRole(String by, String sheetId, String user, String role) {
151	        if (!SheetRole.CLERK.equals(role) && !SheetRole.STEWARD.equals(role) && !SheetRole.VIEWER.equals(role)
152	                && !SheetRole.RESTRICTED.equals(role)) {
153	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
154	                    "A role is clerk, steward, viewer or restricted.");
155	        }
156	        sheets.lock(sheetId);
157	        SheetRole r = roles.findBySheetIdAndUser(sheetId, user).orElseGet(() -> new SheetRole(sheetId, user, role));
158	        r.setRole(role);
159	        SheetRole saved;
160	        try {
161	            saved = roles.saveAndFlush(r);
162	        } catch (DataIntegrityViolationException e) {
163	            throw new ResponseStatusException(HttpStatus.CONFLICT, "That role was just set by someone else.");
164	        }
165	        audit.recordOnCommit("ROLE_SET sheet=" + sheetId + " by=" + by + " user=" + user + " role=" + role);
166	        return saved;
167	    }
