169	    /**
170	     * Sets the roles that may take the action, a comma separated list of clerk and steward; blank (null) for the
171	     * standing rule. Refused for an action not in the matrix or a role that is neither. Not dated.
172	     */
173	    @Transactional
174	    public Sheet setPermission(String by, String sheetId, String action, String roles) {
175	        if (!STANDING_PERMISSIONS.containsKey(action)) {
176	            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "No such action.");
177	        }
178	        String value = null;
179	        if (roles != null && !roles.isBlank()) {
180	            List<String> listed = Arrays.stream(roles.split(",", -1)).map(String::strip).toList();
181	            if (listed.stream().anyMatch(r -> !SheetRole.CLERK.equals(r) && !SheetRole.STEWARD.equals(r))) {
182	                throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
183	                        "List the roles as clerk, steward or both, separated by commas.");
184	            }
185	            value = String.join(",", listed.stream().distinct().toList());
186	        }
187	        Sheet sheet = sheets.lock(sheetId);
188	        sheet.setPermission(action, value);
189	        Sheet saved = sheetRepository.saveAndFlush(sheet);
190	        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + by + " key=perm-" + action + " value="
191	                + (value == null ? "" : value));
192	        return saved;
193	    }
