195	    /** Whether the user's role may take the action on the sheet: as the matrix sets it, else the standing rule. */
196	    @Transactional(readOnly = true)
197	    public boolean may(String sheetId, String user, String action) {
198	        String set = sheets.load(sheetId).getPermissions().get(action);
199	        List<String> allowed = set == null ? STANDING_PERMISSIONS.get(action) : List.of(set.split(","));
200	        return allowed.contains(roleOf(sheetId, user));
201	    }
