203	    /** Refuses the user the action when their role may not take it on the sheet. */
204	    public void refuseUnlessMay(String sheetId, String user, String action) {
205	        if (!may(sheetId, user, action)) {
206	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Your role may not " + action + " here.");
207	        }
208	    }
