155	/**
156	 * Refuses a viewer, and anyone on an archived sheet, every request that changes a sheet, before it reaches its
157	 * handler, so it writes nothing. A handler marked {@link ViewerPasses} is let through.
158	 */
159	@Component
160	public class ViewerGuard implements HandlerInterceptor {
161	
162	    private final SettingsService settings;
163	
164	    public ViewerGuard(SettingsService settings) {
165	        this.settings = settings;
166	    }
