168	    @Override
169	    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
170	        if (!(handler instanceof HandlerMethod method) || HttpMethod.GET.matches(request.getMethod())
171	                || method.hasMethodAnnotation(ViewerPasses.class)) {
172	            return true;
173	        }
174	        HttpSession session = request.getSession(false);
175	        Object user = session == null ? null : session.getAttribute(SessionController.USER);
176	        String sheetId = sheetId(request);
177	        if (sheetId != null && settings.isArchived(sheetId)) {
178	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "The sheet is archived; nothing on it can change.");
179	        }
180	        if (user instanceof String name && sheetId != null && settings.isViewer(sheetId, name)) {
181	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "A viewer may not change anything.");
182	        }
183	        return true;
184	    }
