186	    /** The sheet the request is on: its sheetId path variable, or the id of a /api/sheets/{id} path. */
187	    public static String sheetId(HttpServletRequest request) {
188	        @SuppressWarnings("unchecked")
189	        Map<String, String> vars = (Map<String, String>) request
190	                .getAttribute(HandlerMapping.URI_TEMPLATE_VARIABLES_ATTRIBUTE);
191	        if (vars == null) {
192	            return null;
193	        }
194	        String sheetId = vars.get("sheetId");
195	        if (sheetId == null && request.getRequestURI().startsWith(request.getContextPath() + "/api/sheets/")) {
