55	            LocalDate today = sheet.getToday();
56	            return new SettingsView(sheet.getClerkLimit() == null ? null : sheet.getClerkLimit().toPlainString(),
57	                    sheet.floorOn(today).toPlainString(), sheet.termsOn(today), sheet.latePctOn(today).toPlainString(),
