59	                    sheet.getCap() == null ? null : sheet.getCap().toPlainString(),
60	                    sheet.getSettings().stream().map(DatedSettingView::of)
61	                            .sorted(Comparator.comparing(DatedSettingView::key).thenComparing(DatedSettingView::from))
62	                            .toList(),
63	                    sheet.getPermissions(), sheet.getPot() == null ? null : sheet.getPot().toPlainString(),
64	                    sheet.getAlertThreshold() == null ? null : sheet.getAlertThreshold().toPlainString(),
65	                    sheet.getParentId(), sheet.getFiscalStartMonth(), sheet.getEscalateAfter(),
