 19	/**
 20	 * The sheet's pools and their members. A person is in a pool at most once, with a share percent of more than 0.00 and
 21	 * at most 100.00, and may be in several pools. A pool may be a member of another, with a share like a person's: of at
 22	 * most one pool, never containing itself through any chain, and in a chain of pools at most {@value #MAX_DEPTH} deep.
 23	 * A membership may carry a from-date and a to-date (each optional, both included); a to-date before the from-date is
 24	 * refused. A member whose dates do not include the sheet's today is left out of the pool.
 25	 */
 26	@Service
 27	public class PoolService {
 28	
 29	    private static final BigDecimal HUNDRED = new BigDecimal("100.00");
 30	
 31	    /** The most pools in a chain, the top one counted. */
 32	    static final int MAX_DEPTH = 3;
 33	
 34	    private final PoolRepository pools;
 35	    private final PoolMemberRepository members;
 36	    private final PersonRepository people;
 37	    private final CrewRepository crews;
 38	    private final SheetService sheets;
 39	    private final Audit audit;
 40	
 41	    public PoolService(PoolRepository pools, PoolMemberRepository members, PersonRepository people,
 42	            CrewRepository crews, SheetService sheets, Audit audit) {
 43	        this.pools = pools;
 44	        this.crews = crews;
 45	        this.members = members;
 46	        this.people = people;
 47	        this.sheets = sheets;
 48	        this.audit = audit;
 49	    }
 50	
 51	    /** The sheet's pools, in the order they were added. */
 52	    @Transactional(readOnly = true)
 53	    public List<Pool> list(String sheetId) {
 54	        return pools.findBySheetIdOrderByIdAsc(sheetId);
 55	    }
 56	
 57	    /** The members of every pool on the sheet, in the order they were added. */
 58	    @Transactional(readOnly = true)
 59	    public List<PoolMember> members(String sheetId) {
 60	        return members.findBySheetIdOrderByIdAsc(sheetId);
 61	    }
 62	
 63	    /**
 64	     * Adds a pool under its name, trimmed; refused when blank or already a pool's name or a crew's (a crew is also a
 65	     * pool, under its name).
 66	     */
 67	    @Transactional
 68	    public Pool add(String by, String sheetId, String name) {
 69	        String key = name == null ? "" : name.strip();
 70	        if (key.isEmpty()) {
 71	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "Enter a pool name.");
 72	        }
 73	        sheets.lock(sheetId);
 74	        if (pools.existsBySheetIdAndName(sheetId, key)) {
 75	            throw new ResponseStatusException(HttpStatus.CONFLICT, key + " is already a pool.");
 76	        }
 77	        if (crews.existsBySheetIdAndName(sheetId, key)) {
 78	            throw new ResponseStatusException(HttpStatus.CONFLICT, key + " is already a crew.");
 79	        }
 80	        Pool added = pools.saveAndFlush(new Pool(sheetId, key));
 81	        audit.recordOnCommit("POOL_ADDED sheet=" + sheetId + " by=" + by + " name=" + key);
 82	        return added;
 83	    }
 84	
 85	    /**
 86	     * Adds the person to the pool with a share; refused when the person is already in it, or the share is not more
 87	     * than 0.00 and at most 100.00 with up to two decimals.
 88	     */
 89	    @Transactional
 90	    public PoolMember addMember(String by, String sheetId, Long poolId, Long personId, BigDecimal share,
 91	            LocalDate from, LocalDate to) {
 92	        BigDecimal scaled = validShare(share);
 93	        validDates(from, to);
 94	        sheets.lock(sheetId);
 95	        Pool pool = pool(sheetId, poolId);
 96	        Person person = people.findByIdAndSheetId(personId, sheetId)
 97	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "Choose a person."));
 98	        if (members.existsByPoolIdAndPersonId(pool.getId(), person.getId())) {
 99	            throw new ResponseStatusException(HttpStatus.CONFLICT,
100	                    person.getName() + " is already in " + pool.getName() + ".");
101	        }
102	        PoolMember member = new PoolMember(sheetId, pool.getId(), person.getId(), scaled);
103	        member.setDates(from, to);
104	        PoolMember added = members.saveAndFlush(member);
105	        audit.recordOnCommit("POOL_MEMBER_ADDED sheet=" + sheetId + " by=" + by + " pool=" + pool.getName()
106	                + " name=" + person.getName() + " share=" + scaled.toPlainString() + dated(from, to));
107	        return added;
108	    }
109	
110	    /**
111	     * Adds another pool to the pool with a share; refused when the share is not valid (as for a person), when the
112	     * member pool is already a member of a pool (this or another), when it is the pool itself or contains it through
113	     * any chain, or when the chain of pools would be more than {@value #MAX_DEPTH} deep.
114	     */
115	    @Transactional
116	    public PoolMember addPoolMember(String by, String sheetId, Long poolId, Long memberPoolId,
117	            BigDecimal share, LocalDate from, LocalDate to) {
118	        BigDecimal scaled = validShare(share);
119	        validDates(from, to);
120	        sheets.lock(sheetId);
121	        Pool pool = pool(sheetId, poolId);
122	        Pool member = pools.findById(memberPoolId).filter(p -> p.getSheetId().equals(sheetId))
123	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, "Choose a member."));
124	        // each pool that is a member of another, to the pool it is in
125	        Map<Long, Long> parent = new HashMap<>();
126	        for (PoolMember m : members.findBySheetIdOrderByIdAsc(sheetId)) {
127	            if (m.getMemberPoolId() != null) {
128	                parent.put(m.getMemberPoolId(), m.getPoolId());
129	            }
130	        }
131	        int above = 0;
132	        for (Long p = pool.getId(); p != null; p = parent.get(p)) {
133	            if (p.equals(member.getId())) {
134	                throw new ResponseStatusException(HttpStatus.CONFLICT,
135	                        member.getName() + " would contain itself through " + pool.getName() + ".");
136	            }
137	            above++;
138	        }
139	        if (parent.containsKey(member.getId())) {
140	            throw new ResponseStatusException(HttpStatus.CONFLICT, member.getName() + " is already a member of a pool.");
141	        }
142	        if (above + height(member.getId(), parent) > MAX_DEPTH) {
143	            throw new ResponseStatusException(HttpStatus.CONFLICT,
144	                    "A chain of pools may be at most " + MAX_DEPTH + " deep.");
145	        }
146	        PoolMember membership = PoolMember.ofPool(sheetId, pool.getId(), member.getId(), scaled);
147	        membership.setDates(from, to);
148	        PoolMember added = members.saveAndFlush(membership);
149	        audit.recordOnCommit("POOL_MEMBER_ADDED sheet=" + sheetId + " by=" + by + " pool=" + pool.getName()
150	                + " name=" + member.getName() + " share=" + scaled.toPlainString() + dated(from, to));
151	        return added;
152	    }
153	
154	    /** How many pools deep the chain below a pool goes, the pool itself counted. */
155	    private static int height(Long poolId, Map<Long, Long> parent) {
156	        int most = 0;
157	        for (Map.Entry<Long, Long> e : parent.entrySet()) {
158	            if (e.getValue().equals(poolId)) {
159	                most = Math.max(most, height(e.getKey(), parent));
160	            }
161	        }
162	        return most + 1;
163	    }
164	
165	    private Pool pool(String sheetId, Long poolId) {
166	        return pools.findById(poolId).filter(p -> p.getSheetId().equals(sheetId))
167	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such pool."));
168	    }
169	
170	    /** Refused when both dates are given and the to-date is before the from-date. */
171	    private static void validDates(LocalDate from, LocalDate to) {
172	        if (from != null && to != null && to.isBefore(from)) {
173	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
174	                    "A membership cannot end before it starts.");
175	        }
176	    }
177	
178	    /** The audit fields for the dates given: from=<date> and to=<date>, each only when given. */
179	    private static String dated(LocalDate from, LocalDate to) {
180	        return (from == null ? "" : " from=" + from) + (to == null ? "" : " to=" + to);
181	    }
182	
183	    /** The share at two decimals; refused unless more than 0.00 and at most 100.00 with up to two decimals. */
184	    private static BigDecimal validShare(BigDecimal share) {
185	        if (share == null || share.signum() <= 0 || share.compareTo(HUNDRED) > 0
186	                || share.stripTrailingZeros().scale() > 2) {
187	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
188	                    "Enter a share of more than 0.00 and at most 100.00, with up to two decimals.");
189	        }
190	        return share.setScale(2, RoundingMode.UNNECESSARY);
191	    }
