303	    private static PoolView view(Pool pool, List<PoolMember> members, Map<Long, Person> byId,
304	            Map<Long, String> poolNames, LocalDate today) {
305	        BigDecimal total = BigDecimal.ZERO.setScale(2);
306	        List<MemberView> views = new ArrayList<>();
307	        for (PoolMember m : members) {
308	            boolean current = today == null || m.includes(today);
309	            if (m.getMemberPoolId() != null) {
310	                if (current) {
311	                    total = total.add(m.getShare());
312	                }
313	                views.add(new MemberView(null, m.getMemberPoolId(), poolNames.getOrDefault(m.getMemberPoolId(), ""),
314	                        m.getShare().setScale(2).toPlainString(), false, m.getFrom(), m.getTo(), current));
315	                continue;
316	            }
317	            Person person = byId.get(m.getPersonId());
318	            boolean retired = person == null || person.getRetiredFrom() != null;
319	            if (current) {
320	                total = total.add(m.getShare());
321	            }
322	            views.add(new MemberView(m.getPersonId(), null, person == null ? "" : person.getName(),
323	                    m.getShare().setScale(2).toPlainString(), retired, m.getFrom(), m.getTo(), current));
324	        }
325	        return new PoolView(pool.getId(), pool.getName(), views, total.toPlainString(),
326	                total.compareTo(BALANCED) == 0);
327	    }
