275	    /** The schema, as statements that create it empty. */
276	    private List<String> schema() {
277	        List<String> s = schema;
278	        if (s == null) {
279	            s = List.copyOf(jdbc.queryForList("SCRIPT NODATA", String.class));
280	            schema = s;
281	        }
282	        return s;
283	    }
