285	    /** The tables whose rows are kept for a sheet, found from the schema. */
286	    private List<Kept> kept() {
287	        List<Kept> k = kept;
288	        if (k == null) {
289	            k = jdbc.execute(AsOfService::findKept);
290	            kept = k;
291	        }
292	        return k;
293	    }
294	
295	    private static List<Kept> findKept(Connection c) throws SQLException {
296	        Map<String, List<String>> columns = new LinkedHashMap<>();
297	        Map<String, Boolean> hasSheetId = new LinkedHashMap<>();
298	        try (PreparedStatement q = c.prepareStatement(
299	                "SELECT c.TABLE_NAME, c.COLUMN_NAME, c.IS_GENERATED FROM INFORMATION_SCHEMA.COLUMNS c"
300	                        + " JOIN INFORMATION_SCHEMA.TABLES t ON t.TABLE_SCHEMA = c.TABLE_SCHEMA"
301	                        + " AND t.TABLE_NAME = c.TABLE_NAME"
302	                        + " WHERE c.TABLE_SCHEMA = 'PUBLIC' AND t.TABLE_TYPE = 'BASE TABLE'"
303	                        + " ORDER BY c.TABLE_NAME, c.ORDINAL_POSITION");
304	                ResultSet rs = q.executeQuery()) {
305	            while (rs.next()) {
306	                String table = rs.getString(1);
307	                if (NOT_KEPT.contains(table)) {
308	                    continue;
309	                }
310	                columns.computeIfAbsent(table, t -> new ArrayList<>());
311	                if ("SHEET_ID".equals(rs.getString(2))) {
312	                    hasSheetId.put(table, true);
313	                }
314	                if (!"ALWAYS".equals(rs.getString(3))) {
315	                    columns.get(table).add(rs.getString(2));
316	                }
317	            }
318	        }
319	        Map<String, String> where = new LinkedHashMap<>();
320	        for (String table : columns.keySet()) {
321	            if (table.equals("SHEET")) {
322	                where.put(table, quoted("ID") + " = ?");
323	            } else if (hasSheetId.getOrDefault(table, false)) {
324	                where.put(table, quoted("SHEET_ID") + " = ?");
325	            }
326	        }
327	        // a table with no sheet_id is kept through a row it refers to that is kept
328	        DatabaseMetaData meta = c.getMetaData();
329	        boolean found = true;
330	        while (found) {
331	            found = false;
332	            for (String table : columns.keySet()) {
333	                if (where.containsKey(table)) {
334	                    continue;
335	                }
336	                try (ResultSet keys = meta.getImportedKeys(null, "PUBLIC", table)) {
337	                    while (keys.next()) {
338	                        String parent = keys.getString("PKTABLE_NAME");
339	                        if (where.containsKey(parent)) {
340	                            where.put(table, quoted(keys.getString("FKCOLUMN_NAME")) + " IN (SELECT "
341	                                    + quoted(keys.getString("PKCOLUMN_NAME")) + " FROM " + quoted(parent) + " WHERE "
342	                                    + where.get(parent) + ")");
343	                            found = true;
344	                            break;
345	                        }
346	                    }
347	                }
348	            }
349	        }
350	        List<Kept> kept = new ArrayList<>();
351	        where.forEach((table, w) -> kept.add(new Kept(table, List.copyOf(columns.get(table)), w)));
352	        return List.copyOf(kept);
353	    }
354	
355	    private static String quoted(String name) {
356	        return '"' + name.replace("\"", "\"\"") + '"';
357	    }
358	}
