114	    public byte[] toBytes() {
115	        ByteArrayOutputStream bytes = new ByteArrayOutputStream();
116	        try (ObjectOutputStream out = new ObjectOutputStream(new GZIPOutputStream(bytes))) {
117	            out.writeObject(this);
118	        } catch (IOException e) {
119	            throw new UncheckedIOException(e);
120	        }
121	        return bytes.toByteArray();
122	    }
123	
124	    public static SheetState of(byte[] data) {
125	        try (ObjectInputStream in = new ObjectInputStream(new GZIPInputStream(new ByteArrayInputStream(data)))) {
126	            return (SheetState) in.readObject();
127	        } catch (IOException e) {
128	            throw new UncheckedIOException(e);
129	        } catch (ClassNotFoundException e) {
130	            throw new IllegalStateException(e);
131	        }
132	    }
