326	/**
327	 * A screen showing a sheet as of a date sends that date with each request ({@link #HEADER}). Such a request is
328	 * answered from the sheet as it stood at the end of the date (see {@link AsOfService#storeAsOf}), and every request
329	 * that changes the sheet is refused before it reaches its handler, so it writes nothing. A handler marked
330	 * {@link AsOfReads} changes nothing and is answered as of the date.
331	 */
332	@Component
333	public class AsOfGuard implements HandlerInterceptor {
334	
335	    /** The request header carrying the date the screen shows the sheet as of (yyyy-mm-dd). */
336	    public static final String HEADER = "X-As-Of";
337	
338	    private final AsOfService asOf;
339	
340	    public AsOfGuard(AsOfService asOf) {
341	        this.asOf = asOf;
342	    }
343	
344	    @Override
345	    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
346	        String header = request.getHeader(HEADER);
347	        String sheetId = ViewerGuard.sheetId(request);
348	        if (header == null || header.isBlank() || !(handler instanceof HandlerMethod method) || sheetId == null) {
349	            return true;
350	        }
351	        LocalDate day;
352	        try {
353	            day = LocalDate.parse(header.trim());
354	        } catch (DateTimeParseException e) {
355	            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The as-of date is not a date.");
356	        }
357	        if (!HttpMethod.GET.matches(request.getMethod()) && !method.hasMethodAnnotation(AsOfReads.class)) {
358	            throw new ResponseStatusException(HttpStatus.CONFLICT,
359	                    "The sheet is shown as of a date; nothing on it can change.");
360	        }
