316	export class Summary {
317	  private readonly http = inject(HttpClient);
318	  private readonly session = inject(Session);
319	  private readonly periods = inject(PeriodStore);
320	  private readonly voidReasons = inject(VoidReasonStore);
321	  private readonly grades = inject(SettingsStore).grades;
322	
323	  readonly people = input<readonly SummaryPerson[]>([]);
324	  // The counted claims of the sheet: each one's date and figure, as the periods total them.
325	  readonly figures = input<readonly DatedFigure[]>([]);
326	  // The status of every claim on the sheet.
327	  readonly statuses = input<readonly string[]>([]);
328	  // The reason each VOID claim on the sheet was voided with (null for none).
329	  readonly voidedWith = input<readonly (string | null)[]>([]);
330	  // How many REVIEW claims on the sheet are late against the review SLA.
331	  readonly reviewLateCount = input(0);
332	  readonly pendingLateCount = input(0);
333	
334	  // Per grade: the people on it today, leaving out retired ones, their due-totals added up, skipping n/a, and how
335	  // many of them are active.
336	  protected readonly byGrade = computed(() =>
337	    this.grades().map((grade) => {
338	      const on = this.people().filter((p) => !p.retired && p.grade === grade);
339	      return {
340	        grade,
341	        count: on.length,
342	        dueTotal: sumSkippingNa(on.map((p) => p.dueTotal)),
343	        active: on.filter((p) => p.active).length,
344	      };
345	    }),
346	  );
347	  // The id of the sheet to compare with, and the other sheet's per-grade due-totals once read (null before).
348	  protected readonly compareWith = signal('');
349	  private readonly other = signal<OtherGradeDueTotals | null>(null);
350	  // One line per grade of this sheet: its summary due-total, then the other sheet's (0.00 for a grade it has no one
351	  // on); none for a sheet that does not exist.
352	  protected readonly compareLines = computed(() => {
353	    const other = this.other();
354	    if (!other?.exists) return [];
355	    return this.byGrade().map((g) => `${g.grade} ${g.dueTotal} ${sumSkippingNa([other.gradeDueTotals[g.grade] ?? null])}`);
356	  });
357	
358	  constructor() {
359	    // A comparison belongs to the sheet it was made on.
360	    effect(() => {
361	      this.session.sheetId();
362	      this.session.loads();
363	      untracked(() => this.other.set(null));
364	    });
365	  }
366	
367	  protected value(e: Event): string {
368	    return (e.target as HTMLInputElement).value;
369	  }
370	
371	  // Reads the other sheet's per-grade due-totals; the old lines are gone while it is read.
372	  protected async compare(): Promise<void> {
373	    const id = this.compareWith().trim();
374	    this.other.set(null);
375	    if (!/^[A-Za-z0-9_.-]{1,100}$/.test(id)) return;
376	    try {
377	      const other = await firstValueFrom(
378	        this.http.get<OtherGradeDueTotals>(`/api/sheets/${encodeURIComponent(id)}/grade-due-totals`),
379	      );
380	      if (this.compareWith().trim() === id) this.other.set(other);
381	    } catch {
382	      // with nothing read, no lines show
383	    }
384	  }
385	
386	  // Per period: its due-total, and its change from the period before it by from-date (none for the earliest).
387	  protected readonly byPeriod = computed(() => {
388	    const totals = periodDueTotals(this.periods.list(), this.figures());
389	    const byFrom = [...this.periods.list()].sort((a, b) => a.from.localeCompare(b.from));
390	    const changes = new Map(
391	      byFrom.map((p, i) => {
392	        const before = i > 0 ? totals.get(byFrom[i - 1].id) : undefined;
393	        const now = totals.get(p.id);
394	        return [p.id, before !== undefined && now !== undefined ? difference(now, before) : ''];
395	      }),
396	    );
397	    return this.periods.list().map((p) => ({
398	      name: p.name,
399	      dueTotal: totals.get(p.id) ?? '',
400	      change: changes.get(p.id) ?? '',
401	    }));
402	  });
403	  // Per period: its due-total with each claim counted by its status now; a closed period keeps its fixed figure.
404	  protected readonly classicByPeriod = computed(() => {
405	    const totals = classicPeriodDueTotals(this.periods.list(), this.figures());
406	    return this.periods.list().map((p) => ({ name: p.name, dueTotal: totals.get(p.id) ?? '' }));
407	  });
408	  // The sheet's due-total with no trimming: everyone's due-total added up, skipping n/a.
409	  protected readonly classicDueTotal = computed(() => sumSkippingNa(this.people().map((p) => p.dueTotal)));
410	  protected readonly byStatus = computed(() =>
411	    STATUSES.map((status) => ({ status, count: this.statuses().filter((s) => s === status).length })),
412	  );
413	  // Per reason on the sheet's list: the VOID claims voided with it.
414	  protected readonly byVoidReason = computed(() =>
415	    this.voidReasons.list().map(({ reason }) => ({
416	      reason,
417	      count: this.voidedWith().filter((r) => r === reason).length,
418	    })),
419	  );
420	}

