70	    /** The figures of every person on a sheet, by person id in list order, and the sheet's totals. */
71	    public record Snapshot(Map<Long, Figures> people, BigDecimal claimedTotal, BigDecimal dueTotal,
72	            BigDecimal overdueTotal) {
73	    }
