75	    /**
76	     * One person of a sheet as the tree counts them: their name and aliases, their due-total (null for n/a), their
77	     * overdue-total, settled-total, open-total and cut total.
78	     */
79	    public record Member(List<String> names, BigDecimal dueTotal, BigDecimal overdueTotal, BigDecimal settledTotal,
80	            BigDecimal openTotal, BigDecimal cutTotal) {
81	    }
82	
83	    /**
84	     * Figures added up over sheets: their people (each person once, those whose names or aliases match being one),
85	     * the people's due-totals and overdue-totals trimmed once over all of them, per grade the due-totals of the people
86	     * on it today (retired people left out, n/a skipped), per status the count of claims in it, and the count of
87	     * overdue claims that count live; with every
88	     * sheet's people as members, for the totals to be worked out again with more of them.
89	     */
90	    public record Consolidated(List<Member> members, Map<String, BigDecimal> gradeDueTotals,
91	            Map<ClaimStatus, Integer> statusCounts, int overdueCount) {
92	
93	        static Consolidated empty() {
94	            return new Consolidated(List.of(), new TreeMap<>(), new EnumMap<>(ClaimStatus.class), 0);
95	        }
96	
97	        Consolidated plus(Consolidated o) {
98	            List<Member> all = new ArrayList<>(members);
99	            all.addAll(o.members);
100	            Map<String, BigDecimal> grades = new TreeMap<>(gradeDueTotals);
101	            o.gradeDueTotals.forEach((g, d) -> grades.merge(g, d, BigDecimal::add));
102	            Map<ClaimStatus, Integer> statuses = new EnumMap<>(ClaimStatus.class);
103	            statuses.putAll(statusCounts);
104	            o.statusCounts.forEach((s, n) -> statuses.merge(s, n, Integer::sum));
105	            return new Consolidated(all, grades, statuses, overdueCount + o.overdueCount);
106	        }
107	
108	        /** The people over the tree, each once: those whose names or aliases match, ignoring case, are one. */
109	        public int peopleCount() {
110	            int[] group = new int[members.size()];
111	            Map<String, Integer> byName = new HashMap<>();
112	            for (int i = 0; i < members.size(); i++) {
113	                group[i] = i;
114	                for (String n : members.get(i).names()) {
115	                    Integer j = byName.putIfAbsent(n.toLowerCase(Locale.ROOT), i);
116	                    if (j != null) {
117	                        group[root(group, i)] = root(group, j);
118	                    }
119	                }
120	            }
121	            Set<Integer> roots = new HashSet<>();
122	            for (int i = 0; i < members.size(); i++) {
123	                roots.add(root(group, i));
124	            }
125	            return roots.size();
126	        }
127	
128	        private static int root(int[] group, int i) {
129	            while (group[i] != i) {
130	                i = group[i] = group[group[i]];
131	            }
132	            return i;
133	        }
134	
135	        /** The people's due-totals (n/a skipped), trimmed once over the tree. */
136	        public BigDecimal dueTotal() {
137	            return trimmedSum(members.stream().map(Member::dueTotal).filter(Objects::nonNull).toList());
138	        }
139	
140	        /** The people's overdue-totals, trimmed once over the tree. */
141	        public BigDecimal overdueTotal() {
142	            return trimmedSum(members.stream().map(Member::overdueTotal).toList());
143	        }
144	
145	        /** The people's settled-totals, trimmed once over the tree. */
146	        public BigDecimal settledTotal() {
147	            return trimmedSum(members.stream().map(Member::settledTotal).toList());
148	        }
149	
150	        /** The people's open-totals, trimmed once over the tree. */
151	        public BigDecimal openTotal() {
152	            return trimmedSum(members.stream().map(Member::openTotal).toList());
153	        }
154	
155	        /** The people's cut totals, trimmed once over the tree. */
156	        public BigDecimal cutTotal() {
157	            return trimmedSum(members.stream().map(Member::cutTotal).toList());
158	        }
159	    }
