184	    /** The sheet's figures as the store holds them now (as the screen computes them). */
185	    public Snapshot snapshot(String sheetId) {
186	        claims.flush();
187	        Sheet sheet = sheets.findById(sheetId).orElse(null);
188	        LocalDate today = sheet == null ? null : sheet.getToday();
189	        // the rates by grade for each tier of claims by the mark they were added at; the last is the rates as they
190	        // apply on the sheet, forward-only ones included, which decide n/a today
191	        List<RateChain.Tier> tiers = rates.tiers(sheetId);
192	        Map<RateChain.Tier, Map<String, List<Rate>>> byTier = new HashMap<>();
193	        for (RateChain.Tier t : tiers) {
194	            Map<String, List<Rate>> by = new HashMap<>();
195	            for (Rate r : t.rates()) {
196	                by.computeIfAbsent(r.getGrade(), g -> new ArrayList<>()).add(r);
197	            }
198	            byTier.put(t, by);
199	        }
200	        Map<String, List<Rate>> byGrade = byTier.get(tiers.get(tiers.size() - 1));
201	        Map<Long, List<Claim>> claimsBy = new HashMap<>();
202	        for (Claim c : claims.findBySheetIdOrderByIdDesc(sheetId)) {
203	            if (c.getStatus().counts()) {
204	                claimsBy.computeIfAbsent(c.getPersonId(), id -> new ArrayList<>()).add(c);
205	            }
206	        }
207	        List<Person> listed = people.findBySheetIdOrderByPositionAscIdAsc(sheetId);
208	        // the parts of shared claims: what each holder's part of a counted claim comes to, by holder, and what the
209	        // claim's own person gives away of it, by claim
210	        Map<Long, Person> byId = new HashMap<>();
211	        for (Person p : listed) {
212	            byId.put(p.getId(), p);
213	        }
214	        Map<Long, List<Part>> partsBy = new HashMap<>();
215	        Map<Long, BigDecimal> givenBy = new HashMap<>();
216	        for (Person p : listed) {
217	            for (Claim c : claimsBy.getOrDefault(p.getId(), List.of())) {
218	                if (c.getShares().isEmpty() || !p.countsLive(c, today)) {
219	                    continue;
220	                }
221	                BigDecimal figure = liveFigure(c, p, tiers, byTier, sheet);
222	                if (figure == null) {
223	                    continue;
224	                }
225	                for (ClaimShare share : c.getShares()) {
226	                    BigDecimal part = part(c, figure, share, byId.get(share.getPersonId()), tiers, byTier, sheet);
227	                    // a part at no rate is n/a for its holder and gives nothing away
228	                    if (part == null) {
229	                        continue;
230	                    }
231	                    partsBy.computeIfAbsent(share.getPersonId(), id -> new ArrayList<>()).add(new Part(c, part));
232	                    givenBy.merge(c.getId(), part, BigDecimal::add);
233	                }
234	            }
235	        }
236	        // each person's cut total, which the cap covers along with their due-total
237	        Map<Long, BigDecimal> cutTotals = sheet != null ? poolCuts.getObject().totals(sheetId, today) : Map.of();
238	        Map<Long, Figures> figures = new LinkedHashMap<>();
239	        BigDecimal claimedTotal = ZERO;
240	        List<BigDecimal> dues = new ArrayList<>();
241	        List<BigDecimal> overdues = new ArrayList<>();
242	        for (Person p : listed) {
243	            // an open claim of a retired person counts in no live total, unless a statement binds it; nor does one
244	            // deferred on the sheet's today; a hold leaves nothing out
245	            List<Claim> counted = claimsBy.getOrDefault(p.getId(), List.of()).stream()
246	                    .filter(c -> p.countsLive(c, today)).toList();
247	            // a claim correcting another does not count toward what is claimed
248	            BigDecimal claimed = claimsBy.getOrDefault(p.getId(), List.of()).stream()
249	                    .filter(c -> p.countsClaimed(c, today) && c.getCorrects() == null)
250	                    .map(Claim::getAmount).reduce(ZERO, BigDecimal::add);
251	            BigDecimal due = ZERO;
252	            BigDecimal overdue = ZERO;
253	            BigDecimal settled = ZERO;
254	            BigDecimal splitSettled = ZERO;
255	            BigDecimal open = ZERO;
256	            int overdueCount = 0;
257	            boolean kept = false;
258	            // the grades whose rate today decides n/a: the one in force today and each counted claim's
259	            Set<String> grades = new HashSet<>();
260	            grades.add(p.gradeOn(today));
261	            for (Claim c : counted) {
262	                grades.add(p.gradeOn(c.getDate()));
263	                kept |= c.getSettledDue() != null || (c.isBound() && c.getStatedDue() != null);
264	                BigDecimal figure = liveFigure(c, p, tiers, byTier, sheet);
265	                boolean late = isOverdue(c, p, sheet, today);
266	                if (late) {
267	                    overdueCount++;
268	                }
269	                if (figure != null) {
270	                    kept = true;
271	                    // a shared claim's due-total counts the figure less its holders' parts
272	                    BigDecimal own = figure.subtract(givenBy.getOrDefault(c.getId(), ZERO));
273	                    due = due.add(own);
274	                    if (late) {
275	                        overdue = overdue.add(figure);
276	                    }
277	                    // a correction's figure counts toward no score
278	                    if (c.getStatus() == ClaimStatus.SETTLED && c.getCorrects() == null) {
279	                        settled = settled.add(own);
280	                    }
281	                    if (c.getStatus() == ClaimStatus.SETTLED) {
282	                        splitSettled = splitSettled.add(own);
283	                    } else if (c.getStatus().isOpen()) {
284	                        open = open.add(own);
285	                    }
286	                }
287	            }
288	            // the parts the person holds of others' claims count as figures of theirs
289	            BigDecimal held = partsBy.containsKey(p.getId()) ? ZERO : null;
290	            for (Part part : partsBy.getOrDefault(p.getId(), List.of())) {
291	                kept = true;
292	                due = due.add(part.figure());
293	                held = held.add(part.figure());
294	                if (part.claim().getStatus() == ClaimStatus.SETTLED && part.claim().getCorrects() == null) {
295	                    settled = settled.add(part.figure());
296	                }
297	                if (part.claim().getStatus() == ClaimStatus.SETTLED) {
298	                    splitSettled = splitSettled.add(part.figure());
299	                } else if (part.claim().getStatus().isOpen()) {
300	                    open = open.add(part.figure());
301	                }
302	            }
303	            // with no rate in force today for any of those grades and no claim with a figure (kept, or live at a
304	            // rate that has since ended), the due-total is n/a
305	            if (!kept && (today == null || grades.stream()
306	                    .allMatch(g -> Rate.inForce(byGrade.getOrDefault(g, List.of()), today) == null))) {
307	                due = null;
308	            }
309	            // the due-total is at most the cap in force on the date of their latest counted claim less their cut total
310	            if (sheet != null) {
311	                LocalDate latest = counted.stream().map(Claim::getDate).max(Comparator.naturalOrder()).orElse(null);
312	                due = sheet.capped(due, cutTotals.get(p.getId()), latest);
313	            }
314	            BigDecimal cut = cutTotals.getOrDefault(p.getId(), ZERO).setScale(2);
315	            figures.put(p.getId(), new Figures(p.getName(), claimed, due, overdue, settled, overdueCount, held,
316	                    splitSettled, open, cut));
317	            claimedTotal = claimedTotal.add(claimed);
318	            overdues.add(overdue);
319	            if (due != null) {
320	                dues.add(due);
321	            }
322	        }
323	        return new Snapshot(figures, claimedTotal, trimmedSum(dues), trimmedSum(overdues));
324	    }
