357	    /** One sheet's figures as {@link Consolidated} adds them up, as the store holds them (or as of a date, inside one). */
358	    private Consolidated sheetFigures(String sheetId) {
359	        Snapshot s = snapshot(sheetId);
360	        LocalDate today = sheets.findById(sheetId).map(Sheet::getToday).orElse(null);
361	        Map<String, BigDecimal> grades = new TreeMap<>();
362	        for (Person p : people.findBySheetIdOrderByPositionAscIdAsc(sheetId)) {
363	            Figures f = s.people().get(p.getId());
364	            String grade = p.gradeOn(today);
365	            if (p.getRetiredFrom() != null || f == null || grade == null) {
366	                continue;
367	            }
368	            grades.merge(grade, f.dueTotal() == null ? ZERO : f.dueTotal(), BigDecimal::add);
369	        }
370	        Map<ClaimStatus, Integer> statuses = new EnumMap<>(ClaimStatus.class);
371	        for (Claim c : claims.findBySheetIdOrderByIdDesc(sheetId)) {
372	            statuses.merge(c.getStatus(), 1, Integer::sum);
373	        }
374	        List<Member> members = new ArrayList<>();
375	        int overdueCount = 0;
376	        for (Person p : people.findBySheetIdOrderByPositionAscIdAsc(sheetId)) {
377	            Figures f = s.people().get(p.getId());
378	            if (f != null) {
379	                overdueCount += f.overdueCount();
380	                List<String> names = new ArrayList<>(List.of(p.getName()));
381	                names.addAll(p.getAliases());
382	                members.add(new Member(names, f.dueTotal(), f.overdueTotal(), f.splitSettledTotal(), f.openTotal(),
383	                        f.cutTotal()));
384	            }
385	        }
386	        return new Consolidated(members, grades, statuses, overdueCount);
387	    }
