389	    /**
390	     * The ids of the sheet's descendants as linked now: each sheet naming it as parent, their children, and so on, each
391	     * once and the sheet itself left out.
392	     */
393	    private List<String> descendantIds(String sheetId) {
394	        Set<String> seen = new HashSet<>(Set.of(sheetId));
395	        ArrayDeque<String> toVisit = new ArrayDeque<>(List.of(sheetId));
396	        List<String> ids = new ArrayList<>();
397	        while (!toVisit.isEmpty()) {
398	            for (Sheet child : sheets.findByParentIdOrderByIdAsc(toVisit.poll())) {
399	                if (seen.add(child.getId())) {
400	                    toVisit.add(child.getId());
401	                    ids.add(child.getId());
402	                }
403	            }
404	        }
405	        return ids;
406	    }
