412	    /**
413	     * The people of the other sheets of the sheet's whole tree (its topmost ancestor and every descendant of that, the
414	     * sheet itself left out), sheets by id and each sheet's people in list order, as the store holds them now.
415	     */
416	    @Transactional(readOnly = true)
417	    public List<TreePerson> treePeople(String sheetId) {
418	        String root = sheetId;
419	        Set<String> seen = new HashSet<>(Set.of(root));
420	        for (String up = parentOf(root); up != null && seen.add(up); up = parentOf(up)) {
421	            root = up;
422	        }
423	        List<String> tree = new ArrayList<>(List.of(root));
424	        tree.addAll(descendantIds(root));
425	        tree.remove(sheetId);
426	        Collections.sort(tree);
427	        List<TreePerson> rows = new ArrayList<>();
428	        for (String id : tree) {
429	            Snapshot s = snapshot(id);
430	            LocalDate today = sheets.findById(id).map(Sheet::getToday).orElse(null);
431	            for (Person p : people.findBySheetIdOrderByPositionAscIdAsc(id)) {
432	                Figures f = s.people().get(p.getId());
433	                rows.add(new TreePerson(id, p.getName(), p.gradeOn(today), f == null ? null : f.dueTotal()));
434	            }
435	        }
436	        return rows;
437	    }
