463	    /** The sheet-total of the people's figures: with three or more, the single highest and lowest are left out. */
464	    static BigDecimal trimmedSum(List<BigDecimal> figures) {
465	        BigDecimal sum = figures.stream().reduce(ZERO, BigDecimal::add);
466	        if (figures.size() >= 3) {
467	            sum = sum.subtract(Collections.max(figures)).subtract(Collections.min(figures));
468	        }
469	        return sum;
470	    }
