472	    /**
473	     * Records, once the change commits, a SNAPSHOT line per person with their due-total in the given snapshot, and
474	     * keeps it as the person's snapshot line for the day being left.
475	     */
476	    public void recordSnapshot(String by, String sheetId, Snapshot snapshot, LocalDate day) {
477	        for (Map.Entry<Long, Figures> e : snapshot.people().entrySet()) {
478	            Figures f = e.getValue();
479	            if (day != null) {
480	                snapshotLines.save(new PersonSnapshot(e.getKey(), day, f.dueTotal()));
481	            }
482	            audit.recordOnCommit("SNAPSHOT sheet=" + sheetId + " by=" + by + " name=" + f.name() + " due-total="
483	                    + text(f.dueTotal()));
484	        }
485	    }
