487	    /** Records, once the change commits, a SCORE line per person (in list order) with their score in the given snapshot. */
488	    public void recordScores(String by, String sheetId, Snapshot snapshot) {
489	        for (Figures f : snapshot.people().values()) {
490	            audit.recordOnCommit("SCORE sheet=" + sheetId + " by=" + by + " name=" + f.name() + " score="
491	                    + f.score().toPlainString());
492	        }
493	    }
