495	    /**
496	     * Records, once the change commits, a ROLLUP line for each person whose figures differ from the snapshot taken
497	     * before the change (a person new since then counts as changed), then a TOTALS line when the sheet's totals moved.
498	     */
499	    public void recordChanges(String by, String sheetId, Snapshot before) {
500	        Snapshot after = snapshot(sheetId);
501	        String head = " sheet=" + sheetId + " by=" + by;
502	        for (Map.Entry<Long, Figures> e : after.people().entrySet()) {
503	            Figures was = before.people().get(e.getKey());
504	            Figures now = e.getValue();
505	            if (was != null && was.claimed().equals(now.claimed()) && Objects.equals(was.dueTotal(), now.dueTotal())
506	                    && was.overdueTotal().equals(now.overdueTotal())) {
507	                continue;
508	            }
509	            audit.recordOnCommit("ROLLUP" + head + " person=" + now.name() + " claimed=" + now.claimed().toPlainString()
510	                    + " due-total=" + text(now.dueTotal()) + " overdue-total=" + now.overdueTotal().toPlainString());
511	        }
512	        if (!before.claimedTotal().equals(after.claimedTotal()) || !before.dueTotal().equals(after.dueTotal())
513	                || !before.overdueTotal().equals(after.overdueTotal())) {
514	            audit.recordOnCommit("TOTALS" + head + " claimed-total=" + after.claimedTotal().toPlainString()
515	                    + " due-total=" + after.dueTotal().toPlainString() + " overdue-total="
516	                    + after.overdueTotal().toPlainString());
517	        }
518	        recordAlerts(head, sheetId, before, after);
519	    }
520	
521	    /** Records, once the change commits, a ROLLUP line for every person on the sheet, then its TOTALS line. */
522	    public void recordAll(String by, String sheetId) {
523	        Snapshot now = snapshot(sheetId);
524	        String head = " sheet=" + sheetId + " by=" + by;
525	        for (Figures f : now.people().values()) {
526	            audit.recordOnCommit("ROLLUP" + head + " person=" + f.name() + " claimed=" + f.claimed().toPlainString()
527	                    + " due-total=" + text(f.dueTotal()) + " overdue-total=" + f.overdueTotal().toPlainString());
528	        }
529	        audit.recordOnCommit("TOTALS" + head + " claimed-total=" + now.claimedTotal().toPlainString() + " due-total="
530	                + now.dueTotal().toPlainString() + " overdue-total=" + now.overdueTotal().toPlainString());
531	        recordAlerts(head, sheetId, null, now);
532	    }
533	
534	    /**
535	     * Records, once the change commits, an ALERT line (in list order) for each person whose due-total went from at or
536	     * below the sheet's alert threshold (or n/a, or not yet on the sheet) to above it; none while the threshold is off.
537	     */
538	    private void recordAlerts(String head, String sheetId, Snapshot before, Snapshot after) {
539	        BigDecimal threshold = sheets.findById(sheetId).map(Sheet::getAlertThreshold).orElse(null);
540	        if (threshold == null) {
541	            return;
542	        }
543	        for (Map.Entry<Long, Figures> e : after.people().entrySet()) {
544	            Figures was = before == null ? null : before.people().get(e.getKey());
545	            Figures now = e.getValue();
546	            if (above(now, threshold) && !above(was, threshold)) {
547	                audit.recordOnCommit("ALERT" + head + " name=" + now.name() + " due-total=" + text(now.dueTotal()));
548	            }
549	        }
550	    }
551	
552	    private static boolean above(Figures f, BigDecimal threshold) {
553	        return f != null && f.dueTotal() != null && f.dueTotal().compareTo(threshold) > 0;
554	    }
555	
556	    /** A holder's part of a shared claim: the claim, and what the holder's part of it comes to. */
557	    private record Part(Claim claim, BigDecimal figure) {
558	    }
559	
560	    /**
561	     * A holder's part of a counted shared claim with the figure. A settled or bound claim keeps its parts as frozen: its
562	     * figure times the share divided by 100, rounded half to even. Otherwise the claim's amount times the share divided
563	     * by 100, times the rate the holder's own grade in force on the claim's date has (in the tier of its added mark)
564	     * divided by 100, rounded like the claim; null (n/a) when that grade has no rate.
565	     */
566	    private static BigDecimal part(Claim c, BigDecimal figure, ClaimShare share, Person holder,
567	            List<RateChain.Tier> tiers, Map<RateChain.Tier, Map<String, List<Rate>>> byTier, Sheet sheet) {
568	        if (c.getSettledDue() != null || c.isBound()) {
569	            return figure.multiply(share.getShare()).movePointLeft(2).setScale(2, RoundingMode.HALF_EVEN);
570	        }
571	        Map<String, List<Rate>> claimRates = byTier.get(tiers.stream()
572	                .filter(t -> t.upTo() == null || c.getAddedMark() <= t.upTo()).findFirst().orElseThrow());
573	        String grade = holder == null ? null : holder.gradeOn(c.getDate());
574	        Rate rate = grade == null ? null : Rate.inForce(claimRates.getOrDefault(grade, List.of()), c.getDate());
575	        if (rate == null) {
576	            return null;
577	        }
578	        return c.getAmount().multiply(share.getShare()).multiply(rate.getPct()).movePointLeft(4)
579	                .setScale(2, sheet.roundingOn(c.getRoundsOn()));
580	    }
581	
582	    /**
583	     * The figure a counted claim of the person totals: a settled or bound claim's due as fixed or as shown when stated,
584	     * else its live due at the rate its person's grade in force on its date has (in the tier of its added mark).
585	     */
586	    private static BigDecimal liveFigure(Claim c, Person p, List<RateChain.Tier> tiers,
587	            Map<RateChain.Tier, Map<String, List<Rate>>> byTier, Sheet sheet) {
588	        Map<String, List<Rate>> claimRates = byTier.get(tiers.stream()
589	                .filter(t -> t.upTo() == null || c.getAddedMark() <= t.upTo()).findFirst().orElseThrow());
590	        BigDecimal figure = figure(c, claimRates.getOrDefault(p.gradeOn(c.getDate()), List.of()), sheet);
591	        if (c.getSettledDue() == null && !c.isBound()) {
592	            figure = ClaimService.liveDue(figure, c, p, sheet, c.getStatus().isOpen());
593	        }
594	        return figure;
595	    }
596	
597	    /**
598	     * The figure of a claim: its settled due, else the due a statement bound it to, else its rate figure (no floor),
599	     * rounded as the sheet's policy date decides for it.
600	     */
601	    private static BigDecimal figure(Claim c, List<Rate> rates, Sheet sheet) {
602	        if (c.getSettledDue() != null) {
603	            return c.getSettledDue();
604	        }
605	        if (c.isBound()) {
606	            return c.getStatedDue();
607	        }
608	        Rate rate = Rate.inForce(rates, c.getDate());
609	        return rate == null ? null : ClaimService.dueOn(c.getAmount(), rate.getPct(), sheet.roundingOn(c.getRoundsOn()));
610	    }
611	
612	    /**
613	     * Whether a claim is overdue: open (or pending), not deferred, and its due-by plus its grace (see
614	     * {@link ClaimService#lateFrom}) is before the sheet's today.
615	     */
616	    private static boolean isOverdue(Claim c, Person p, Sheet sheet, LocalDate today) {
617	        return c.getStatus().isOpen() && today != null && !c.isDeferredOn(today) && c.getDueBy() != null
618	                && ClaimService.lateFrom(c, p, sheet).isBefore(today);
619	    }
620	
621	    private static String text(BigDecimal value) {
622	        return value == null ? "n/a" : value.toPlainString();
623	    }
624	}
