24	/**
25	 * The sheet's plans. Generating makes, for each plan in the order they were added, a draft claim of its amount on
26	 * each of its plan dates up to its end and the sheet's today that has none yet, dated that day with an empty note, by
27	 * every rule of the claim form; a date the form refuses is skipped and tried again next time. A plan naming one of the
28	 * sheet's descendants makes its claims there instead, for the person of the same name, by that sheet's rules.
29	 */
30	@Service
31	public class PlanService {
32	
33	    private final PlanRepository plans;
34	    private final PersonRepository people;
35	    private final SettingsService settings;
36	    private final ClaimService claims;
37	    private final ClaimRepository claimRows;
38	    private final SheetService sheets;
39	    private final Audit audit;
40	    private final TransactionTemplate tx;
41	
42	    public PlanService(PlanRepository plans, PersonRepository people, ClaimService claims,
43	            ClaimRepository claimRows, SheetService sheets, SettingsService settings, Audit audit, PlatformTransactionManager transactions) {
44	        this.settings = settings;
45	        this.plans = plans;
46	        this.people = people;
47	        this.claims = claims;
48	        this.claimRows = claimRows;
49	        this.sheets = sheets;
50	        this.audit = audit;
51	        this.tx = new TransactionTemplate(transactions);
52	    }
53	
54	    /** The sheet's plans in the order they were added. */
55	    @Transactional(readOnly = true)
56	    public List<Plan> list(String sheetId) {
57	        return plans.findBySheetIdOrderByIdAsc(sheetId);
58	    }
59	
60	    /**
61	     * Adds a plan for the person, every so many days or monthly on a day of the month. Refused when the amount is
62	     * negative or has more than two decimals, both or neither of the interval and the day are given, the interval is
63	     * less than one day, the day is not 1 to 31, or the end is before the start.
64	     */
65	    @Transactional
66	    public Plan add(String by, String sheetId, Long personId, BigDecimal amount, LocalDate start, Integer every,
67	            Integer day, LocalDate end, String targetSheetId) {
68	        checkAmount(amount);
69	        if ((every == null) == (day == null)) {
70	            throw refused("Enter either a number of days or a day of the month.");
71	        }
72	        if (every != null && every < 1) {
73	            throw refused("Enter a whole number of days of at least 1.");
74	        }
75	        if (day != null && (day < 1 || day > 31)) {
76	            throw refused("Enter a day of the month from 1 to 31.");
77	        }
78	        if (start == null || end == null) {
79	            throw refused("Enter a start date and an end date.");
80	        }
81	        if (end.isBefore(start)) {
82	            throw refused("The end date is before the start date.");
83	        }
84	        String target = targetSheetId == null || targetSheetId.isBlank() ? null : targetSheetId.trim();
85	        if (target != null && !sheets.isDescendant(sheetId, target)) {
86	            throw refused("That sheet is not a descendant of this sheet.");
87	        }
88	        sheets.lock(sheetId);
89	        Person person = people.findByIdAndSheetId(personId, sheetId)
90	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
91	        BigDecimal scaled = amount.setScale(2, RoundingMode.UNNECESSARY);
92	        Plan saved = plans.saveAndFlush(new Plan(sheetId, personId, scaled, start, every, day, end, target));
93	        audit.recordOnCommit("PLAN_ADDED sheet=" + sheetId + " by=" + by + " name=" + person.getName() + " amount="
94	                + scaled.toPlainString() + " start=" + start + (day != null ? " day=" + day : " every=" + every) + " end=" + end
95	                + (target != null ? " sheet=" + target : ""));
96	        return saved;
97	    }
98	
99	    /**
100	     * Pauses (true) or resumes (false) the plan from the sheet's today. Refused when pausing a paused plan or resuming
101	     * a running one.
102	     */
103	    @Transactional
104	    public Plan setPaused(String by, String sheetId, Long planId, boolean paused) {
105	        sheets.lock(sheetId);
106	        Plan plan = plans.findById(planId).filter(p -> p.getSheetId().equals(sheetId))
107	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such plan."));
108	        if (plan.isPaused() == paused) {
109	            throw refused(paused ? "The plan is already paused." : "The plan is not paused.");
110	        }
111	        LocalDate today = sheets.load(sheetId).getToday();
112	        if (paused) {
113	            plan.pause(today);
114	        } else {
115	            plan.resume(today);
116	        }
117	        Plan saved = plans.saveAndFlush(plan);
118	        Person person = people.findByIdAndSheetId(plan.getPersonId(), sheetId).orElseThrow();
119	        audit.recordOnCommit((paused ? "PLAN_PAUSED" : "PLAN_RESUMED") + " sheet=" + sheetId + " by=" + by + " name="
120	                + person.getName() + " start=" + plan.getStart());
121	        return saved;
122	    }
123	
124	    /** What a change of amount made: the plan as it stands and the claims of the sheet it edited, in order. */
125	    public record AmountChanged(Plan plan, List<Claim> claims) {
126	    }
127	
128	    /**
129	     * Changes the plan's amount from the sheet's today: the claims generated from then on take it, and so do those it
130	     * made that are still drafts, each edited as the claim form would edit it after the change; those in any other
131	     * status keep theirs. Each draft is edited in a change of its own, so one the claim form refuses keeps its amount
132	     * and the others still go through. Refused when the amount is negative or has more than two decimals.
133	     */
134	    public AmountChanged changeAmount(String by, String sheetId, Long planId, BigDecimal amount) {
135	        checkAmount(amount);
136	        BigDecimal scaled = amount.setScale(2, RoundingMode.UNNECESSARY);
137	        Plan saved = tx.execute(s -> {
138	            sheets.lock(sheetId);
139	            Plan plan = plans.findById(planId).filter(p -> p.getSheetId().equals(sheetId))
140	                    .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such plan."));
141	            plan.changeAmount(sheets.load(sheetId).getToday(), scaled);
142	            Plan changed = plans.saveAndFlush(plan);
143	            Person person = people.findByIdAndSheetId(plan.getPersonId(), sheetId).orElseThrow();
144	            audit.recordOnCommit("PLAN_CHANGED sheet=" + sheetId + " by=" + by + " name=" + person.getName()
145	                    + " start=" + plan.getStart() + " amount=" + scaled.toPlainString());
146	            return changed;
147	        });
148	        String claimSheet = saved.getTargetSheetId() == null ? sheetId : saved.getTargetSheetId();
149	        if (settings.isReadOnly(claimSheet, by)) {
150	            return new AmountChanged(saved, List.of());
151	        }
152	        List<Claim> edited = new ArrayList<>();
153	        for (Long claimId : saved.getMadeClaims().stream().sorted().toList()) {
154	            try {
155	                Claim done = tx.execute(s -> {
156	                    Claim draft = claimRows.findByIdAndSheetId(claimId, claimSheet).orElse(null);
157	                    if (draft == null || draft.getStatus() != ClaimStatus.DRAFT) {
158	                        return null;
159	                    }
160	                    return claims.update(by, claimSheet, claimId, scaled, draft.getDate(), draft.getNote(),
161	                            draft.getCorrects(), draft.getRef(), draft.getTags());
162	                });
163	                if (done != null && claimSheet.equals(sheetId)) {
164	                    edited.add(done);
165	                }
166	            } catch (ResponseStatusException refused) {
167	                // the claim form refused this edit: the draft keeps its amount
168	            }
169	        }
170	        return new AmountChanged(saved, edited);
171	    }
172	
173	    /** What a generate made: the claims, in the order they were made, and every plan of the sheet as it stands. */
174	    public record Generated(List<Claim> claims, List<Plan> plans) {
175	    }
176	
177	    /**
178	     * Makes the plans' claims. Each claim is made in a change of its own, so one the claim form refuses changes
179	     * nothing and the others still go through. A user who may change nothing on the sheet makes none.
180	     */
181	    public Generated generate(String by, String sheetId) {
182	        if (settings.isReadOnly(sheetId, by)) {
183	            return new Generated(List.of(), list(sheetId));
184	        }
185	        LocalDate today = sheets.load(sheetId).getToday();
186	        List<Claim> made = new ArrayList<>();
187	        for (Plan plan : tx.execute(s -> plans.findBySheetIdOrderByIdAsc(sheetId))) {
188	            LocalDate last = plan.getEnd().isBefore(today) ? plan.getEnd() : today;
189	            for (LocalDate on : plan.datesUpTo(last)) {
190	                if (plan.hasMade(on) || plan.isSkipped(on)) {
191	                    continue;
192	                }
193	                LocalDate date = on;
194	                try {
195	                    made.add(tx.execute(s -> {
196	                        Plan current = plans.findById(plan.getId()).orElseThrow();
197	                        if (current.hasMade(date) || current.isSkipped(date)) {
198	                            return null;
199	                        }
200	                        Claim claim;
201	                        if (current.getTargetSheetId() == null) {
202	                            claim = claims.add(by, sheetId, current.getPersonId(), current.getAmount(), date, "",
203	                                    null, null, null);
204	                        } else {
205	                            // on the descendant, for the person of the same name there; none when there is no such
206	                            // person or the user may change nothing there
207	                            String target = current.getTargetSheetId();
208	                            Person named = people.findByIdAndSheetId(current.getPersonId(), sheetId).orElse(null);
209	                            Person there = named == null ? null
210	                                    : people.findBySheetIdAndNameIgnoreCase(target, named.getName()).orElse(null);
211	                            if (there == null || settings.isReadOnly(target, by)) {
212	                                return null;
213	                            }
214	                            claim = claims.add(by, target, there.getId(), current.getAmount(), date, "", null, null,
215	                                    null);
216	                        }
217	                        current.markMade(date, claim.getId());
218	                        plans.saveAndFlush(current);
219	                        return claim;
220	                    }));
221	                } catch (ResponseStatusException refused) {
222	                    // the claim form refused this date: it is tried again next time
223	                }
224	            }
225	        }
226	        made.removeIf(c -> c == null);
227	        return new Generated(made, list(sheetId));
228	    }
229	
230	    private static void checkAmount(BigDecimal amount) {
231	        if (amount == null || amount.signum() < 0 || amount.stripTrailingZeros().scale() > 2
232	                || amount.precision() - amount.scale() > 12) {
233	            throw refused("Enter an amount of at least 0 with up to two decimals.");
234	        }
235	    }
236	
237	    private static ResponseStatusException refused(String reason) {
238	        return new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT, reason);
239	    }
240	}
