 40	// The people over the tree, each once: those whose names or aliases match, ignoring case, are one.
 41	function distinctPeople(members: readonly TreeMember[]): number {
 42	  const group = members.map((_, i) => i);
 43	  const root = (i: number): number => (group[i] === i ? i : (group[i] = root(group[i])));
 44	  const byName = new Map<string, number>();
 45	  members.forEach((m, i) => {
 46	    for (const n of m.names) {
 47	      const key = n.toLowerCase();
 48	      const j = byName.get(key);
 49	      if (j === undefined) byName.set(key, i);
 50	      else group[root(i)] = root(j);
 51	    }
 52	  });
 53	  return new Set(members.map((_, i) => root(i))).size;
 54	}
