 93	// Whether a membership's dates include the day (with no day known, every membership counts).
 94	function dated(m: { from: string | null; to: string | null }, day: string | null): boolean {
 95	  return day === null || ((m.from === null || m.from <= day) && (m.to === null || day <= m.to));
