101	// Each pool that is a member of another, to the pool it is in.
102	function parents(pools: readonly PoolView[]): Map<number, number> {
103	  const parent = new Map<number, number>();
104	  for (const p of pools) for (const m of p.members) if (m.poolId !== null) parent.set(m.poolId, p.id);
105	  return parent;
106	}
