108	// How many pools deep the chain below a pool goes, the pool itself counted.
109	function height(pool: number, parent: ReadonlyMap<number, number>): number {
110	  let most = 0;
111	  for (const [child, of] of parent) if (of === pool) most = Math.max(most, height(child, parent));
112	  return most + 1;
113	}
