135	/**
136	 * Each member's cut of the pot (in cents), in member order: the pot times their share over the shares of the members
137	 * with a cut added up, rounded half to even to the cent; a retired member, one held on the sheet's today, and one
138	 * whose dates do not include it, has none (0). The remainder left by the rounding goes to the member with the smallest
139	 * non-zero cut (the latest added on a tie), or, with no non-zero cut, to the last member with a share, so the cuts
140	 * total exactly the pot; with no member left with a cut, each is 0, except that a pool whose every member is retired has no cuts at all (null).
141	 */
142	function cuts(
143	  pot: bigint,
144	  members: readonly { share: string; retired: boolean; held: boolean; out: boolean }[],
145	): bigint[] | null {
146	  if (members.length > 0 && members.every((m) => m.retired)) return null;
147	  const shares = members.map((m) => (m.retired || m.held || m.out ? 0n : BigInt(hundredths(m.share))));
148	  const of = shares.reduce((sum, h) => sum + h, 0n);
149	  if (of === 0n) return shares.map(() => 0n);
150	  const result = shares.map((h) => {
151	    const exact = pot * h;
152	    let q = exact / of;
153	    const r = (exact % of) * 2n;
154	    if (r > of || (r === of && q % 2n === 1n)) q += 1n;
155	    return q;
156	  });
157	  let to = -1;
158	  result.forEach((c, i) => {
159	    if (c !== 0n && (to < 0 || c <= result[to])) to = i;
160	  });
161	  if (to < 0) {
162	    shares.forEach((h, i) => {
163	      if (h > 0n) to = i;
164	    });
165	  }
166	  result[to] += pot - result.reduce((sum, c) => sum + c, 0n);
167	  return result;
168	}
