172	// The pools as of a day, for the store as it then stood: their crews' pools included, each member counted retired as
173	// the people then were, the totals to match, and each member's cut of the pool's pot while the pool is balanced: the
174	// pot for a pool that is a member of none, else its cut in the pool above. A member retired, or held on the day,
175	// counts toward the total but has no cut; a member whose dates do not include the day is left out entirely.
176	function shownPools(
177	  pools: readonly PoolView[],
178	  people: readonly RosterPerson[],
179	  sheetPot: string | null,
180	  today: string | null,
181	): ShownPool[] {
182	  const retired = new Map(people.map((p) => [p.id, p.retiredFrom !== null]));
183	  const held = new Set(
184	    people
185	      .filter((p) => today !== null && p.holds.some((h) => h.from <= today && (h.to === null || today <= h.to)))
186	      .map((p) => p.id),
187	  );
188	  const parent = parents(pools);
189	  const counted = new Map(
190	    pools.map((pool) => {
191	      const members = pool.members.map((m) => ({
192	        ...m,
193	        key: m.personId !== null ? String(m.personId) : `pool-${m.name}`,
194	        retired: m.personId !== null ? (retired.get(m.personId) ?? m.retired) : false,
195	        out: !dated(m, today),
196	        held: m.personId !== null && held.has(m.personId),
