200	    }),
201	  );
202	  // Each pool's cuts (in cents, in member order), or null for none; worked out top down.
203	  const cutsOf = new Map<number, bigint[] | null>();
204	  const poolCuts = (id: number): bigint[] | null => {
205	    if (cutsOf.has(id)) return cutsOf.get(id)!;
206	    const c = counted.get(id)!;
207	    let pot: bigint | null = null;
208	    const above = parent.get(id);
209	    if (above === undefined) {
210	      pot = sheetPot !== null ? cents(sheetPot) : null;
211	    } else {
212	      const i = counted.get(above)!.members.findIndex((m) => m.poolId === id);
213	      pot = poolCuts(above)?.[i] ?? null;
214	    }
