71	    /** Each person's statements on the sheet, for the people who have any. */
72	    @Transactional(readOnly = true)
73	    public List<Summary> list(String sheetId) {
74	        Map<Long, List<Statement>> by = new LinkedHashMap<>();
75	        for (Statement s : statements.findBySheetIdInOrder(sheetId)) {
76	            by.computeIfAbsent(s.getPersonId(), k -> new ArrayList<>()).add(s);
