81	    /**
82	     * Takes a statement for the person, now (as of null) or as of a date on or before the sheet's today: see
83	     * {@link #take(String, String, Long)} and {@link #takeAsOf}.
84	     */
85	    @Transactional
86	    public Summary take(String by, String sheetId, Long personId, LocalDate asOf) {
87	        return asOf == null ? take(by, sheetId, personId) : takeAsOf(by, sheetId, personId, asOf);
88	    }
