90	    /**
91	     * Takes a statement for the person: records their due-total now (late charges included) and binds each of their claims that counts to
92	     * the due it shows now, late charge included (one already bound keeps its bound due), and counts the parts they
93	     * hold of others' shared claims; a claim that does not count (as an open one dated within a hold, or a deferred one) is freed (live again).
94	     */
95	    @Transactional
96	    public Summary take(String by, String sheetId, Long personId) {
97	        Person person = people.findWithLockByIdAndSheetId(personId, sheetId)
98	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
99	        Sheet sheet = sheets.load(sheetId);
100	        LocalDate today = sheet.getToday();
101	        RollupService.Snapshot before = rollup.snapshot(sheetId);
102	        BigDecimal total = BigDecimal.ZERO.setScale(2);
103	        boolean kept = false;
104	        // the grades whose rate today decides n/a: the one in force today and each counted claim's
105	        Set<String> grades = new HashSet<>();
106	        grades.add(person.gradeOn(today));
107	        int count = 0;
108	        // the cap held to is the one in force on the date of the latest claim that counts
109	        LocalDate latest = null;
110	        for (Claim c : claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId)) {
111	            if (!person.countsLive(c, today)) {
112	                c.unbind();
113	                continue;
114	            }
115	            // a settled or already bound claim keeps its figure even with no rate in force today
116	            grades.add(person.gradeOn(c.getDate()));
117	            latest = latest == null || c.getDate().isAfter(latest) ? c.getDate() : latest;
118	            kept |= c.getSettledDue() != null || (c.isBound() && c.getStatedDue() != null);
119	            // the statement binds the due as shown, late charge and floor included; a bound one stays as it is
120	            BigDecimal due = claimService.due(sheetId, person, c);
121	            c.bind(due);
122	            count++;
123	            if (due != null) {
124	                kept = true;
125	                total = total.add(due);
126	            }
127	        }
128	        // the parts the person holds of others' shared claims count, as on screen
129	        RollupService.Figures figures = before.people().get(personId);
130	        if (figures != null && figures.heldTotal() != null) {
131	            kept = true;
132	            total = total.add(figures.heldTotal());
133	        }
134	        claims.flush();
135	        // as on screen: with no rate in force today for any of those grades and no claim with a figure, the due-total
136	        // is n/a
137	        boolean current = grades.stream().anyMatch(g -> rates.findInForce(sheetId, g, today).isPresent());
138	        // held to the sheet's cap, as on screen
139	        BigDecimal dueTotal = current || kept ? sheet.capped(total, latest) : null;
140	        Statement taken = statements.saveAndFlush(new Statement(sheetId, personId, dueTotal, count, today, null));
141	        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + by + " name=" + person.getName()
142	                + " due-total=" + (dueTotal == null ? "n/a" : dueTotal.toPlainString()) + " claims=" + count);
143	        rollup.recordChanges(by, sheetId, before);
144	        return new Summary(personId, statements.findBySheetIdAndPersonIdInOrder(sheetId, personId));
145	    }
146	
147	    /**
148	     * Takes a statement for the person as of a date on or before the sheet's today. Their claims that counted at the
149	     * end of that date are bound to their figures as they stood then: only the changes made while the sheet's today
150	     * was on or before the date count (each claim's status, the rates, grades, settings, holds and retirement, and
151	     * the binding of the person's last statement), and the date stands in for the sheet's today in every figure. Each
152	     * other claim of theirs is freed, as a statement does. Refused for a date after the sheet's today, and for a
153	     * person added after it.
154	     */
155	    private Summary takeAsOf(String by, String sheetId, Long personId, LocalDate asOf) {
156	        Person current = people.findWithLockByIdAndSheetId(personId, sheetId)
157	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
158	        Sheet sheet = sheets.load(sheetId);
159	        LocalDate today = sheet.getToday();
160	        if (asOf.isAfter(today)) {
161	            throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_CONTENT,
162	                    "A statement cannot be taken as of a date after the sheet's today.");
163	        }
164	        if (!current.addedBy(asOf)) {
165	            throw new ResponseStatusException(HttpStatus.CONFLICT, "The person was not on the sheet on that date.");
166	        }
167	        Sheet then = sheet.asOf(asOf);
168	        Person person = current.asOf(asOf);
169	        List<RateChain.Tier> tiersThen = rates.tiersAsOf(sheetId, asOf);
170	        List<Rate> ratesThen = tiersThen.get(tiersThen.size() - 1).rates();
171	        // the binding of the person's last statement counts when it was taken while the sheet's today was on or before
172	        List<Statement> theirs = statements.findBySheetIdAndPersonIdInOrder(sheetId, personId);
173	        boolean bindingCounts = !theirs.isEmpty() && !theirs.get(theirs.size() - 1).getTakenOn().isAfter(asOf);
174	        RollupService.Snapshot before = rollup.snapshot(sheetId);
175	        BigDecimal total = BigDecimal.ZERO.setScale(2);
176	        boolean kept = false;
177	        Set<String> grades = new HashSet<>();
178	        grades.add(person.gradeOn(asOf));
179	        int count = 0;
180	        // the cap held to is the one in force on the date of the latest claim that counts
181	        LocalDate latest = null;
182	        for (Claim c : claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId)) {
183	            ClaimStatus status = c.statusAtEndOf(asOf);
184	            boolean bound = bindingCounts && c.isStated();
185	            boolean counts = status != null && status.counts() && !(c.isDeferredAsOf(asOf) && !bound)
186	                    && !(status.isOpen() && !bound && person.isRetiredOn(asOf));
187	            if (!counts) {
188	                c.unbind();
189	                continue;
190	            }
191	            grades.add(person.gradeOn(c.getDate()));
192	            latest = latest == null || c.getDate().isAfter(latest) ? c.getDate() : latest;
193	            BigDecimal figure;
194	            BigDecimal due;
195	            if (status == ClaimStatus.SETTLED) {
196	                // its due as fixed then
197	                figure = c.dueLoggedAtEndOf(asOf);
198	                due = figure;
199	                kept = true;
200	            } else {
201	                if (bound) {
202	                    // its due as bound, late charge included
203	                    figure = c.getStatedDue();
204	                    kept |= figure != null;
205	                    due = figure;
206	                } else {
207	                    due = ClaimService.liveDue(rateFigure(RateChain.forMark(tiersThen, c.getAddedMark()), then,
208	                            person.gradeOn(c.getDate()), c), c, person, then, status.isOpen());
209	                    figure = due;
210	                }
211	            }
212	            c.bind(figure);
213	            count++;
214	            if (due != null) {
215	                kept = true;
216	                total = total.add(due);
217	            }
218	        }
219	        claims.flush();
220	        boolean inForce = grades.stream().anyMatch(g -> inForce(ratesThen, g, asOf) != null);
221	        BigDecimal dueTotal = inForce || kept ? then.capped(total, latest) : null;
222	        Statement taken = statements.saveAndFlush(new Statement(sheetId, personId, dueTotal, count, today, asOf));
223	        audit.recordOnCommit("STATEMENT sheet=" + sheetId + " by=" + by + " name=" + person.getName()
224	                + " due-total=" + (dueTotal == null ? "n/a" : dueTotal.toPlainString()) + " claims=" + count
225	                + " asof=" + asOf);
226	        rollup.recordChanges(by, sheetId, before);
227	        return new Summary(personId, statements.findBySheetIdAndPersonIdInOrder(sheetId, personId));
228	    }
229	
230	    /** The grade's rate in force on the date among the rates; null with none. */
231	    private static Rate inForce(List<Rate> rates, String grade, LocalDate date) {
232	        return Rate.inForce(rates.stream().filter(r -> r.getGrade().equals(grade)).toList(), date);
233	    }
234	
235	    /**
236	     * The claim's rate figure among the rates, on the sheet as it stood: at the rate the grade has in force on its
237	     * date, rounded as the sheet decides for it; null (n/a) with none.
238	     */
239	    private static BigDecimal rateFigure(List<Rate> rates, Sheet sheet, String grade, Claim claim) {
240	        Rate rate = inForce(rates, grade, claim.getDate());
241	        return rate == null ? null
242	                : ClaimService.dueOn(claim.getAmount(), rate.getPct(), sheet.roundingOn(claim.getRoundsOn()));
243	    }
244	
245	    /**
246	     * A steward cancels the person's last statement: the claims it bound are live again (a figure an earlier
247	     * statement bound is not restored), and the statement before it is the last. Refused unless the user is a
248	     * steward, and for a person with no statement. Returns the person's statements as the cancel left them.
249	     */
250	    @Transactional
251	    public Summary cancel(String by, String sheetId, Long personId) {
252	        Person person = people.findWithLockByIdAndSheetId(personId, sheetId)
253	                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person."));
254	        if (!settings.isSteward(sheetId, by)) {
255	            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can cancel a statement.");
256	        }
257	        List<Statement> theirs = statements.findBySheetIdAndPersonIdInOrder(sheetId, personId);
258	        if (theirs.isEmpty()) {
259	            throw new ResponseStatusException(HttpStatus.CONFLICT, "There is no statement to cancel.");
260	        }
261	        Statement last = theirs.get(theirs.size() - 1);
262	        RollupService.Snapshot before = rollup.snapshot(sheetId);
263	        for (Claim c : claims.findBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId)) {
264	            if (c.isStated()) {
265	                c.unbind();
266	            }
267	        }
268	        claims.flush();
269	        statements.delete(last);
270	        statements.flush();
271	        audit.recordOnCommit("STATEMENT_CANCELLED sheet=" + sheetId + " by=" + by + " name=" + person.getName()
272	                + " due-total=" + (last.getDueTotal() == null ? "n/a" : last.getDueTotal().toPlainString()));
273	        rollup.recordChanges(by, sheetId, before);
274	        return new Summary(personId, theirs.subList(0, theirs.size() - 1));
275	    }
276	}
