244	/**
245	 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
246	 * so tests can assert side-effects by reading that file — the second test-assertion channel
247	 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
248	 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
249	 *
250	 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
251	 * SYNC) so a test reads the record immediately.
252	 *
253	 * A record of a change made by a user acting on behalf of another (see {@link OnBehalf}) ends with for=<that one>,
254	 * unless it only reports figures (ROLLUP, TOTALS, ALERT). A SNAPSHOT, written by a change of today the user makes,
255	 * carries it too.
256	 */
257	@Service
258	public class Audit {
259	
260	    /** Tells for whom a user acts on a sheet, when they act on another's behalf. */
261	    public interface OnBehalf {
262	        Optional<String> forOf(String sheetId, String user);
263	    }
264	
265	    /** The records that only report figures, which never carry for=. */
266	    private static final Set<String> FIGURES_ONLY = Set.of("ROLLUP", "TOTALS", "ALERT");
267	
268	    /** A record's event, sheet and user: its head. */
269	    private static final Pattern HEAD = Pattern.compile("^(\\S+) sheet=(\\S+) by=(.+?)(?= [a-z][a-z-]*=|$)");
270	
271	    private final Path file;
272	    private final ObjectProvider<OnBehalf> onBehalf;
273	
274	    public Audit(@Value("${app.audit.file:.run/audit.log}") String path, ObjectProvider<OnBehalf> onBehalf) {
275	        this.file = Path.of(path);
276	        this.onBehalf = onBehalf;
277	    }
278	
279	    /**
280	     * Append one audit record. Tests assert the exact line(s) in the file. A request answered as of a date changes
281	     * nothing, so it writes none.
282	     */
283	    public synchronized void record(String entry) {
284	        if (AsOfContext.active()) {
285	            return;
286	        }
287	        try {
288	            Path parent = file.toAbsolutePath().getParent();
289	            if (parent != null) {
290	                Files.createDirectories(parent);
291	            }
292	            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
293	                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
294	        } catch (IOException e) {
295	            throw new UncheckedIOException(e);
296	        }
297	    }
298	
299	    /**
300	     * Append one audit record once the current transaction commits, so a change that is refused (and
301	     * rolled back) writes nothing. Outside a transaction the record is appended at once.
302	     */
303	    public void recordOnCommit(String record) {
304	        String entry = record + onBehalfOf(record);
305	        if (!TransactionSynchronizationManager.isSynchronizationActive()) {
306	            record(entry);
307	            return;
308	        }
309	        TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
310	            @Override
311	            public void afterCommit() {
312	                record(entry);
313	            }
314	        });
315	    }
316	
317	    /** " for=<who>" when the record's user makes the change on another's behalf, as things stand now; else "". */
318	    private String onBehalfOf(String entry) {
319	        Matcher m = HEAD.matcher(entry);
320	        OnBehalf who = onBehalf.getIfAvailable();
321	        if (who == null || !m.find() || FIGURES_ONLY.contains(m.group(1))) {
322	            return "";
323	        }
324	        return who.forOf(m.group(2), m.group(3)).map(f -> " for=" + f).orElse("");
325	    }
326	
327	    /** A field of a record: its key and value, the value running to the next field or the end. */
328	    private static final Pattern FIELD = Pattern.compile("(?<=^| )([a-z][a-z-]*)=(.*?)(?= [a-z][a-z-]*=|$)");
329	
330	    /**
331	     * The records of a sheet exactly as the file holds them, newest first. With a name, only those about that person:
332	     * carrying name= or person= that name, compared as names are (case and surrounding spaces ignored).
333	     */
334	    public synchronized List<String> lines(String sheetId, String name) {
335	        if (!Files.exists(file)) {
336	            return List.of();
337	        }
338	        List<String> all;
339	        try {
340	            all = Files.readAllLines(file, StandardCharsets.UTF_8);
341	        } catch (IOException e) {
342	            throw new UncheckedIOException(e);
343	        }
344	        String key = name == null ? "" : name.strip().toLowerCase(Locale.ROOT);
345	        List<String> found = new ArrayList<>();
346	        for (String line : all) {
347	            Matcher m = HEAD.matcher(line);
348	            if (m.find() && m.group(2).equals(sheetId) && (key.isEmpty() || about(line, key))) {
349	                found.add(line);
350	            }
351	        }
352	        Collections.reverse(found);
353	        return found;
354	    }
355	
356	    /**
357	     * The sheet's activity: for every user and every event in its records, one line "<user> <EVENT> <count>", sorted
358	     * by user then event.
359	     */
360	    public synchronized List<String> activity(String sheetId) {
361	        Map<String, Map<String, Integer>> counts = new TreeMap<>();
362	        for (String line : lines(sheetId, null)) {
363	            Matcher m = HEAD.matcher(line);
364	            if (m.find()) {
365	                counts.computeIfAbsent(m.group(3), u -> new TreeMap<>()).merge(m.group(1), 1, Integer::sum);
366	            }
367	        }
368	        List<String> found = new ArrayList<>();
369	        counts.forEach((user, events) -> events.forEach((event, n) -> found.add(user + " " + event + " " + n)));
370	        return found;
371	    }
372	
373	    /**
374	     * The records of a sheet about one claim, exactly as the file holds them, newest first: with a number, those
375	     * carrying number= that number; without one, those carrying no number but naming the person (compared as names
376	     * are), the amount and the date together.
377	     */
378	    public synchronized List<String> claimLines(String sheetId, String number, String person, String amount,
379	            String date) {
380	        String key = person.strip().toLowerCase(Locale.ROOT);
381	        List<String> found = new ArrayList<>();
382	        for (String line : lines(sheetId, null)) {
383	            Map<String, String> f = fields(line);
384	            boolean about = number != null ? number.equals(f.get("number"))
385	                    : !f.containsKey("number") && f.containsKey("person")
386	                            && f.get("person").strip().toLowerCase(Locale.ROOT).equals(key)
387	                            && amount.equals(f.get("amount")) && date.equals(f.get("date"));
388	            if (about) {
389	                found.add(line);
390	            }
391	        }
392	        return found;
393	    }
394	
395	    /** A record's fields by key; the first of a key repeated. */
396	    private static Map<String, String> fields(String line) {
397	        Map<String, String> found = new HashMap<>();
398	        Matcher f = FIELD.matcher(line);
399	        while (f.find()) {
400	            found.putIfAbsent(f.group(1), f.group(2));
401	        }
402	        return found;
403	    }
404	
405	    /** Whether a record carries name= or person= the given name key. */
406	    private static boolean about(String line, String key) {
407	        Matcher f = FIELD.matcher(line);
408	        while (f.find()) {
409	            String k = f.group(1);
410	            if ((k.equals("name") || k.equals("person")) && f.group(2).strip().toLowerCase(Locale.ROOT).equals(key)) {
411	                return true;
412	            }
413	        }
414	        return false;
415	    }
416	
417	    /** Truncate the audit file. */
418	    public synchronized void clear() {
419	        try {
420	            Files.deleteIfExists(file);
421	        } catch (IOException e) {
422	            throw new UncheckedIOException(e);
423	        }
424	    }
425	}

